window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_041"]={"n":"朱诚泳","dyn":"明","poems":[{"t":"钧天曲","f":"五言古诗","c":["飞游郁罗境，稽首东王公。","开轩临法座，置酒燕灵宫。","紫云歌玉女，琼浆酌金童。","挥刀麟脯细，入箸鸾膏空。","凤箫声袅袅，鼍鼓鸣逄逄。","投壶起天笑，吹律回春融。","燕罢百神散，乐阕万舞终。","归来倚馀醉，凭虚驭刚风。"]},{"t":"折杨柳","f":"五言律诗","c":["灵州城下柳，多被官军窃。","犹馀拂地条，更苦行人折。","无复眼窥春，不见花飞雪。","今君赴玉关，将何赠离别。"]},{"t":"陇头吟","f":"七言古诗","c":["万里奔驰陇头水，日夜呜呜乱人耳。","黄沙白草两茫茫，怕听水声愁欲死。","一从结发戍凉州，铁甲磨穿已秃头。","儿孙养得谙胡语，不如陇水解东流。","几度临流磨剑首，水浊谁怜刃伤手。","何当乘隙奏肤功，笑取侯章大于斗。","肯学李陵生服降，甘饮陇水臣他方。"]},{"t":"上皇三台","f":"五言绝句","c":["沈沈漏几更，辗转不胜情。","南内凄凉处，梧桐夜雨声。"]},{"t":"杨白花","f":"古风","c":["杨白花，随风无定止。","飘然一去太无情，飞度江南几千里。","可怜落水化浮萍，浮萍无复随风起。","宫中美人连臂歌，此情不断如春水。"]},{"t":"上邪","f":"古风","c":["上邪，我欲与君相知，永久无休期。","马生角，慈乌头白。","天柱折，地维缺，华岳兀。","天地无日月，乃敢与君绝。"]},{"t":"春词 其四","f":"七言绝句","c":["海棠枝上鹊声乾，罗幕重重护晓寒。","初日半林珠露重，脆红无数压阑干。"]},{"t":"题王舜耕画 其一","f":"七言绝句","c":["翠壁丹厓淡夕曛，往来麋鹿自成群。","仙家住在空青外，只隔桃花一片云。"]},{"t":"秋夜 其二","f":"七言绝句","c":["秋声溢耳不堪听，燕坐高斋户半扃。","霁月满窗明似昼，梧桐如雨下空庭。"]},{"t":"武功道中","f":"七言律诗","c":["五原三畤隔西东，此地人言是武功。","杨柳池塘科斗水，杏花村店酒旗风。","农耕绿野春台里，客在青山罨画中。","日暮官程催去马，树头微雨正濛濛。"]},{"t":"圣君曲","f":"五言古诗","c":["圣人履天位，驭世应昌期。","宝历千年运，神京万世基。","梯航来职贡，海岳拱神祇。","常道陈中夏，仁恩洽四夷。","仪文唐制度，官属汉威仪。","气正三辰顺，年登百谷滋。","河清龟出洛，日暖凤鸣岐。","大地歌谣满，唐虞今在兹。"]},{"t":"宛转歌","f":"五言古诗","c":["夜月明行舟，琴更清女郎。","元是钟情物，风前乍听难。","为情歌宛转，此身今已亡。","于君有冥契，愿作双鸳鸯。","长太息相看，泪沾臆茫茫。","造物竟谁尸，恨不生逢王。","敬伯歌宛转，宛转悲且长。","红颜易零落，古今同一伤。"]},{"t":"明月引","f":"楚辞体","c":["青天有月兮照八荒。","银汉无云兮流素光。","平分寒暑兮变炎凉。","几人欢乐兮几悲伤。","叹明月之弗改，念人生之靡常。","或醉饱于夏屋，或困敝于康庄。","一瓢寒士，千乘侯王。","泥涂囚虏，珠翠名倡。","或安居于甲第，或流落于他乡。","百年能几，毕竟亡羊。","惟达人之知命，且对月而衔觞。"]},{"t":"江上曲","f":"五言古诗","c":["君为南越儿，妾乃东吴女。","江上一相逢，目成心已许。","与君欲相语，奈此舟中人。","到岸各分散，悠悠恨此身。","风高波浪险，极目孤篷转。","重晤良独难，万里天涯远。"]},{"t":"春游曲 其一","f":"五言绝句","c":["车马乘春出，莺花触眼新。","秋千忽飞起，故故看游人。"]},{"t":"春游曲 其二","f":"五言绝句","c":["走马章台路，红尘一骑飞。","美人招素手，楼上唤郎归。"]},{"t":"春游曲 其三","f":"五言绝句","c":["晓色分杨柳，春阴护牡丹。","王孙驰骏马，多是醉中看。"]},{"t":"春游曲 其四","f":"五言绝句","c":["新柳迎游骑，飞花趁酒瓯。","年年三二月，烂醉曲江头。"]},{"t":"春游曲 其五","f":"五言绝句","c":["楼外江山丽，城边锦绣新。","春光浓似酒，醉杀浪游人。"]},{"t":"鸡鸣曲","f":"七言古诗","c":["沈沈漏箭催残更，扶桑日出天鸡鸣。","羲和叱驭起苍震，坐令万国生光明。","角角再鸣声未已，万国祼生都唤起。","可怜驱入利名场，蝇营尽被鸡催死。","我愿人家莫畜鸡，胶胶风雨不须啼。","威凤来仪天下乐，日日窗前闻喜鹊。"]},{"t":"对酒歌","f":"古风","c":["人生埃壒内，忽忽如梦中。","三万六千日，所期安得同。","枝上花正开，风前花又落。","羲驭不我留，及时胡不乐。","君不见三闾大夫誇独醒，形容憔悴江潭行。","回风歌罢葬鱼腹，到底只留身后名。","又不见伯伦荷锸身相随，生死有命信所之。","洁身旷达两何有，毕竟得失还归谁。","荣悴升沈若翻手，千古贤愚同一朽。","昨朝绿鬓映朱颜，今日苍髯成皓首。","秋月春光不等閒，何如且罄樽中酒。","樽中酒，岂徒然，会须一饮吸百川。","白日西驰坐成夜，休问安期与偓佺。"]},{"t":"古意 其一","f":"五言古诗","c":["君好堤边柳，妾好岭上松。","堤柳吐轻絮，飞去无定踪。","不如松有操，郁郁傲寒冬。"]},{"t":"古意 其二","f":"五言古诗","c":["君好江上舟，妾好岸边树。","舟行遇风波，飘泊无常处。","何如树不移，风波自来去。"]},{"t":"楼上曲","f":"七言古诗","c":["东风吹春春欲阑，纷纷香雪梨花残。","美人倚阑娇不语，翠袖笼寒懒轻举。","尘封锦柱暗银筝，那忍弹成肠断声。","掩袂含羞抱幽怨，怕见雕梁语双燕。","蹙损双蛾思转迷，粉痕满面伤春啼。","金莲缓步下楼去，飞絮游丝荡心绪。","巫阳望断楚天遥，行雨行云在何处。"]},{"t":"远游篇","f":"五言古诗","c":["至人思远游，远游竟何之。","聊乘汗漫风，直与神仙期。","晨兴食方丈，暮归宿瑶池。","凭虚弄日月，剑佩光陆离。","渴饮九霄露，饥餐千岁芝。","平头看星斗，挥手谢尘羁。","欢忻朝帝座，指麾役灵祇。","归来驭元气，飞云亦追随。","步虚振金石，天风吹鬓丝。","两仪与终始，三光共盈亏。","茫茫尘海人，蚩蚩讵能知。"]},{"t":"苦热行","f":"七言古诗","c":["赤云喷火烧长天，蟾宫老桂飞苍烟。","金乌自恨具毛羽，白虎喘杀知谁怜。","万山烘透销青翠，四海波乾欲平地。","苍龙鳞甲隐虫蛆，竟日泥蟠嗟殄瘁。","况是南州瘴疠乡，火山炎海连天黄。","著人毒热若汤火，灼我肌肤成炙疮。","铁甲磨穿藏虮虱，万苦千辛死无日。","蛮人退去幸生还，一级微名君尚惜。"]},{"t":"渭城少年行","f":"七言古诗","c":["洛下春深柳絮飞，渭城少年应忆归。","马蹄偶入城南陌，相逢却是长安客。","为言前日发秦台，而翁传语需君来。","千门万户燕皆至，北苑南园花正开。","年少寻春须及早，挥鞭疾上长安道。","一路春光绝可怜，懵腾忽过斗城边。","两两新妆临渭水，纷纷游骑满秦川。","秦川自昔羡繁华，王孙公子争豪誇。","门开朱户星初出，燕设青楼日未斜。","倚醉联镳过戚里，九衢见者皆兴起。","玉辔摇风马更骄，斗鸡赌得肯相饶。","閒寻红粉来金市，喜听黄鹂过灞桥。","桥下倡家新酒熟，解鞍就向倡家宿。","美人纤手弄琵琶，酒边双脸蒸红霞。","黄金掷与买今夕，少年肯负秦川花。"]},{"t":"轻薄篇","f":"五言古诗","c":["末世多轻薄，轻薄良可嗤。","昂昂倚门第，行行恃先基。","金多忽贫贱，尚肯恤癃疲。","气豪蔑贤圣，讵知慕轩羲。","一餐烹九鼎，下箸犹嗟咨。","被服极纨绮，犹云匪新奇。","千金买艳妾，色衰竟弃之。","四方致名马，一蹶终见遗。","结交出肺肝，盟言日星垂。","片言苟不合，对面生嫌疑。","仲尼称匹夫，造化呼小儿。","伯阳道德小，孟轲仁义亏。","孙吴岂谙兵，卢扁岂知医。","陋兹轻薄子，宜为君子规。","薄方惊蝶翅，轻于风柳枝。","愿言执其人，为君投四夷。"]},{"t":"公子行","f":"七言古诗","c":["白面青瞳照秋水，豪华知是诸公子。","金鞍玉辔紫丝鞭，双双笑语东风里。","越罗披体试春衣，鹘似身轻马似飞。","春色薰人随处好，纵游直过妓楼西。","美人楼上亲招手，公子风流能过否。","绿杨树底繫花骢，指点银瓶来索酒。","笑将綵胜结同心，醉来一掷双南金。","翠帏锦帐恣欢谑，梦入阳台何处寻。","五更却恨鸡声早，马上归来踏芳草。","弯弓更过曲江头，争拾金丸逐飞鸟。"]},{"t":"西城路","f":"古风","c":["西城路，半是平田半坟墓。","平田渐少坟渐多，酸风苦雨泣铜驼。","百岁光阴驹过隙，营营终日将如何。","人生少年胡不乐，世间那有苏仙鹤。"]},{"t":"燕燕于飞","f":"五言律诗","c":["燕燕何处来，营巢寻旧主。","斜冲碧柳烟，低掠青芜雨。","逐絮绕回塘，衔泥过远浦。","汉灰无复然，莫效当时舞。"]},{"t":"苦哉远征人","f":"五言古诗","c":["苦哉远征人，荷戈西出秦。","以身自许国，举目谁为亲。","阴云翳落日，白草迷黄尘。","三伏不知暑，四月那见春。","射生充早食，卧草当夜茵。","风高弓力劲，霜重铁衣新。","主将号令肃，部伍催行频。","提兵誓灭敌，僇力敢顾身。","固知在家乐，宁厌行戍贫。","他日侯王贵，绘像登麒麟。"]},{"t":"秋夜长","f":"古风","c":["秋夜长，明月光，露华洗天金气凉。","寒虫候雁两何苦，声逐西风来枕傍。","彷徨披衣坐夜深，丁东又听捣衣砧。","残烛荧荧更漏静，无端万事皆萦心。"]},{"t":"遥夜吟","f":"五言绝句","c":["秋夜一何遥，灯烬炉烟灭。","低下水精帘，含情对明月。"]},{"t":"估客乐","f":"五言律诗","c":["郎船下江水，乘风疾若飞。","与侬各分袂，掩泣牵郎衣。","手拔黄金钗，临岐赠郎别。","愿郎心似金，坚持莫轻折。"]},{"t":"将军行","f":"七言古诗","c":["衔命西来专斧钺，远出萧关探虎穴。","铁骢夜踏黑河冰，金戈冷射关山月。","将军令严健儿勇，直捣长驱争鼓勇。","阴山北遁穹庐空，惟剩牛羊满丘陇。","忆昔我军多战没，风雨啾啾鬼宵哭。","于今汉将守边城，翻役官军收战骨。","露布星驰达冕旒，将军承诏独封侯。","争誇一代麒麟阁，谁念沙场万髑髅。"]},{"t":"捣衣曲","f":"七言古诗","c":["井梧叶坠金风起，满庭明月凉於水。","为念儿夫戍玉关，尘满征衣谁与洗。","我有冰缣三两疋，胼手殷勤为君织。","欲制寒衣远寄将，双杵拈来对砧石。","捣乱西风续又鸣，一声声里寓幽情。","夜深玉腕痛且困，不知露下将三更。","裁缝已就凭谁寄，走马朝来有边吏。","一行书染泪千行，寒到君边衣到未。"]},{"t":"夜宴谣","f":"七言古诗","c":["良夜沈沈宫漏促，两阶庭燎烧银烛。","上宾入座气如虹，帘外佳人面如玉。","一举飞觥累十觞，凤笙龙管声锵锵。","满堂珠翠照人眼，酒边尤物令人狂。","风动俄然银烛灭，暗中求与同心结。","红颜变色绝冠缨，壮士羞颜冷於铁。","君王一笑许终欢，保全宾客曾无难。","夜深痛醉各归去，感恩直欲倾心肝。","从来燕礼惟三爵，三爵既过多失错。","不醉无归乃所私，饮而不乱真为乐。"]},{"t":"农夫谣","f":"五言古诗","c":["我昨过农家，农夫于我陈。","嗟嗟天地间，而唯农苦辛。","春耕土埋足，夏耘汗沾巾。","秋成能几何，仅得比比邻。","老农惟二子，输边辛苦均。","大儿援灵夏，性命逐车轮。","小儿戍甘泉，身首犯边尘。","老妇卖薪去，老农空一身。","荒村绝鸡犬，四壁罄仓囷。","公家不我恤，里胥动生嗔。","鞭笞且不免，敢冀周吾贫。","我农老垂死，甘为地下人。","尚祈孙子辈，犹为平世民。"]},{"t":"树中草","f":"五言绝句","c":["草木非同气，托根犹可生。","如何兄与弟，同气却无情。"]},{"t":"独不见","f":"五言律诗","c":["举头望仙山，孤坐开水殿。","芳草自成茵，落花复如霰。","轻云逐翔鸾，绿树来新燕。","光景满目前，杳然独不见。"]},{"t":"昔思君","f":"楚辞体","c":["昔君与我兮，心契意投。","今君与我兮，云散雨收。","昔君与我兮，鱼水相宜。","今君与我兮，风马难追。","昔君与我兮，琴瑟谐和。","今君与我兮，音问蹉跎。"]},{"t":"伤思吟","f":"七言古诗","c":["碧云天末寒风起，吹乱宾鸿不成字。","远道音书那得闻，伤心滴尽相思泪。","泪痕界破腮上红，一点灵犀不可通。","惊破绿窗蝴蝶梦，月明砧杵闻丁东。","玉关此去三千里，离恨又从今日始。","自怜不及江上莲，两两红衣并头死。"]},{"t":"吴钩行","f":"五言绝句","c":["吴钩铸鬼工，锋锷耀昆铁。","游侠购千金，羌人犹未灭。"]},{"t":"壮士行","f":"五言绝句","c":["寝帐夜闻鸡，起坐气如虎。","怒发赫冲冠，拔剑灯前舞。"]},{"t":"戍妇词","f":"五言绝句","c":["奉姑妾尽孝，报君郎尽忠。","忠孝苟无愧，死生何必同。"]},{"t":"饮酒乐","f":"古风","c":["好鸟窗前宛转，春花庭外芳菲。","任我狂歌醉舞，从他兔走乌飞。"]},{"t":"春晓曲","f":"七言古诗","c":["隐隐疏钟出林杪，杜鹃啼血韶光老。","西楼残月坠咸池，香雾空濛六宫晓。","绿槐满院结春阴，锦屏银烛高堂深。","鸳鸯不暖红窗梦，虹壶玉漏声沈沈。","起来无事偏萧索，料峭东风越罗薄。","笑语丫鬟捲绣帘，一庭红雨桃花落。"]},{"t":"羽林郎","f":"五言律诗","c":["戮力收城后，承恩下紫宸。","电飞骝马疾，日绚锦袍新。","邃閤宵藏妓，长途昼杀人。","赦书终见宥，依旧佩麒麟。"]},{"t":"春夜曲","f":"五言绝句","c":["皓月明台榭，和风度管弦。","夜深诸女伴，犹自竞鞦韆。"]},{"t":"凉州词 其一","f":"七言绝句","c":["黄云漠漠接平沙，落日悲风惨暮笳。","回首长安五千里，征人若个不思家。"]},{"t":"凉州词 其二","f":"七言绝句","c":["三军辛苦觅封侯，终岁防边战不休。","何事孟佗凭斗酒，当时谈笑博凉州。"]},{"t":"相思曲","f":"古风","c":["去日春光未老，别来秋意方深。","明月寒更砧杵，丁东敲碎侬心。"]},{"t":"燉煌曲","f":"七言古诗","c":["何物蕃儿颜渥赭，生来个个能骑马。","公然剽掠恣南行，河湟戍卒尸纵横。","危城穷将呼天泣，都护不来谁救急。","身无羽翼可能飞，一纪穷荒甘受围。","万里长安无一使，丐兵回纥何时归。","懦将既诛绫易麦，一饱何辞蹈锋镝。","朝来群丑已登城，我军四面皆蕃声。","万人解甲从蕃俗，强把皮裘更我服。","每直年年寒食时，禠裘南向吞声哭。","汉将黄金空满箧，不见征西能报捷。"]},{"t":"龙支行","f":"七言古诗","c":["边地悲风声鼓角，长天万里愁云薄。","忽闻天使自天来，龙支城门聊一开。","碧眼羌儿屯且守，没蕃老兵无黑首。","马前拜问天可汗，五十年来今健否。","涕流自说山东住，结发从军隶边戍。","一自西戎侵玉关，泾陇烽烟薰两间。","汉军战死音声绝，战骨凭谁埋故山。","十中存者仅三五，哀哀泪滴龙堆土。","旃裘禦雪酪充饥，年深渐解蕃人语。","夜观北斗忆中原，每见花开思故园。","记得来时星火急，亲邻送我出前村。","凭君归报今天子，早发天兵下天水。","假若不来期速死，犹是唐家忠孝鬼。"]},{"t":"酒垆行","f":"七言古诗","c":["酒垆正在街当中，青楼锦树围香风。","美人巧笑饵行客，玉颜相映桃花红。","蛾眉瓠齿兼螓首，鞍马门前竞沽酒。","笑谑焉知日已斜，执事苍头应怨久。","西邻亦有酒垆开，谩誇竹叶浮樽罍。","效颦翻引里人去，坐令行径生莓苔。","何事人情偏好色，一见妖姬双眼侧。","五陵年少更粗豪，一掷千金宁吝惜。","西邻慎莫怨东邻，区区冷暖何须嗔。","偶然一醉各分散，俱是悠悠行路人。"]},{"t":"邯郸曲","f":"七言古诗","c":["邯郸女儿真如花，手梳云髻盘双鸦。","红裙翠袖黄金束，春山画出蛾眉绿。","芳年才及破瓜馀，除却嫦娥皆不如。","弱不胜衣体轻薄，唾花疑是珍珠落。","闷来斜倚碧纱窗，自拾青梅打飞雀。","秋千墙外有人游，隔花一见争相求。","却恨娇痴嫁人早，誓与卿卿永相好。","春风夜夜芙蓉幔，酒醒扶头厌珍馔。","锦堂鱼水日追欢，讵管流年暗中换。","比邻有女嫁农家，蚕事才成又绩麻。","日午馌田助耕作，麻丝输尽无衣著。"]},{"t":"丽情曲","f":"七言古诗","c":["庭院沈沈春昼长，云窗懒绣双鸳鸯。","阳台昨夜隔云雨，体弱不胜罗锦裳。","残妆满面朝慵洗，侍儿枕上刚扶起。","粉郎薄倖恋青楼，画出春山为谁媚。","满庭香雾湿空濛，花气薰人眼欲矇。","深掩兰房下筠箔，背面伤春双泪落。"]},{"t":"猛虎行","f":"古风","c":["落日暗深谷，酸风振孤城。","山子饥负嵎，耽耽谁敢撄。","伥鬼被渠役，地灵恣尔行。","目光夹双镜，怒尾竖一旌。","当途正择肉，依草饱食人。","於乎猛虎天所憎，假手会遣飞将军。"]},{"t":"燕歌行","f":"古风","c":["天声远振祁连北，深入穷庐追猾贼。","手提长剑光陆离，挥霍顿教天失色。","一自将兵出玉关，年年出没风尘间。","檄书只隔黑河水，狼烟近接贺兰山。","行役谁人不怀土，马上操戈冒风雨。","朝来更觉铁衣寒，怕见长天雪花舞。","冻眼茫茫冻叶腓，寒鸦无数居人稀。","巡边游骑畏逢敌，守寨尪兵愁被围。","从戎自念经年久，每与将军作留后。","里正来时为裹头，今日悠悠成白首。","自是男儿志四方，马革包尸亦何有。","匈奴未灭敢言归，独卧月明击刁斗。","营中健卒日纷纷，料得何人建大勋。","君不见牧羊人奴取侯印，汉家争说卫将军。"]},{"t":"骢马行","f":"七言古诗","c":["个马双睛湛秋水，狮子精神骊龙耳。","神奇传自渥洼来，万里奔云贡天子。","圉人控出御河堤，诏归豸史随驱驰。","九衢駊騀拥尘雾，雕鞍玉辔增光辉。","双旌引出经都市，贵戚豪门总趋避。","石崇金谷尽搜残，杨氏冰山都踏碎。","昨日天书下乌府，乘骢远入函关路。","华岳三峰亦动摇，皇天一德劳敷布。","咫尺天颜地有馀，冰清玉洁真璠玙。","一天明月照旌节，万里春风随简书。","喜是青年致身早，台端风裁惟君好。","长安门外雨初晴，送君又上长安道。","极目神京气郁葱，风生马首摇玲珑。","人间神骏恐难絷，还入天闲仗马中。"]},{"t":"巫山高次童士昂黄门韵","f":"七言古诗","c":["天接巫山碍南极，遥看十二芙蓉碧。","云雨朝来失数峰，应疑神女兴方浓。","楚人赋就几千载，浪语茫茫那有踪。","至今来往空台下，想像无人不停马。","土人犹解说襄王，荒祠空笑蛮巫假。","寂寂巫山万古青，时看石上白云生。","吁嗟丑谤竟谁雪，谩听崖头瀑布声。"]},{"t":"春宫曲","f":"七言古诗","c":["杏花庭院廉纤雨，火暖博山飞碧缕。","金笼鹦鹉晓惊寒，似隔红窗共人语。","画阑十二春迟迟，忍闻别院争弹棋。","妆罢日长无个事，华笺自写留春词。","柳带袅风成百结，海棠零落胭脂雪。","笑携女伴踏苍苔，漠漠香尘污罗缬。"]},{"t":"征妇怨","f":"五言绝句","c":["空阶寒雨零，远道西风作。","灯下制征衣，檐花和泪落。"]},{"t":"秋夜曲","f":"七言古诗","c":["梧桐一叶飞金井，唧唧虫鸣露华冷。","明月流辉入绮疏，夜深照见娉婷影。","心切辽阳在何处，千里云山渺烟树。","征鸿嘹呖度西风，恨身不逐鸿飞去。","起来独自步中庭，耿耿双星河汉横。","几回徙倚不成寐，银烛光寒摇画屏。"]},{"t":"写玉歌","f":"七言古诗","c":["砚池墨涨烟涛湿，兔颖含香扫秋碧。","九疑山隔楚天遥，湘灵夜抱琅玕泣。","生绡半幅凝雪光，罗缬捲风双袂凉。","电掣雷轰老蛟舞，月明露冷飞鸾凰。","翠拂珊瑚海波动，裁为短笛成三弄。","不胜清思逼人多，唤醒江南片时梦。"]},{"t":"寒夜吟","f":"七言古诗","c":["雪月交辉涵素影，银荷莲炬红光冷。","夜深翠被不胜寒，玉人枕上眠未安。","檐霜片落盆冰结，铜龙漏涩宫壶咽。"]},{"t":"绣思曲","f":"七言古诗","c":["碧纱如烟春昼长，玉桃花绽东风香。","小屏深坐悄无语，越罗刺到双鸳鸯。","凝神想像阳台去，心绪纷纷乱如絮。","百啭流莺和泪闻，声声正在人愁处。","宝篆烟消金鸭冷，碧云天外红轮暝。","重整残妆启镜奁，镜中怕见孤鸾影。"]},{"t":"看花唫","f":"古风","c":["寒暑恒代谢，四时迭推迁。","百年光景驹过隙，人生安得长少年。","君不见园中花，铅华不久落尘沙。","又不见晋石崇，十里锦帐围春风。","豪华安得镇常在，回首万事浮云空。","昼短夜长须秉烛，东皇明日回辕促。"]},{"t":"闻角吟","f":"七言律诗","c":["呜咽楼头暮一声，塞鸿惊起度边城。","无端吹断霜天月，多少征人不忍听。","辛苦年年留绝漠，功名何日图麟阁。","黄沙漠漠暗秦云，极目家山双泪落。"]},{"t":"待月辞","f":"七言古诗","c":["露下虚庭夜光冷，碧梧叶落秋无影。","美人凭阑耿不眠，香雾半空霏绿烟。","广寒倒蘸江湖底，睡熟姮娥呼不起。","浮云蔽我白玉盘，琼楼十二空高寒。","画屏黯淡销银烛，不管城头漏声促。"]},{"t":"短歌行","f":"古风","c":["黄河水，日夜东流无暂已。","金谷花，红芳不久委尘沙。","水流花落年华改，绿鬓朱颜肯相待。","百千万古埃壒间，贵贱贤愚有谁在。"]},{"t":"有所思怀戴松崖宪使","f":"七言律诗","c":["美人迢迢在何处，千里关山渺云树。","当时贻我珊瑚钩，箧笥珍藏宛如故。","晶光㶷耀众目惊，千金价直原非轻。","美人美人不可见，侧身东望难为情。"]},{"t":"王公上寿酒歌","f":"古风","c":["献寿觞，乐未央。","来玉帛，宣宫商。","吾皇迈汤武，吾皇齐虞唐。","遐龄嵩华久，休祚天地长。"]},{"t":"古离别","f":"五言律诗","c":["参商各两地，郁郁苦怀思。","不见回辕日，空怜执手时。","清霜疏柳脆，明月断鸿迟。","岁晏无消息，安知会晤期。"]},{"t":"登山曲","f":"五言古诗","c":["平明出门去，驱车升上头。","岚光青可掬，山色翠如流。","黄莺鸣远树，白云起深湫。","莲宫日辉辉，松观风飕飕。","猿吟窥果熟，鹿眠藉莎柔。","因怜尘世浊，翻爱山中幽。","蓬壶阻东海，羽人在丹丘。","安得驭飞凤，万里恣遨游。"]},{"t":"泾水黄","f":"古风","c":["泾水黄，泾土荒。","牧犬豕，饱豺狼，老狼摇毒势最张。","摩牙瞋目据中央，獾不敢过，羊不敢当。","老狼死，子更强，朝岐暮渭恣厥狂。","维我唐，振天纲，一鼓就擒，如水沃汤。","军前面缚魄飞扬，皮毛剥落血淋浪。","旄头落，唐日光。"]},{"t":"望行人","f":"五言律诗","c":["一自儿夫去，天涯信息稀。","无缘完破镜，空自寄寒衣。","未死魂先断，相思梦欲飞。","化作山头石，终天待尔归。"]},{"t":"梅花落","f":"五言律诗","c":["雅淡虽堪喜，飘零亦可伤。","随风翻玉笛，带雨上雕梁。","蕃将宁知味，胡儿讵识香。","吴侬缘戍久，一曲泪成行。"]},{"t":"紫骝马","f":"五言律诗","c":["旧日紫骝马，于今谁复看。","犹能随破虏，相与战呼韩。","岁久头颅老，风酸战骨寒。","新驹初堕地，眼见试金鞍。"]},{"t":"公无渡河","f":"古风","c":["朝鲜渡头晓日寒，风掀怒浪高于山。","疾鸟退飞不敢过，征夫乍见凋朱颜。","蛟蟠结，龙伏眠。","往来一相犯，俄顷碎舟船。","念此千金躯，谁能轻弃捐。","稍待风定，斯可周旋。","被发之叟晨提壶，乱流径渡将焉如。","波涛覆首竟沈溺，公乎公乎狂且愚。","蛟饮血，龙啮尸，公无渡河竟渡之。","公今既死去，我何用生为。","一曲箜篌为公死，公乎公乎知不知。"]},{"t":"鸡鸣","f":"楚辞体","c":["君家有高树，高树与云齐。","东方一以明，高树闻鸣鸡。","天下正康泰，汝将安归兮。","长安王侯第，出入通金闺。","当门设行马，隔墙闻鼓鼙。","入朝火城近，破晓天光低。","云鬟白玉钗，绿鬓黄金鎞。","美人年几许，窈窕初及笄。","君家五兄弟，蝉联荷爵圭。","十旬两聚首，金鞍映霜蹄。","玉堂醉琼液，锦队绚晴霓。","唶唶道旁士，无计同攀跻。","鸿飞遵水渚，雁栖在芦乡。","虞人巧执雁，而雁代鸿亡。","禽鸟且相代，兄弟何可忘。"]},{"t":"乌生八九子","f":"古风","c":["乌生八九子，寄栖秦氏树。","初不巢人屋，于人无所预。","奈何秦民游冶儿，林间挟弹相追随。","我肉不中登鼎俎，痴儿规我将奚为。","一弹中雏雏即死，阿母见之悲不止。","忆昔生儿谋反哺，讵料雏成今若此。","我巢元自穿岩石，弹射纷纷应莫及。","一朝邂逅秦家儿，离死毛伤真可惜。","吁嗟天地间，定数安可逃。","嗤彼机巧徒，用智徒劳劳。","上林西苑有白鹿，虞人尚得菹其骨。","万里摩天有黄鹄，后宫乃得烹其肉。","百尺深渊有鲤鱼，深钩密网取无馀。","于乎物理有修短，祸福安得移。","修俟乃君子，乐天奚复疑。"]},{"t":"青楼曲","f":"五言律诗","c":["二八娉婷女，伤春更惜春。","粉融双脸嫩，黛蹙两眉颦。","啼鸟窥歌扇，飞花落舞茵。","玉鞭催马去，肠断少年人。"]},{"t":"艳歌行","f":"五言古诗","c":["秦家有好女，婉娈字罗敷。","父怜母更惜，深闺谁敢谋。","十二初养发，十三渐知羞。","十四正垂髫，十五乃上头。","娇痴十八九，明媚擅风流。","于时嫁千乘，好合胶漆投。","夫妇两兼美，姿容万不侔。","耳珰明月珠，裙带黄金钩。","明眸剪秋水，秀色照秦楼。","飞鸟见之堕，潜鱼见之浮。","病者见之起，去者见之留。","嗤嗤多往来，人人注罗敷。","矇夫不解睹，闻声亦随游。","使君驱马来，一见意油油。","踌蹰不能去，遣吏与之谋。","黄金我所饶，而能共载不。","罗敷前谢吏，使君请归休。","罗敷自有夫，堂堂千乘侯。","使君自有妇，焉用桑中求。","夫妇贵有别，与君风马牛。","知君非浪子，妾身岂倡流。","宁将身中刃，断我舌下喉。","传言谢使君，罗敷乃罗敷。"]},{"t":"大雅行","f":"古风","c":["自恃天然貌，黄金未足悭。","丹青最是无情物，断送佳人出玉关。","中官押出归无路，泪湿琵琶面如土。","马蹄西去入毡城，惟听黄河流水声。","惆怅茫茫胡地月，清光不似汉宫明。","翻恨将军万户封，却将宫女远和戎。","堂堂可笑刘天子，世与匈奴作舅翁。"]},{"t":"湘妃吟","f":"七言古诗","c":["茫茫楚泽湘云高，泽中禽兽多鸣号。","君王猎射乐忘死，竟日驰驱无乃劳。","不见秦人剧豺虎，正恐他年作囚虏。","禽荒有戒在周书，我愿君王鉴前古。","秦人笑谈楚人哭，贱妾忍尝禽兽肉。"]},{"t":"置酒高堂上","f":"五言古诗","c":["置酒高堂上，四座皆戚戚。","炰羔且为乐，何须叹今昔。","嗟此座中人，流年多半百。","垆金几时黄，头发日夜白。","大药不可期，乌蟾苦相迫。","昨日诧人豪，今朝由鬼伯。","人生真梦幻，世事一局奕。","儿孙自儿孙，无烦广田宅。","所以置此酒，诸君宜醉适。","当筵如不饮，宁无负今夕。","生前酒一杯，身后土三尺。","达人贵知命，烂醉乃长策。"]},{"t":"君子行","f":"五言古诗","c":["君子防未然，所贵远嫌疑。","莫登权倖门，莫交寡妇儿。","权门苟栖托，终当被人訾。","孤儿一与交，将疑私乃慈。","拾尘与掇蜂，圣贤尚蒙欺。","瓜田及李下，君子当慎之。"]},{"t":"苦寒行 其一","f":"七言律诗","c":["枯桑叫号朔风急，贺兰山色朝来失。","我马冲寒势欲僵，飞雪漫天大于席。","野狐径渡河冰合，冰刃著人如剑斫。","莫讶征夫多指落，见说寒林冻杀雀。"]},{"t":"苦寒行 其二","f":"七言律诗","c":["边云压地边风猛，飞雪平铺三万顷。","蕃儿走狗更呼鹰，醉拥貂裘宁畏冷。","秦人运刍兼运粮，牛颠驴蹶车轮戕。","但愿黄河狐怕渡，三军喜气回春阳。"]},{"t":"蛾眉怨","f":"古风","c":["君不见汉家天子偏多欲，万户千门犹未足。","巍峨宝殿饰黄金，磊磈琼楼镌白玉。","个中宫女日无事，学得新翻合欢曲。","彩帐年年空御床，椒房夜夜閒红烛。","忽闻中使自天来，暗地低头笑口开。","蛾眉扶入车中去，凤诏先从马上回。","即夜承恩留侍寝，鸳鸯被拥珊瑚枕。","夜深明月上瑶台，梦回却怕窗风冷。","不意君心遽变迁，欲抛恩爱学神仙。","金盘露和蓝田玉，石井冰生泰华莲。","空闻龙辂亲封禅，何曾一接仙人面。","渭河女子乳垂寻，持斋徒感天星见。","君心多欲岂仙才，钩弋枉死谁怜哉。","王母蟠桃真浪说，争如下诏罢轮台。","琼阶人静生春草，可惜蛾眉坐中老。","五利文成竟受诛，不见刘郎上蓬岛。","宫车晚出南山去，吁嗟翻被求仙误。","灵驾飘摇不可追，惟有悲风起陵树。","人生岁月苦无多，汉宫一入成蹉跎。","楚雨湘云归昨梦，刘郎刘郎如我何。"]},{"t":"宫怨 其一","f":"七言绝句","c":["自入深宫不见人，年年花柳负青春。","君恩谩说多如雨，一滴何曾到妾身。"]},{"t":"宫怨 其二","f":"七言绝句","c":["自入春来减玉容，腰肢无力受东风。","忽闻墙外羊车过，却恨君王过别宫。"]},{"t":"宫怨 其三","f":"七言绝句","c":["珍珠帘捲隐回廊，寂寞难禁夏日长。","自恨不如双燕子，衔泥犹解出宫墙。"]},{"t":"宫怨 其四","f":"七言绝句","c":["昨宵雨过嫩凉生，金屋银屏枕簟清。","浴罢自怜香透骨，君王何事独无情。"]},{"t":"宫怨 其五","f":"七言绝句","c":["夜静深宫睡不成，井梧满耳送秋声。","三千宠爱偏遗妾，閒理寒衣厚戍兵。"]},{"t":"宫怨 其六","f":"七言绝句","c":["独拥罗衾那得眠，炉烟消尽夜如年。","恼人最是宫壶水，点点声声在耳边。"]},{"t":"宫怨 其七","f":"七言绝句","c":["门外飞花糁玉尘，天家谈笑别生春。","凤笙龙管羊羔酒，不是君王帐里人。"]},{"t":"宫怨 其八","f":"七言绝句","c":["深宫寂寂冷无春，咫尺何缘近一人。","误喜中官银钥动，朝来有例给乌薪。"]},{"t":"凤吹笙曲","f":"七言古诗","c":["当年子晋学吹笙，学得丹山两凤鸣。","只愿凌风归碧落，不图代日恋周京。","一朝邂逅浮丘子，鹤驾飘摇羾元始。","阆风玄圃友群仙，万岁千秋终不死。","七月七日天下秋，分明返憩缑山头。","世人可望不可近，空有涕泗交横流。","吁嗟我亦子晋徒，曲终逸兴凌空虚。","尘寰谪限满千岁，相与翱翔游帝都。"]},{"t":"团扇郎","f":"五言绝句","c":["团扇复团扇，皎如明月秋。","西风易憔悴，从此见郎羞。"]},{"t":"朝云曲","f":"古风","c":["巫山之高高何极，十二晴峰倚空碧，襄王一去无消息。","无消息，神不游，化为雨，滋田畴。"]},{"t":"前有一樽酒行","f":"五言绝句","c":["前有一樽酒，当筵艳绮罗。","谁能寿千岁，不饮复如何。"]},{"t":"起夜来","f":"五言绝句","c":["念远断音书，揽衣中夜起。","月明如有情，照入深闺里。"]},{"t":"从军行","f":"五言律诗","c":["少年多义气，壮志在功名。","许国千金重，捐身一羽轻。","旌旗风外捲，笳鼓月中鸣。","誓斩楼兰首，尘清万里城。"]},{"t":"游仙谣","f":"七言古诗","c":["三花珠树春云香，琼楼十二凝寒光。","灵童双吹白玉管，鹤背稳驾朝虚皇。","虚皇身著云锦裳，手持北斗斟天浆。","素娥两两鼓瑶瑟，綵軿绕绕飞鸾凰。","历览须臾遍八荒，回首更欲攀扶桑。","阆风玄圃隔尘世，海波万里空茫茫。"]},{"t":"长相思","f":"五言古诗","c":["道路远且阻，相违动逾年。","秋风一夕起，堕我池中莲。","玉关渺何许，妾心空惘然。","踌蹰坐宵境，搔首那能眠。","山高须及巅，水深须及泉。","离合谅有日，微躯当保全。"]},{"t":"竹枝词","f":"古风","c":["袅袅万竿秋影，点点二女泪痕。","试听鹧鸪声里，满川风雨黄昏。"]},{"t":"白纻辞","f":"七言律诗","c":["白纻纤纤累成疋，丝丝是妾机中织。","欲制春衫寄远人，亲向姑前弄刀尺。","衣成著意封题去，背立东风垂玉箸。","明年于役倘未归，肯惜为君裁白纻。"]},{"t":"当窗织","f":"古风","c":["当窗织，一织三太息。","水寒丝脆头绪多，唱彻午鸡宁暇食。","抛来抛去失金梭，织久奄奄手无力。","手无力，肠欲断，停梭坐对灯花烂。","阿姑并我三丈强，短尺量来夜将半。","满砌寒螀助寥落，织成知与谁人著。","遍身罗绮属名娼，缠头舞罢锦满箱。"]},{"t":"新声","f":"七言绝句","c":["花烛荧荧艳洞房，同心人醉合欢床。","拟将十索翻新曲，惭愧当年丁六郎。"]},{"t":"关山月","f":"古风","c":["关山月，居人见月伤离别。","结发从军二十年，茫茫万里音书绝。","黄沙碛里无人烟，健儿来往横戈鋋。","有时夜渡黑河水，纵横万骑乘冰坚。","千钟马湩名王醉，毡帐夜寒人不睡。","朝来下令又南侵，一曲秋笳堪堕泪。","北兵恃力南兵靡，东窜西逃知有几。","吁嗟健骨委边尘，半是春闺梦中鬼。","良人一去戍萧关，惆怅于今竟未还。","独怜今夜关山月，应照刀痕与箭瘢。"]},{"t":"洛阳道","f":"五言律诗","c":["纵横洛阳道，来往觅行踪。","宫车若流水，仗马似游龙。","戚里传灯火，侯门闻鼓钟。","何因人掷果，应为美姿容。"]},{"t":"长安道","f":"五言律诗","c":["迢遰长安道，王侯甲第多。","金张朝燕饮，许史夜笙歌。","京兆豪家富，新丰侠客过。","卖珠谁氏子，年少正婆娑。"]},{"t":"雨雪曲","f":"五言律诗","c":["风号沙塞北，雪暗玉关西。","听水谙狐迹，循山趁马蹄。","三冬边戍苦，万里塞云低。","汉节彫零尽，苏郎应未归。"]},{"t":"朱鹭","f":"古风","c":["朱鹭来，毛质好。","浴天池，戏蘋藻。","鼓咽咽，资舞纛。","将因汉德来，请以颂天保。"]},{"t":"思悲翁","f":"古风","c":["思悲翁，白蛇断。","天地炉，帝王剑。","火德炎，水德微。","谁相者，昴日鸡。","握天符，应天造。","谁其尸之耀魄宝。"]},{"t":"艾如张","f":"古风","c":["艾如张罗，黄雀几多。","雀乃高飞，其如雀何。","大雀善惊，黄口贪食。","虞人张罗，于彼路侧。","黄雀头颅，嗟谁与惜。"]},{"t":"上之回","f":"古风","c":["上之回，剪群丑。","尔跳梁，作戎首。","犯我甘泉宫，恃弓杻。","渡河来，望尘走。","如驱羊，如拉朽。","匈奴既服臣，天子千万寿。"]},{"t":"翁离","f":"古风","c":["拥离趾中营室美。","何以树之桃与李。","拥离趾中。"]},{"t":"战城南","f":"古风","c":["战城南，死城北，满地僵尸污青血。","马蹄蹀躞，骨肉狼藉。","地远无人收，乌鸢飞飞下来食。","黄沙漠漠，黑水潺潺。","日暮一回首，壮士彫朱颜。","兵事凶，战事危，匈奴桀骜谁制之。","男儿一死不足辞，古有国殇国殇良可悲。","万骨委野，封侯其谁。"]},{"t":"巫山高","f":"古风","c":["巫山高高以耸，淮水深深以迥。","我心思归，恨不奋飞。","登山无车，涉水无航。","嗟我怀人，涕下沾裳。","山高水复深，悠悠当奈何。"]},{"t":"上陵","f":"古风","c":["上陵举我头，乃见蓬莱山。","弱水三万里，云气升其间。","黄金为宫关，丹砂满原田。","麟凤若鸡犬，居人尽神仙。","我闻黄帝在位铸鼎成，有神龙，下相迎。","黄帝上天去，寿与天地并。","维我汉，炽炎德。","莅九州，朝万国。","甘露降自天，灵芝出铜池。","群仙颂天子，遐龄拟黄帝，天地永无期。"]},{"t":"将进酒","f":"古风","c":["将进酒，止三爵。","诵宾筵，陈雅乐。","醉而狂，僛僛舞。","由醉言，出童羖。","既立监，或佐史。","醉而归，乃君子。","将进酒，君莫辞，惟酒无量维制之。"]},{"t":"君马黄","f":"古风","c":["君马黄，臣马白。","二马并驱驰，共逐长安陌。","美人归以西，臣马逐轮蹄。","美人归以北，臣马追车辙。","愿逐美人保终始，不惜驽骀为君死。"]},{"t":"芳树","f":"古风","c":["彼美芳树，朝荣夕萎。","人生几何，驹隙如斯。","日月忽忽愁杀人，老不复少，实劳我心。","我心不可转，肯以浮言误。","居易以俟命，奚忧谗与妒。"]},{"t":"有所思","f":"古风","c":["有所思，乃在天之涯，海之角。","何以问遗君，赠之白玉璞。","维兹白玉璞，凿出相思心。","兹璞倏以烂，我心悠悠日以深。","相思复相思，雠之春蚕丝。","春蚕不到死，抽丝无已时。","吾固有情物，物亦有所知。","如彼比翼鸟，如彼连理枝。","比翼鸟亦死，连理枝随枯。","惟有相思情，乃与天地俱。","朝亦有所思，暮亦有所思。","天地会有尽，相思无绝期。"]},{"t":"雉子班","f":"古风","c":["雉子班，傍母飞。","羽泄泄，刷锦衣。","野有风草我所依。","陇麦青青我苦饥。","虞人乃规我肉肥。","飞鹰走狗惊合围。","嗟我性命那可希。","恨不此身逐黄鹄，一举千里，奚虑虞人为。"]},{"t":"圣人出","f":"古风","c":["圣人出，昌运开。","圣人出，元气回。","三展正，万福来。","屏奸宄，登贤才。","物熙熙，跻春台。","皇风被，遍九垓。","虽有猛士马施哉。"]},{"t":"临高台","f":"古风","c":["临高台，望四方，俯仰万里无灾祥。","今皇帝，召和气，来凤凰。","凤凰于飞，爰集爰止。","令我主，寿万年，与台相终始。"]},{"t":"远如期","f":"古风","c":["远如期，连大漠。","我师出，匈奴缚。","献功未央，陈雅乐。","昔我往，声振寥廓。","今我来，春蒸河岳。","维我汉皇帝，寿且乐。"]},{"t":"石留","f":"古风","c":["石留石留，流水滔滔，逝者如斯夫。","岁不我与，一滔滔徂。","五十无闻，与异物俱。","少不努力，徒衰老而唏吁。","嗟彼舜蹠，厥初匪殊。","尚慎旃哉，勿迷厥途。"]},{"t":"杂诗十首 其一","f":"五言古诗","c":["南山有长松，独抱参天姿。","岁晚愈苍翠，不受霜雪欺。","一贞恒自守，四序焉能移。","眷彼桃李花，灼灼迎春曦。","明媚惊众目，秾华复几时。","常恐风雨至，须臾变离披。","物性本如此，造化谁尸之。","嗟哉浮俗流，龊龊徒尔为。","安得古贞操，偃仰慰吾思。"]},{"t":"杂诗十首 其二","f":"五言古诗","c":["深闺有佳人，清姿艳且光。","美人盻秋水，联娟蛾眉长。","良玉蕴其辉，幽兰蔼其芳。","永绡制其服，明珠缀其珰。","借问谁氏子，伊其姬与姜。","非惟逞颜色，而实励冰霜。","贻我双南金，讵肯轻下堂。","谦撝固自守，曾不求煌煌。","奉帚心所甘，好合琴瑟张。","伐柯未有斧，自媒诚恐皇。","嗟嗟宿心违，辗转徒在床。","搔首起延伫，云山远相望。","音书无以托，涕泗空沾裳。"]},{"t":"杂诗十首 其三","f":"五言古诗","c":["凤鸟秉灵德，九苞璨文章。","名为希世物，出见世道昌。","稻粱非素谋，竹实乃所尝。","梧桐岂枳棘，鸣则依高岗。","虞廷闻九奏，览德斯呈祥。","吁嗟吾道微，丹山乃深藏。","䲭鸮亦何为，敢尔窥朝阳。","宵行本么䯢，顾可争辉煌。","造物杳难问，谁能复其常。","三复仲尼叹，令人徒感伤。"]},{"t":"杂诗十首 其四","f":"五言古诗","c":["长江险可逾，蜀道难可陟。","谁言周道平，而多荆与棘。","箜篌乃戈矛，卮酒为敌国。","举目睚眦间，骨肉甚仇隙。","九夷不可居，俯仰隘八极。","将欲凌风翔，恨无双羽翼。"]},{"t":"杂诗十首 其五","f":"五言古诗","c":["猛虎在深山，终日恒渴饥。","狰狞肆贪恶，居然当九逵。","一啸腥风生，白日翳阴霾。","阱槛素无备，冯妇安可羁。","姬旦久不作，兴言乃凄其。"]},{"t":"杂诗十首 其六","f":"五言古诗","c":["薰莸本不同，冰炭实相反。","华夷性苦殊，雅郑音亦远。","熟计出万全，危哉诚累卵。","鹤颈与凫足，何须较长短。","捐彼戚戚怀，履道恒坦坦。"]},{"t":"杂诗十首 其七","f":"五言古诗","c":["寒暑互相迁，二仪成气候。","真宰司化权，谁能测声臭。","松柏一以摧，居然樗栎寿。","伤哉萁豆情，载惜山木寇。","洋洋北鄙音，乱我钧天奏。","白鹤伏黄昏，寒䲭出清昼。","坐起长太息，颠倒何太缪。"]},{"t":"杂诗十首 其八","f":"五言古诗","c":["玄浆参曲蘖，太羹杂酸辛。","妖姬调古瑟，郑声乱天真。","太朴一以散，谁为葛天民。","热中殊感慨，吊古徒沾巾。","物情类如此，已矣无复陈。"]},{"t":"杂诗十首 其九","f":"五言古诗","c":["燕燕谁家女，人云难再得。","讵知乃祸水，汉火因之灭。","尤物虽可怜，往往倾人国。","于戏古哲王，所贵惟有德。","我心亦如水，女蛊安能惑。"]},{"t":"杂诗十首 其十","f":"五言古诗","c":["大钧秉元化，寒暑循无端。","至理妙不测，岂容私智观。","春风草木荣，秋霜忽凋残。","达人契斯理，所遇常自安。","如何抱阳人，能成紫火丹。","念彼穆天子，瑶池往复还。"]},{"t":"拟古 其一","f":"五言古诗","c":["女萝附长松，倚托欲终身。","愿为鱼与水，不作参与辰。","愿为鸳与鸯，不作胡与秦。","云何动隔绝，千里蒙风尘。","我有一端绮，欲持赠远人。","赠之将如何，永结平生亲。","怀思邈难即，郁郁何当伸。"]},{"t":"拟古 其二","f":"五言古诗","c":["秋高凉风厉，灏灵发清商。","井梧一以堕，昼短夜渐长。","嗷嗷过鸣雁，唧唧乱啼螀。","自起步中庭，夕露沾我裳。","沾裳岂足惜，感时空彷徨。"]},{"t":"拟古 其三","f":"古风","c":["南山有高士，栖息岩壑间。","翩翩鹤?衣，棱棱鹿皮冠。","白石煮为食，丹砂驻其颜。","我欲求其人，举头隔云烟。","苍厓千万仞，可望不可攀。","昨宵梦见之，忽然登其巅。","知我苦辛志，念我跋涉艰。","欲授长生诀，鸡鸣夜已阑。","起坐长叹息，终焉老尘寰。"]},{"t":"感寓 其一","f":"五言古诗","c":["天道一元会，默运无穷极。","四时自成岁，至诚以无息。","声臭不可闻，但见苍苍色。","福善与祸淫，应感无差忒。","所安在人爵，所贵在天德。","深居读周易，精微端可测。","畏天乃君子，忠慎期自克。","兢兢复战战，于焉保家国。"]},{"t":"感寓 其二","f":"五言古诗","c":["天道幽且远，明明谁敢欺。","勿言不吾察，日鉴恒在兹。","所以古君子，敬畏日孳孳。","出门如有见，影响真相随。","吾人贵居易，左绳右更规。","淫荒苟失度，恐为天所遗。","公旦无逸篇，卫侯抑戒诗。","愿言书诸绅，终身为我师。"]},{"t":"感寓 其三","f":"五言古诗","c":["皇天生下民，而必立之君。","端居统万国，宵旰极忧勤。","创业藉神武，守成资圣文。","功德配天地，休声光典坟。","典坟既以远，区宇时并分。","六朝及五部，割标徒纷纭。","此疆而彼界，蒸黎蒙兵氛。","干戈无时息，嗟我赤子群。"]},{"t":"感寓 其四","f":"五言古诗","c":["有天斯有地，有君斯有臣。","君臣亦天合，谁云属之人。","君者臣之亲，臣则君之邻。","微虫有蜂蚁，而人岂无伦。","不见唐虞世，五人作同寅。","不见文武时，二公为经纶。","如何衰季世，颓风竟难淳。","全躯保妻子，临危谁致身。"]},{"t":"感寓 其五","f":"五言古诗","c":["茫茫元会间，造化竟谁尸。","昏旦既不爽，寒暑无或移。","至诚本无息，庶类自蕃滋。","日月相代明，阴阳岂参差。","岳山坯厥气，江河分厥支。","雷霆布厥威，风雨行厥时。","圣人今在上，天心与相宜。","八万六千岁，悠悠无尽期。"]},{"t":"感寓 其六","f":"五言古诗","c":["吾闻帝王世，人文日以宣。","间尝读其书，抚卷思茫然。","三王莫之尚，五帝不可前。","征伐与禅让，仁义岂偏全。","光明烛幽远，心法垂简编。","群生乐熙皞，九州无倒悬。","帝王日以远，明哲徒拳拳。","恭惟我皇祖，绳武三千年。"]},{"t":"感寓 其七","f":"五言古诗","c":["丹山有威凤，哕哕集梧冈。","竹实苟不饱，丹山复回翔。","所以古明君，求贤日遑遑。","玄纁走千里，徵车驰四方。","伊尹起有莘，太公兴渭阳。","傅说奋版筑，孔明出荆襄。","扶持赖三寿，声名高百王。","用贤乃如此，时君当不忘。"]},{"t":"感寓 其八","f":"五言古诗","c":["兹晨忽不乐，抚膺多可伤。","披书感前事，令我涕沾裳。","凤鸾止荆棘，䲭鸮据梧冈。","驺虞不饱肉，豺狼厌肥羊。","人龙困田野，人猫登庙堂。","倒颠有如此，天下安所望。","吁嗟汉唐宋，参会何纷攘。","载读虞书篇，千古心遑遑。"]},{"t":"感寓 其九","f":"五言古诗","c":["南国有佳人，温其颜如玉。","我欲往从之，白驹在空谷。","斯人不可招，泥涂讵能辱。","去往本无心，飘飘若黄鹄。","我思日以深，玄纁谩成束。","掉头不肯顾，悠悠我衷曲。","清时足大行，胡为自彳亍。","念彼采芝歌，独坐恒忽忽。"]},{"t":"感寓 其十","f":"五言古诗","c":["吕政多遗金，商辛多羡财。","鹿台与嬴藏，一炬飞烟埃。","吾思古贤君，所贵在贤才。","贤才足资世，金玉安用哉。","此理固易晓，彼狂迷莫回。","鸡鸣起孳孳，为利日徘徊。","会田有齐魏，斗宝生嫌猜。","四臣照千里，魏惠颜如灰。"]},{"t":"感寓 其十一","f":"五言古诗","c":["我观天下山，一一坯造化。","峥嵘各擅名，而谁肯相下。","巍巍五岳中，崇高维泰华。","一掌入云霄，日月真可借。","冲天几万寻，恍惚来灵驾。","冰雪四时寒，三庚讵知夏。","嗟予夙好奇，藩维况多暇。","扪参试一登，玉姜莫深讶。"]},{"t":"感寓 其十二","f":"五言古诗","c":["神龟曾出洛，凤凰亦鸣岐。","灵物岂虚来，解后文明时。","羲文既以远，元气日以衰。","虽有麟与凤，致之者为谁。","嗟嗟仲尼氏，栖栖良足悲。","获麟竟遭毙，识者空涟洏。","嗤彼五胡世，祯祥何所期。","苍麟驾鼓车，天道真嗤嗤。"]},{"t":"感寓 其十三","f":"五言古诗","c":["放勋结茅茨，神禹卑宫室。","吁嗟古圣人，安居保终吉。","奈何秦汉来，万邦困据拮。","山林穷斧斤，门户罄丹漆。","阿房未及成，建章亦以毕。","雕镌竞淫巧，回首竟萧瑟。","夜眠庸几何，小轩取容膝。","睡美五更钟，晓窗踏红日。"]},{"t":"感寓 其十四","f":"五言古诗","c":["嗟嗟今古人，滔滔迷女色。","焉知粉触髅，亡身更亡国。","妲已商纣危，褒姒周幽惑。","西施吴子亡，太真三郎踣。","于维高世王，持身能自克。","宠姬欲同辇，无宁亏盛德。","予心本冲素，万虑恒自息。","深居养太和，于焉趋寿域。"]},{"t":"感寓 其十五","f":"五言古诗","c":["伏羲抚云泉，神明钦厥德。","大舜鼓南薰，斯民愠皆绝。","谁云古乐淡，清和见天则。","曾闻凤格韶，感应妙难测。","吁嗟后世人，淫声相蛊惑。","唐皇亲羯鼓，梨园乐无极。","霓裳欲何为，一舞遂亡国。","我耳厌喧阗，端居守渊默。","窗前披乐书，古道已荆棘。"]},{"t":"感寓 其十六","f":"五言古诗","c":["茫茫一元化，二气乃屈伸。","万物生其间，悉含天地仁。","虎狼之父子，蜂蚁之君臣。","雎鸠之夫妇，鸿雁之主宾。","物且具人性，愧此蚩蚩民。","谁知禽与兽，亦能出其伦。","禽中则有凤，兽中亦有麟。","人而反乎此，焉用名为人。"]},{"t":"感寓 其十七","f":"五言古诗","c":["天地生万物，意思本自嘉。","奈何当世人，玩好竞浮誇。","隋君恣厥狂，宸游日以奢。","龙舟走千里，贪彼维扬花。","宋徽蹈覆辙，黄杨致天涯。","吁嗟花石纲，江淮尽虎蛇。","炀亡徽北狩，回首白日斜。","唐人牡丹地，相传能几家。"]},{"t":"感寓 其十八","f":"五言古诗","c":["我家有美玉，人言出昆冈。","清姿温且润，素质坚以刚。","珊瑚让精彩，水精失辉光。","玉人一入手，珍重无时忘。","琢磨借沙石，切磋付刀铓。","雕镌制瑚琏，专攻作圭璋。","神明许相与，君子良可方。","但恐珷玞混，弃置令人伤。"]},{"t":"感寓 其十九","f":"五言古诗","c":["神仙驻何许，传闻在蓬莱。","沉沉白玉宫，隐隐青莲台。","弱流不可渡，万里无飞埃。","自非鹤背仙，凭虚讵能来。","安期不死药，王母流霞杯。","天地许同寿，日月宁相催。","我生竟茫昧，自愧非仙才。","至人不可遇，且酌黄金罍。"]},{"t":"感寓 其二十","f":"五言古诗","c":["三代日以远，至治不可追。","我尝读前史，抚卷心伤悲。","炎刘崇伯术，李唐竟沦夷。","女祸世所耻，和蕃人共嗤。","逮兹赵宋氏，兵力苦不支。","委靡不复振，甘为异国欺。","明明我皇祖，仗钺驱熊貔。","一怒九围定，百世今熙熙。"]},{"t":"感寓 其二十一","f":"五言古诗","c":["绝代有佳人，优游在空谷。","渴饮涧中泉，饥餐岩下菊。","穷居养贞白，衡门擅幽独。","如何治平世，长往不肯复。","劝尔脱麻衣，为君挂朝服。","山灵莫见疑，公家正悬禄。","丈夫贵雄飞，胡为自雌伏。","登车早幡然，无苦恋黄犊。"]},{"t":"感寓 其二十二","f":"五言古诗","c":["乾坤乖气薄，阴阳镇差乱。","重雾结重阴，漫漫不知旦。","幽岩木魅栖，深谷鬼车唤。","百怪恣纵横，群阴郁无散。","阳乌忽东生，沧溟涌霄汉。","赫赫破顽云，潜回若冰泮。","须臾障碍消，悠远天文焕。","万国属皇明，寰海同灿灿。"]},{"t":"感寓 其二十三","f":"五言古诗","c":["深山有蛇虎，晴原多凤麟。","凤麟真快睹，蛇虎不可亲。","虎蛇有馀毒，近之噬吾身。","凤麟乃灵瑞，致之苦无因。","我尝读古书，于焉求屈伸。","昏昏苟不察，贻患将无垠。","閒居感畴昔，用舍怨因循。","蛇虎既难近，远之诚在人。"]},{"t":"感寓 其二十四","f":"五言古诗","c":["有初必有终，有日必有夜。","天运自循环，阴阳交代谢。","曾闻古仙人，云霄远凌跨。","死生亦常理，谁惟天所赦。","吁嗟老佛徒，蚩蚩思久假。","贪迷竟何如，而徒陷虚诈。","所以君子儒，安焉老田舍。","修身以俟之，万物还元化。"]},{"t":"感寓 其二十五","f":"五言古诗","c":["吾观三王世，有周承夏商。","贤圣相继作，享国何久长。","自从周赧来，天命苦不常。","兴戎凭诈力，王图讵能昌。","嬴秦才二世，阿房火咸阳。","六朝并五代，纷纷日更张。","皇天眷吾祖，继宋高百王。","绳绳千万年，神器传无疆。"]},{"t":"感寓 其二十六","f":"五言古诗","c":["吾闻贤后妃，有周不可当。","太姜及任姒，世德传无疆。","如何至后世，宫闱多滥觞。","吕武恣淫虐，纷纷多色荒。","我家配圣祖，圣后并姬姜。","仁孝实继之，辅治声洋洋。","徽音允相嗣，帝道日以昌。","嗟嗟我圣善，子孙焉敢忘。"]},{"t":"感寓 其二十七","f":"五言古诗","c":["齐桓假仁义，晋文亦如之。","纷纷战国君，剧戏真小儿。","美哉汉东平，为善日孳孳。","三监与七国，国亡身亦隳。","李唐不足道，诸王恣豪痴。","淫荒讵知耻，俗乐手所持。","嗟予固无似，嗣秦沗藩维。","愿言崇令德，刘苍其我师。"]},{"t":"感寓 其二十八","f":"五言古诗","c":["舜有臣五人，而天下乃治。","武王资十乱，承商履天位。","嗟彼夘金刀，凭谁和鼎味。","创始藉萧曹，守成推丙魏。","李唐虽小康，贤才亦云萃。","杜房兼宋姚，绳绳赖无坠。","我思古良臣，班班犹可记。","相望佐无为，诸公真了事。"]},{"t":"感寓 其二十九","f":"五言古诗","c":["两间有安宅，安宅我所居。","四方有正路，正路我所如。","安宅固非小，正路岂其迂。","夫何当世人，而自与之疏。","安宅蔽草莽，蚩蚩莫之除。","正路塞荆棘，茫茫谁与锄。","执迷若不解，旁观但踟蹰。","此道真窅然，吾人当体诸。"]},{"t":"感寓 其三十","f":"五言古诗","c":["公车有千乘，出则如云随。","所居能几何，焉用千乘为。","名马致千里，奔趋若星驰。","所守仅吾封，乘此将安之。","我尝陋周制，金玉岂其仪。","过奢诚易败，商车乃为宜。","汉皇征大宛，将士实乘危。","嗟嗟天马歌，徒为千载嗤。"]},{"t":"感寓 其三十一","f":"五言古诗","c":["吾闻有熊氏，古风始更张。","裹缠兼布革，上下易衣裳。","三代自有制，后来渐荒唐。","诡异骇群目，轻薄移四方。","锦章夺天巧，罗衣斗时装。","广袖全疋帛，长裙欲飞扬。","服妖古所忌，不衷真不祥。","城中苟知禁，天下当循常。"]},{"t":"感寓 其三十二","f":"五言古诗","c":["吾闻古圣君，而惟饭土簋。","仲尼大圣人，饮蔬食饮水。","箪瓢困颜氏，至乐谁能拟。","曾参亦可人，恒饥宁愿仕。","嗟嗟后世人，口腹斗珍美。","万钱充一箸，豪奢浩无纪。","烹羔宰肥牛，杯盘动盈几。","太仓日五升，何如安汝止。"]},{"t":"感寓 其三十三","f":"五言古诗","c":["仪狄昔为酒，大禹乃绝之。","维狂鉴周诰，抑戒惩卫诗。","岂惟戕性命，抑且丧威仪。","一语苟不合，兵刃手所持。","不见夏之桀，昏默沈酒池。","不见隋之炀，口不离酒卮。","二君今已矣，后世尤多迷。","亡身更亡国，智者应自知。"]},{"t":"感寓 其三十四","f":"五言古诗","c":["人生期百年，百年能几何。","逝者不可追，将来苦无多。","向来黄小群，玄发忽以皤。","古人亦有言，流光一掷梭。","大禹乃圣人，竞辰惧閒过。","亦有运甓老，而肯甘婆娑。","勤苦既如此，令名终不磨。","吁嗟当世人，其谁不蹉跎。"]},{"t":"感寓 其三十五","f":"五言古诗","c":["混沌既以死，征伐不可无。","圣人奉天命，元后授阴符。","蚩尤叛臣节，涿鹿真囚俘。","上干轩辕讨，百灵乃相扶。","桀纣逆人理，汤武布神谟。","周兴商乃蹶，汉起嬴斯殂。","至仁伐不仁，民徯后来苏。","诸王互征战，七国多贪夫。"]},{"t":"感寓 其三十六","f":"五言古诗","c":["万物有禽兽，生意亦自均。","荒夫苦畋猎，但欲膏其唇。","车网遍原野，百里践飞尘。","焚射纵鹰犬，暴殄积如薪。","我观车攻诗，古意犹可申。","后来竞驰骋，无乃劳其民。","穷搜尽巢穴，入口未必珍。","汤网去三面，诸侯归至仁。"]},{"t":"感寓 其三十七","f":"五言古诗","c":["商辛苛聚敛，货财溢台屋。","吕政灭诸侯，金刀折车轴。","董卓据郿坞，石崇擅金谷。","王戎亲较筹，萧宏广营蓄。","吁嗟射利徒，劳心何仆仆。","安知铜臭讥，讵惜钱愚恧。","障尘锦十里，买妾珠三斛。","金钱竟何为，而终遭杀戮。","吾观颜渊氏，薄田继饘粥。","箪瓢有馀乐，富贵真碌碌。"]},{"t":"感寓 其三十八","f":"五言古诗","c":["古人拙已甚，今人巧何多。","古意竟不存，纷纷将奈何。","嗤彼当世人，斗智互砻磨。","眼前移造物，胸中铸干戈。","权门讵云远，一径即能过。","天门谁谓高，攀缘手堪摩。","巧人固多事，有如茧中蛾。","茧成身自锢，拙者频笑歌。"]},{"t":"感寓 其三十九","f":"五言古诗","c":["西川恃重险，而人谁敢窥。","征西裹毡入，蜀人竟难支。","东吴倚三江，汹涌乃天为。","楼船焚缆下，吴人亦离披。","维险不可恃，维贤为可资。","舟中皆敌国，君人当慎之。"]},{"t":"感寓 其四十","f":"五言古诗","c":["相君椒百斛，领军鞋一屋。","为利日孳孳，而心苦无足。","贪夫诚可憎，佩钥声相触。","匹骑按田园，弄筹计鱼肉。","营营趁市墟，贸贸涉川陆。","剥削尽锱铢，悭涩及饘粥。","恨不马重驹，恨无牛两犊。","恨不青蚨钱，日往还相逐。","家藏万镒金，身为九州牧。","贪夫正如此，一笑聊捧腹。"]},{"t":"感寓 其四十一","f":"五言古诗","c":["假兵车者伯，以仁义者王。","诚伪迥不同，而人自圣狂。","汤以七十里，至德闻四方。","文王以百里，殷人何可当。","小足以制大，弱可以制强。","人心一以归，天命自有常。","试观伯者民，驩虞气洋洋。","齐桓晋文事，十世忽以亡。","何如王者民，皞皞莫能量。","百世既以远，仁恩讵能忘。","我尝阅书史，浩然兴慨慷。","因之识天德，王者其永昌。"]},{"t":"感寓 其四十二","f":"五言古诗","c":["有国有家者，知人实为艰。","知人竟何为，乃在用舍间。","宵人不可用，用则秽清班。","君子不可舍，舍则槁空山。","子瑕据津要，伯玉甘退閒。","孰知贤不肖，治乱诚所关。","凤凰览德辉，一去不肯还。","豺狼卧当道，令我涕潺湲。"]},{"t":"感寓 其四十三","f":"五言古诗","c":["吾闻君人者，奔走天下士。","进退手所操，谁云无所事。","祥麟不苟出，妖狐足儇利。","吁嗟进退间，而诚关至治。","何物鬼蜮徒，貌陋据台位。","奸邪惑帝聪，子仪徒自恚。","而亦有人猫，月堂运深智。","李适日衔杯，九龄亦趍避。","朝中有君子，四方君子至。","君看权倖门，群儿竞投刺。"]},{"t":"感寓 其四十四","f":"五言古诗","c":["仲尼主子瑕，卫卿非所惜。","孟轲媚臧仓，齐卿斯煖席。","俗论真可鄙，圣贤能自择。","富贵等浮云，台钧亦陈迹。","茅茨乃广居，衡门实安宅。","箪瓢敌钟鼎，乞求竟何益。","声色不我移，刀锯不我迫。","居易以俟命，玩味庖羲易。"]},{"t":"感寓 其四十五","f":"五言古诗","c":["吁嗟兹世人，居官多老饕。","孜孜慕名位，焉知奔竞劳。","权门炙手热，冰山与天高。","绥绥乞昏夜，白日矜所遭。","相君喜松寿，凉州博葡萄。","好官我自为，笑骂空嘲嘈。","君看柄臣第，车马何滔滔。","幽人方寂寞，闭门读离骚。"]},{"t":"感寓 其四十六","f":"五言古诗","c":["曾闻黄河水，远自天上来。","万流会东海，滔滔极蓬莱。","又闻瞿塘峡，惊涛吼春雷。","人愁滟滪险，奔流若山摧。","有熊作舟楫，神灵济颠颓。","千里在俄顷，转折真奇哉。","巨舰苦难运，聊横小水隈。","丁夫且休息，南风殊未回。"]},{"t":"感寓 其四十七","f":"五言古诗","c":["茫茫天地间，而理固有常。","云胡当世人，行险恣猖狂。","周行舍不由，捷径恣翱翔。","法言乃不道，群居肆荒唐。","啖葛诳天下，饮鸩欺四方。","指鹿乃言马，问牛翻问羊。","阴邪莫能测，诡异何可当。","勿云不吾察，天理恒日章。","吁嗟君子儒，灵台自开张。","作事贵昭著，宁惭天日光。"]},{"t":"感寓 其四十八","f":"五言古诗","c":["庄生寄傲者，閒居著南华。","浮辞逞虚诞，寓言恣喧哗。","操戈击夫子，盗蹠翻见誇。","三王未足论，五帝讵为嘉。","睥睨小天地，言谈多险邪。","猖狂如所言，万物其泥沙。","吾儒自有经，典谟浩无涯。","至诚乃君子，宜其辅邦家。"]},{"t":"感寓 其四十九","f":"五言古诗","c":["造化有常理，反之则为妖。","幻人有奇术，橐钥如手操。","禽兽解歌舞，金石乃鸣跳。","海水咒可竭，岳山祈可摇。","铜盘出江鲤，土盆长灵苗。","羝羊作人语，井钱若榆飘。","或缩地远游，或凭虚入朝。","蒸沙可为糜，嘘气即为飙。","黄金自融成，白雪凝不消。","撒豆化赤衣，投筇作虹桥。","纷纷妖异事，我心实不挠。","吾儒有正术，百怪当自消。"]},{"t":"感寓 其五十","f":"五言古诗","c":["二气有清浊，化工应使然。","重浊乃为地，轻清则为天。","人物各分类，参差难比肩。","君子与小人，赋予有偏全。","鸡豚与凤麟，凡庸于圣贤。","清浊乃尔殊，天性不可迁。","中庸贵能变，君子当勉旃。","浊夫会当清，清者当梯仙。"]},{"t":"感寓 其五十一","f":"五言古诗","c":["普天皆国土，四海皆国人。","唐虞今在上，一视乃同仁。","酷吏独何心，咤叱恣威神。","爪牙剧豺虎，曾不恤吾民。","冻馁任流殍，逸劳谁与均。","催科急于火，鞭挞肤已鳞。","健吏持帖来，追呼聚比邻。","鸡豚给馋口，拜跪回怒嗔。","老农二三子，力耕恒苦辛。","眼中欲流血，釜中屡生尘。","昨日有新条，公家收税银。","踟蹰惟四壁，局促仅一身。","健吏诟且辱，而敢诉其贫。","追随向官去，悲号谋所亲。","有女犹未笄，娇痴正青春。","商人买为妾，遑恤朱陈姻。","儿孙既零替，里胥犹日臻。","虐民恃官长，盘飧竞铺陈。","破屋存数间，求钱斧为薪。","性命苦见逼，恨不沈水滨。","斯民乃邦本，吾徒宜见珍。","苛政猛于虎，勖哉诸缙绅。"]},{"t":"感寓 其五十二","f":"五言古诗","c":["为善为君子，君子喻于义。","为恶为小人，小人喻于利。","所思既不同，善恶岂相类。","义利自两途，理欲所由异。","譬之食饮然，而各有所嗜。","恶臭与馨香，伊人自知味。","吁嗟义利间，慎无迷厥志。","北轲有法言，君子所当识。"]},{"t":"感寓 其五十三","f":"五言古诗","c":["有阳必有阴，有夜必有旦。","吁嗟正与邪，相反如冰炭。","谁谓郑声淫，韶音为所乱。","谁谓莠草新，嘉谷为所烂。","凤凰览德辉，鸺鹠可同观。","驺虞履中野，梼杌可同绊。","物类自区别，吾人亦相判。","荆舒培祸胎，群邪斯漫漶。","君实起西府，群贤乃藩翰。","星辰归党籍，君子窃悲叹。","正邪不两立，天王贵雄断。"]},{"t":"感寓 其五十四","f":"五言古诗","c":["人中有佞人，谗言不可当。","蜜口覆人国，簧言乱侯王。","贤愚任喉吻，君子归雌黄。","舐痔讵知耻，掇蜂终见伤。","绥绥九尾狐，媚惑迷四方。","洋洋八风舞，斯文遂无光。","我尝览前古，圣言奚敢忘。","为邦远佞人，谗夫尤所防。"]},{"t":"感寓 其五十五","f":"五言古诗","c":["商人元尚质，淳风自尔全。","周人始尚文，金玉日雕镌。","末世益滋伪，物情多变迁。","万物困凌暴，鬼工倦钻研。","八宝妆便器，珊瑚裁马鞭。","黄金饰宫殿，珠珍络鞍鞯。","一剑磨十载，一钗直三千。","相看竞淫巧，安知师圣贤。","象箸不可谏，玉杯谁肯捐。","一梦了今古，豪奢真可怜。"]},{"t":"感寓 其五十六","f":"五言古诗","c":["仲尼相鲁君，鲁人兴谤辞。","子产听郑政，郑人亦毁之。","赤心苦不同，黄口任瑕疵。","贤圣且不免，吾人莫嗟咨。","周公古元圣，流言乃相欺。","向非天动威，成王终见疑。","所以明哲士，脩身日孳孳。","谤言虽百端，而吾自坦夷。","譬之伤日月，指斥靡不为。","安知日月光，万古焉能亏。"]},{"t":"感寓 其五十七","f":"五言古诗","c":["西旅贡神獒，召公力阻之。","远方献名马，汉文乃深辞。","陇西产鹦鹉，广南生荔枝。","巨象致南粤，狮子走西陲。","翠禽尽输羽，猛兽皆脱皮。","白玉罄山谷，黄金空泽陂。","纷纷争献纳，扰扰欲何为。","愿言贡贤俊，为国扶雍熙。"]},{"t":"感寓 其五十八","f":"五言古诗","c":["吁嗟眼底人，反覆何其多。","对谈如隔山，同居或操戈。","结交出肝肺，回首施网罗。","变态苦不常，阴佼莫能过。","斯人何所喻，譬之江与河。","微风一相激，遽兴千丈波。","我诚憎其徒，洞见劳撝呵。","绵绵不可绝，纷纷将奈何。"]},{"t":"感寓 其五十九","f":"五言古诗","c":["我尝穷古书，窃闻谦受益。","如何夸毗子，洋洋多德色。","有位莫骄人，骄人位斯踣。","有国莫骄人，骄人士斯匿。","如有周公才，吝骄矜富殖。","虽云大圣人，斯亦无足式。","贤哉谢夫子，程门能自克。","三年去一矜，群儒推令德。"]},{"t":"感寓 其六十","f":"五言古诗","c":["君子莫施智，施智近小人。","愚人祗自愚，至愚翻近仁。","吾观古人智，而不私其身。","后人乃机巧，鬼魅与同伦。","吁嗟愚下流，为谋固难陈。","安知千虑中，一得无可因。","智囊竟何为，东市冤莫伸。","愚智莫相笑，同为千古尘。"]},{"t":"感寓 其六十一","f":"五言古诗","c":["天地赋人物，二气均所生。","如何贤不肖，而乃殊其名。","吁嗟贤者流，宜公亦宜卿。","嗤彼不肖徒，胡为污冠缨。","人君无所为，代天持鉴衡。","进贤退不肖，吾人资主盟。","前元多错缪，仕途良未清。","非才满廊庙，贤人困渔耕。","我祖奉天命，九州尽豪英。","黜陟考三载，万年仰大明。"]},{"t":"感寓 其六十二","f":"五言古诗","c":["淫奔谁氏女，少好正青春。","欲窦一以开，而宁顾其身。","踰墙期所私，钻穴召比邻。","恶少竞相逐，兄弟不敢嗔。","马蹄松柏下，鸡鸣风雨晨。","绥绥自求耦，往来岂辞频。","脂肤湿香汗，瓠齿含朱唇。","精神照秋水，秀丽惊鬼神。","我行偶见之，伤心泪沾巾。","颓风不可挽，凭谁振彝伦。"]},{"t":"感寓 其六十三","f":"五言古诗","c":["展雄古名盗，横行恣凶恶。","眈眈谁敢撄，杀人供咀嚼。","公然据太行，往来悉攘夺。","牗下终老寿，天意竟何若。","我闻三代时，群黎遂生乐。","后来日滋伪，绿林满丘壑。","穷寇不须追，饿虎不足缚。","公家薄租税，此辈将自削。"]},{"t":"感寓 其六十四","f":"五言古诗","c":["天地固不老，吾人安可常。","今者如不乐，逝者忽以亡。","矧兹隆盛世，四海称大康。","吾藩静无事，辅臣能赞襄。","散人荷天宠，贵富守一方。","台池与山水，登临足徜徉。","名花落又闻，好鸟鸣且翔。","黄奶助滋味，朱弦和宫商。","我生何庆幸，逸乐殊未央。","载歌咏天保，终身感吾皇。"]},{"t":"感寓 其六十五","f":"五言古诗","c":["忆初周穆王，天下恣观游。","八骏逐风雨，万里无停留。","瑶池觞阿母，玉帛朝诸侯。","琼浆侑天乐，白云起仙讴。","山川务穷览，邦家宁复忧。","徐方忽以兴，周鼎几不收。","亦有隋炀氏，黄金饰龙舟。","琼花作奇祟，妖氛满扬州。","至乐不可极，淫荒竟成休。","吁嗟后来者，能无览隋周。","茫茫天地间，无不有鬼神。","在下乃河岳，在天为星辰。"]},{"t":"感寓 其六十六","f":"五言古诗","c":["百神固非一，所主在一人。","一人总神器，百神歆所禋。","一诚本昭著，二气自屈伸。","变化讵能测，恍惚不可亲。","所贵乎君子，万物备其身。","鬼神自扶佑，福履将日臻。"]},{"t":"感寓 其六十七","f":"五言古诗","c":["吾观尘海门，善恶各有徒。","谦谦鲜君子，悻悻多凶夫。","善者所宜福，凶夫所宜诛。","善恶苟无报，真宰其含胡。","夷齐死沟壑，丘轲困穷途。","颜渊嗟夭折，比干乃捐躯。","盗蹠亦何人，横行主逃逋。","乳虎饱人肉，谁敢摩其须。","公然老牖下，雄风闻八区。","彼苍不可问，仰面长呜呼。"]},{"t":"感寓 其六十八","f":"五言古诗","c":["茫茫大化间，生育无停息。","鳞介与毛虫，而各成形色。","蠢蠢万不齐，至巧谁能识。","营营若有知，绳绳日滋殖。","馋夫亦何心，网罗兼弹弋。","五鼎恣煎烹，万钱供口食。","焉知爱物仁，忍杀无穷极。","君子远庖厨，暴殄良可惜。"]},{"t":"感寓 其六十九","f":"五言古诗","c":["天地有正气，英灵钟正人。","大义薄云汉，至诚通鬼神。","探穴蹈虎尾，沈渊批龙鳞。","碎首讵知惜，引裾宁畏嗔。","龙逢既以死，比干甘杀身。","史鱼以尸谏，直心终见伸。","诸公不可作，精神乃星辰。","回首媚灶徒，謟骨成埃尘。"]},{"t":"感寓 其七十","f":"五言古诗","c":["东海有匹妇，诬杀良可伤。","奈何三年旱，赤地千里荒。","幽燕有贱臣，繫狱将见戕。","仰天一叩心，六月飞清霜。","物情有冤抑，一念通彼苍。","二三持法吏，舞文自洋洋。","阳诛苟幸逭，阴祸亦可防。","于公能治狱，子孙乃隆昌。"]},{"t":"感寓 其七十一","f":"五言古诗","c":["吾闻尧舜世，皞皞惟淳风。","耕凿罢无为，礼义日以隆。","如何三代来，巧伪竞相蒙。","常道既以坠，斯文丁厄穷。","兄弟动相阋，父子或见攻。","臣节每中改，君恩多不终。","夫死妇即嫁，安能顾同宫。","帅亡兵即变，凭谁瘗元戎。","金多辄易交，官高互为雄。","耨锄且不假，财帛宁肯通。","轻肥骄市里，睨傲欺疲癃。","乳腥犹未除，群儿强称翁。","纷纷轻薄态，天下将无同。","诗成聊一笑，浮云满虚空。"]},{"t":"感寓 其七十二","f":"五言古诗","c":["万物有真伪，人心不可期。","真伪苟不分，君子将蒙欺。","譬之金与玉，而价固无赀。","珷玞与鍮石，乱真良可悲。","公旦困流言，恐惧实倾危。","新莽初下士，谦恭何自卑。","旦莽岂同伦，昧者犹自疑。","假饶身即死，真伪谁能知。"]},{"t":"感寓 其七十三","f":"五言古诗","c":["项籍苦强暴，沛公乃宽仁。","秦鹿竞相逐，六合生姻尘。","呜咽起雷电，叱咤惊鬼神。","拔山气盖世，扛鼎力足任。","豪雄竟难恃，凶残徒杀身。","阴陵一失道，楚歌自沾巾。","焉知卯金刀，兴隆自有因。","帝王本仁义，猛力何足云。"]},{"t":"感寓 其七十四","f":"五言古诗","c":["君子慎嫌疑，所慎良有因。","莫交孀妇儿，莫友敌国臣。","孀儿一与交，人谓私其亲。","敌臣一与友，人谓通其邻。","广会莫耳语，临民莫眉颦。","嫂叔不相授，男女不共茵。","临食休涕唾，迎宾休怒嗔。","共食莫泽手，分财莫言贫。","吁嗟天下事，一一难具陈。","避嫌乃君子，斯言可书绅。"]},{"t":"感寓 其七十五","f":"五言古诗","c":["绝代有佳人，盈盈擅风流。","裹头初入室，丑妇争为仇。","君看技术徒，忌嫉交怨尤。","文人亦相轻，诋斥多不侔。","孙庞初共学，藏修亦同谋。","忌心一以兴，对面操戈矛。","安得万黄鸟，九鼎荐为羞。","坐令天下人，其心同休休。"]},{"t":"感寓 其七十六","f":"五言古诗","c":["古人一忠厚，今人尚浮誇。","裘马纵驰骋，酒食恣喧哗。","文章逞轻薄，荒唐欲名家。","立言多不根，滔滔浩无涯。","吾思矫其弊，至诚斯可嘉。","六经不可及，何须诵南华。"]},{"t":"感寓 其七十七","f":"五言古诗","c":["文王曾拘羑，仲尼亦围匡。","至圣且不免，忧患奚可忘。","元来古君子，遭逢德弥彰。","脩身以俟命，履之若康庄。","臣子死忠孝，善道乃其常。","小人恒戚戚，翻为知者伤。"]},{"t":"感寓 其七十八","f":"五言古诗","c":["珠宫麝兰气，金帐流苏香。","美人娇侍夜，老此温柔乡。","不知勤四体，焉能法三王。","日夜未能起，更深尚飞觞。","舆行赏花柳，醉眠听笙簧。","散发任容与，饱食恣徜徉。","此乐虽莫极，外虞亦须防。","请观无逸篇，念念当不忘。"]},{"t":"感寓 其七十九","f":"五言古诗","c":["古道日以远，人情日以新。","逢迎以为悦，举世多谀臣。","比干蹈虎尾，龙逢批龙鳞。","二公既以死，千古难其人。","谀臣不足道，直士宜见珍。","吁嗟谀与直，举错在君身。"]},{"t":"感寓 其八十","f":"五言古诗","c":["君子自明白，小人多险邪。","毒阴类鸮獍，纠结如虬蛇。","蓝色丑于鬼，公然专正衙。","出口尽蜂蜜，满腹皆镆铘。","月堂幽且深，恒谋破人家。","复壁隐且僻，惟虞匕首加。","纷纷秽青史，追思可兴嗟。","群阴不可尽，仰叹白日斜。"]},{"t":"感寓 其八十一","f":"五言古诗","c":["静思天下事，黑白多见迷。","自非明知人，伊谁无所疑。","譬之鸦与鹭，同栖占林池。","黑白自分晓，何须苦相窥。","圣人明四目，烛理洞无遗。","台衡或昏暗，平治其资谁。"]},{"t":"感寓 其八十二","f":"五言古诗","c":["执虚如执盈，执圭如不胜。","譬之循墙走，蹜蹜惟恐倾。","圣贤重戒慎，厌斁宁敢生。","漏室虽至暗，衣冠对神明。","出门何所见，如接公与卿。","安居固无为，如临祭与兵。","尝观庸学传，庶几学斯成。","戒慎与慎独，没齿期遵行。"]},{"t":"感寓 其八十三","f":"五言古诗","c":["万物在天地，生生无暂息。","洪纤与高下，一一含太极。","鳞羽自飞潜，肖翘亦形色。","神功不可名，妙用谁能识。","忆昔弄丸翁，幽居悟天则。","微探极性情，至理穷因革。","我尝读其书，茫然无所得。","学海信汪洋，区区惭蠡测。","静思兴太息，居然竭心力。","安得起其人，为我祛郁抑。"]},{"t":"感寓 其八十四","f":"五言古诗","c":["将军饧沃釜，卫尉蜡代薪。","供馔宰名马，行觞杀美人。","万钱营一箸，九鼎荐八珍。","锦绮照庭户，歌钟动比邻。","豪纵讵知极，奢华孰与伦。","造物者好还，明明察吾身。","暴殄自亡灭，俭德独怡神。"]},{"t":"感寓 其八十五","f":"五言古诗","c":["公孙为布被，汉人讥诈廉。","司马亦布被，举世称大贤。","老聃尝有言，俭为天下先。","俭苟不中礼，魏风有遗篇。","大禹古圣人，至德垂简编。","亦有齐晏子，一裘三十年。","何曾独何心，一食费万钱。","末俗不可易，临风兴喟然。"]},{"t":"感寓 其八十六","f":"五言古诗","c":["吾人有正气，养之曰浩然。","充之塞天地，失养则靡全。","反身而理缩，万人吾往焉。","不缩乃自馁，褐夫亦难前。","燕丹不善养，谋报何拳拳。","虎狼一相犯，父子竟弃捐。","亦有廉将军，争功怒填填。","负荆终见屈，无乃相如贤。","恒思战国君，奋师日相牵。","往往就囚虏，所见何其偏。","容忍乃君子，庶几保天年。","血气圣所戒，吾人当勉旃。"]},{"t":"感寓 其八十七","f":"五言古诗","c":["吾观天下理，聚散不可期。","纣聚尘台财，武王乃散之。","财聚则民散，古语岂吾欺。","财散则民聚，君人所宜思。","此理自分晓，而人多自迷。","矧兹聚敛臣，为利日孳孳。","财乃民之命，民则邦之基。","观风亦何人，能无采吾诗。"]},{"t":"感寓 其八十八","f":"五言古诗","c":["周公复明辟，北面还为臣。","贼莽始居摄，久假遂即真。","歔欷执孺子，流涕沾衣巾。","如何草玄者，剧秦以美新。","赤符赫然起，覆宗终殒身。","伯禽继鲁后，祚延八百春。","流芳与遗臭，谁仁谁不仁。"]},{"t":"感寓 其八十九","f":"五言古诗","c":["万物有成败，造物自制之。","天定不可胜，人谋空尔为。","达人自知命，顺受尚奚辞。","嗤彼智巧徒，而徒用其私。","项羽败乌江，沛公成帝基。","虽云仁与暴，实乃天所思。","起家良不易，兴国亦如兹。","天地尚终坏，勿为千载悲。"]},{"t":"临池作","f":"五言古诗","c":["凿破苍苔地，引来寒溜长。","中有碧荷盘，红莲净以芳。","薰风扇炎熇，赤日回朱光。","披襟坐钓石，高柳阴生凉。","诗成复浩歌，对酒成疏狂。","恣我一朝乐，焉知人事忙。","邀宾时共适，临流飞羽觞。","洒然万虑清，援琴调宫商。","地僻绝喧杂，世事浑相忘。","兹盟幸无爽，终岁来徜徉。"]},{"t":"对月夜饮","f":"五言古诗","c":["银蟾上东岭，流光含夕清。","瑶天湛冰壶，万景俱分明。","招邀青桂下，开樽坐閒庭。","畅然发歌咏，一笑聊相倾。","嗟嗟尘世中，日夕徒营营。","佳景足吟赏，谁能测幽情。","苟使契真意，奚用劳平生。"]},{"t":"祀祖母太妃茔偶作","f":"五言古诗","c":["皇天渺无际，后土广且深。","缅怀大母恩，空伤寸草心。","雨露既沾濡，松楸散清阴。","瞻望杳容仪，不闻謦欬音。","俎豆式前陈，聊复昭寸忱。","感慨热中肠，涕泗沾衣襟。"]},{"t":"荅少参郁先生","f":"五言古诗","c":["岁久音尘绝，怀君思愈深。","兰章辱远寄，展玩轻南金。","锦绣夺人目，宫商恊雅音。","三复得远意，庶以慰离心。","瞻望不可见，云树连春阴。"]},{"t":"秋江访友画","f":"五言律诗","c":["秋江雨初歇，江波漫矶石。","鸿雁杂轻鸥，泛泛点寒碧。","松风萝径深，抱琴有游客。","相见复相违，苍苔掩行迹。"]},{"t":"云景画","f":"五言律诗","c":["同云酿飞雪，远近皆琼瑶。","冰壶冻六合，万木皆萧条。","策蹇来幽人，抱琴度危桥。","何处觅知音，前溪路迢迢。"]},{"t":"早起","f":"五言古诗","c":["枕上春梦惊，远寺疏钟歇。","起坐默无言，青灯半明灭。","缓步出门行，西楼挂残月。"]},{"t":"书室偶成兼柬新斋堂兄","f":"五言古诗","c":["粤若今古士，浮生谁百年。","俛仰宇宙间，时复长喟然。","衣食固煖饱，岁序恒推迁。","朽腐同草木，胡不师圣贤。","口吟六艺文，手披百家编。","勿言道弥坚，孜孜在钻研。","青岁不努力，白发空盈颠。","题诗遗同志，及时当勉旃。"]},{"t":"苦旱","f":"五言古诗","c":["妖魃肆凶顽，频年炽无已。","隰田皆龟拆，泾渭黄尘起。","井涸草木枯，赤地动千里。","天灾固流行，感召良有以。","死者相枕藉，生者艰动履。","骨肉尚相食，焉知有伦理。","困苦亦已极，调燮望谁弭。","彼苍空悠悠，胡不谅人只。","凭谁挽天瓢，一泻银河水。"]},{"t":"独坐","f":"古风","c":["重门掩绿树，车马寂无喧。","好鸟日相对，端居两忘言。","爽籁解炎?，满庭松竹繁。","怡然适吾趣，俗虑焉能干。"]},{"t":"书王氏族谱","f":"五言古诗","c":["大河发昆崙，众派同一源。","源深流益远，同归沧海壖。","巨木亦有本，本固末自繁。","培植岁云久，枝叶茂且坚。","惟人本乎祖，有开应必先。","馀庆由积善，古圣宁虚言。","王门世忠孝，德业光后先。","棱棱名宪使，友爱人称贤。","系明分族属，亲疏情愈宣。","千秋及万祀，瓜瓞常绵绵。","吁嗟后来者，世世宜勉旃。"]},{"t":"过田中有感","f":"五言古诗","c":["小人不可用，用则妨善良。","稂莠不可容，容则嘉谷伤。","所以田家父，耘锄日皇皇。","四体苦胼胝，仅得充饥肠。","奈何治家国，而不谨其防。","悠悠感前史，披书徒自伤。"]},{"t":"题四景画 其一","f":"五言古诗","c":["春风瑶草芳，桃花满村坞。","云林烟雾深，丁丁响樵斧。","岚翠湿衣襟，空山半疑雨。","乐哉萧散徒，麋鹿自成侣。","长啸倚岩崖，清风迈千古。"]},{"t":"题四景画 其二","f":"五言古诗","c":["西岭夕阳沈，绿树烟霏灭。","渔郎罢钓归，溪女采菱歇。","远水浸落霞，瑶天淡微月。","诗翁踞石吟，悠然清兴发。","吟罢好风生，萧萧吹鬓发。"]},{"t":"题四景画 其三","f":"五言古诗","c":["山空木叶落，万籁皆商音。","天外度征雁，东篱菊摇金。","茅屋数椽小，郁郁松径深。","游客远相过，趺坐鸣瑶琴。","幽怀聊共写，对酒且论心。"]},{"t":"题四景画 其四","f":"五言古诗","c":["栗烈岁云徂，顽云迷古树。","积雪遍山川，远近堆琼素。","野梅得春先，开遍前溪路。","独客好幽寂，杖藜林下步。","水寒渔父归，扁舟横野渡。"]},{"t":"首夏即事","f":"五言律诗","c":["景色当清和，小院绝尘俗。","阶药飘残红，池荷展新绿。","手调绿绮琴，试鼓薰风曲。","草色满虚庭，蔼然生意足。"]},{"t":"送顾指挥之襄阳","f":"五言古诗","c":["春水照双旌，迢递襄阳道。","王事重贤劳，喜君优智调。","秦民多阻饥，嗷嗷望君饱。","东风三月时，满目莺花好。","襄阳诸女儿，妖艳惊年少。","努力济时艰，千金休买笑。"]},{"t":"游兴善寺","f":"五言古诗","c":["兴善古名刹，僻居城南陬。","译经自唐代，遗迹于今留。","绿树荫苔径，阒然清且幽。","兹晨残暑退，凉风动新秋。","乐哉二三子，闲暇从我游。","行歌足胜览，乘兴还登楼。","仰视玉宇阔，俯瞰清江流。","南山当目前，雨过晴岚浮。","无边好光景，收拾归吟眸。","仆夫促归辕，清兴良未休。","回瞻北斗城，月光过林丘。"]},{"t":"春园行乐","f":"五言古诗","c":["青阳布生意，万物皆光辉。","风日适晴煖，花柳争芳菲。","方塘水初满，乔林绿正肥。","黄鸟出幽谷，嘤嘤鸣复飞。","银鞯鞚骅骝，赏心谁肯违。","盘桓讵知夕，明月扶醉归。"]},{"t":"秋夜露坐","f":"五言古诗","c":["大火流天末，金井飞梧桐。","草枯露华湿，莲衰池影空。","招摇向参宿，鸣蛩泣西风。","中夜耿不寐，孤坐明月中。","炎凉逐时改，感慨徒忡忡。"]},{"t":"步虚词赠印鍊师","f":"五言古诗","c":["逍遥一仙侣，灵胎宝元阳。","天风振环佩，凭虚朝帝乡。","驾以苍精虬，酌以青霞浆。","朝游华山颠，暮飞东海洋。","去来无定踪，玄鹤同翱翔。"]},{"t":"题魏颗结草图","f":"五言古诗","c":["死不从乱命，不从乃尊亲。","婢父阴有报，结草能胜秦。","吁嗟乎康公，而心胡不仁。","三良既云殉，国事亦以湮。","细读黄鸟诗，令人泪沾巾。"]},{"t":"新斋兄寿诗","f":"五言古诗","c":["仙人跨白鹤，元阳结灵胎。","天风振环佩，驾言游蓬莱。","餐以青精饭，酌以流霞杯。","苍梧与北海，倏忽时往回。","回首笑而语，寿域从今开。","春秋百千祀，今日乃其媒。"]},{"t":"成化乙已关中苦旱","f":"五言古诗","c":["东风转岁律，对景不成观。","微雨未沾足，田畴复枯乾。","连村绝烟火，比屋皆伤残。","民生与鬼邻，疫疠仍相干。","匡时愧无策，抚膺空长叹。","我欲叩天阍，恨乏凌风翰。"]},{"t":"挽郑长史父母","f":"五言古诗","c":["萧田古文献，先后多名人。","而翁钟瑞秀，琼姿迈风尘。","富而更好礼，乐善能周贫。","优游泉石间，浑然葛天民。","惟刘乃厥配，四德备一身。","勤俭资内治，甘旨同养亲。","岁时助禋祀，诚敬采蘩蘋。","芳年三帙馀，鱼水情两真。","瑶琴忽中断，无复鸣阳春。","鼓盆发长叹，闻者为悲辛。","诸郎复秀发，咸怀席上珍。","白眉乃子初，观光充国宾。","历官鲁藩相，霜风殒灵椿。","泣血既三祀，衣冠谒枫宸。","董贾素腾誉，复官相吾秦。","子贤岂无自，严慈家教勤。","貤恩五花诰，指日来八闽。","草木翳双冢，蔚然光宠新。","丰碑表潜德，万古宁沈沦。"]},{"t":"偶书","f":"五言古诗","c":["城西地卑湿，一掘能及泉。","居止失将护，寒气相寅缘。","冬深偶疾作，春尽犹未痊。","只尺艰动履，坐久空兀然。","吁嗟孝道违，于身诚有愆。","父母全生之，子当慎保全。","兢兢复战战，于心愧圣贤。"]},{"t":"蜀府德阳王师古堂代保安王肃斋作","f":"五言古诗","c":["圣圣既以远，古道何邈绵。","遗训弗俱亡，明明垂简编。","万理具成宪，后王宜不愆。","吕政弗师古，诗书烬馀烟。","傅说古良弼，纳诲心拳拳。","至言乃龟鉴，宜哉千古传。","吾人思受益，无如师圣贤。","君子贵自勉，彼昏胡不然。","河间兴礼乐，淮南泥神仙。","择术诚在人，存亡讵由天。","吾宗有贤王，分藩世蝉联。","日用动师古，肯为流俗牵。","苍黄免驰逐，货色咸弃捐。","斋居静无事，妙契羲皇前。","嗟余沗宗人，见贤思与肩。","昼读古人书，夜梦与周旋。","吾宗契吾志，夙夕恒乾乾。","声光腾玉牒，流芳万斯年。","皇祖有彝训，典则相后先。","宪章在诸孙，百世同勉旃。"]},{"t":"岁晚","f":"五言律诗","c":["玄天忽冬暮，岁功云已成。","群阴结幽谷，冻鸟栖复惊。","四序迭更代，万汇纷枯荣。","物理孔昭著，君子宜安贞。"]},{"t":"古意","f":"五言古诗","c":["莫栽莲在沼，莫种柳临岐。","莲实中多苦，莲根中多丝。","杨柳垂长条，犹解赠别离。"]},{"t":"秋夜","f":"五言律诗","c":["月光透绮疏，露华湿金井。","疏枝惊鹊堕，腐草流萤冷。","入秋情转多，况复寒宵永。","默坐当前墀，素心徒耿耿。"]},{"t":"写怀","f":"五言古诗","c":["野情耽逸趣，僻地结幽居。","其中何所有，左右秪图书。","饱食竟无事，陈编聊卷舒。","众鸟相和鸣，园林宿雨馀。","好风东南来，飘飘吹我裾。","愿言竟兹乐，舍此复何如。"]},{"t":"有怀凌卧岩","f":"五言古诗","c":["月色满虚庭，皎然如秉烛。","鸣蝉咽无声，巢鸟惊还宿。","忽忆卧岩人，怅然乱心曲。","烟树千万重，苕溪如在目。","有书未得通，有地何由缩。","入口匪刀圭，春风面如玉。","悠然养谷神，遐龄端可卜。"]},{"t":"寓兴","f":"五言律诗","c":["浇风乱淳俗，靡靡入人深。","猗兰谁所谱，为我调素琴。","琴中有天趣，茫茫无赏音。","吁嗟广陵散，终古其沈沈。"]},{"t":"山水图","f":"五言古诗","c":["我自游山归，见山心辄喜。","何人写此图，彷佛旧游是。","漠漠岭上云，泛泛溪中水。","啼猿扳树颠，驯鹿依山趾。","谛彼方瞳翁，宛然赤松子。"]},{"t":"玩松石","f":"五言古诗","c":["郁郁涧畔松，凿凿岩下石。","移来置庭阶，苍然古颜色。","我生幸多暇，废卷对终日。","苔藓点斓斑，霜风动萧瑟。","尘埃隔人境，庶以慰幽寂。"]},{"t":"安分","f":"五言古诗","c":["菽粟贵充腹，焉用罗珍羞。","布帛既适体，何须衣轻裘。","缊袍与箪食，哲人竟亡忧。","况复过饱暖，安居日优游。","内省自不疾，此外复何求。"]},{"t":"轩中即事","f":"五言古诗","c":["小小结幽轩，我来任栖宿。","富贵轻浮云，身安心自足。","高槐夹行道，繁阴凉夏屋。","洞然八窗开，青山常在目。","细和渊明诗，诗成还自读。","夜来风雨声，晓起庭莎绿。"]},{"t":"沧浪图","f":"五言律诗","c":["水清斯濯缨，水浊斯濯足。","逍遥大块间，何荣复何辱。","日暮罢钓归，孤舟水云宿。","觉来吹洞箫，一和沧浪曲。"]},{"t":"纪梦","f":"五言古诗","c":["深宫传蜡烛，侍儿治我床。","心虚静无事，安眠纳微凉。","俄然梦一人，黑色颀而长。","衣冠存古制，玉佩鸣锵锵。","粲然顾予笑，眉目如有光。","自言忝西伯，陵丘在咸阳。","我闻惊且拜，无乃周文王。","抠趍将复请，云车忽飞扬。","梦回长太息，沈沈夜未央。","夙兴具圭冕，宝鼎燃瓣香。","孝慈与仁敬，明明垂典章。","文王真我师，千载讵敢忘。"]},{"t":"雪夜","f":"五言律诗","c":["积雪动连旬，岁华复相迫。","中夜坐彷徨，窗明如月白。","竹炉火正红，玉盌浮桐叶。","晓起看青山，同云天一色。"]},{"t":"雪意","f":"古风","c":["上天布同云，寒日堕不收。","老木归栖鸦，彻夜风萧飕。","屋茅尽以捲，掀?无停休。","昏昏遍千里，落落连九州。","谁将万端叶，欲寒山中沟。","寒虫厌原野，枯桑叫林丘。","冰下有河鱼，忍冻谁肯求。","万间思广厦，被覆焉能周。","独有力耕者，相看起歌讴。","今年麦信好，明岁真无忧。","矧兹百谷中，所急先来牟。","去冬苦愆阳，诜诜出螟蟊。","一雪今乃尔，来牟行有秋。","沗予守西土，而岂为食谋。","端居念农事，宁敢忘绸缪。","吾藩盛邹枚，森然拥戈矛。","语气各勍猛，星堂能少留。"]},{"t":"进履图","f":"五言古诗","c":["张良昔未遇，誓欲报韩仇。","进履圮桥下，虚心将有谋。","素书一授受，于焉相炎刘。","蹙秦暨蹶项，默运帷幄筹。","王业既大定，毅然乞封留。","列侯岂不贵，而托赤松游。","度彼良之心，报韩愿已酬。","区区黄石公，不知伊与周。","素书视典谟，治道孰为优。"]},{"t":"问礼图","f":"五言古诗","c":["聃为柱下史，周礼在于斯。","圣人不自圣，从聃一问之。","学琴暨问官，所学何常师。"]},{"t":"枯木竹石画","f":"五言律诗","c":["老木势槎牙，相依独幽筱。","空山岁月深，苦历风霜饱。","幽筱欲成林，老木自合抱。","托根既得所，愿言永相保。"]},{"t":"读史外纪 其一","f":"五言律诗","c":["太极本无极，乃在天地先。","两仪生四象，庶类斯繁焉。","混茫一以辟，浑敦御其间。","明达二五粤，三才方肇宣。"]},{"t":"读史外纪 其二","f":"五言古诗","c":["粤惟太古氏，一姓十三人。","澹泊诚无为，俗化因之淳。","干支名岁在，天灵实斯君。","继之王者何，爰以定三辰。","寿年能满德，一万八千春。"]},{"t":"读史外纪 其三","f":"五言古诗","c":["居方受元命，继地治以昌。","山川分九区，人各居一方。","惟臣不虚贵，惟主不虚王。","君臣政教兴，男女斯有常。","淳风正沕穆，更号曰九皇。"]},{"t":"读史外纪 其四","f":"五言古诗","c":["于惟大荒初，人物无区别。","抟生以咀华，茹毛而饮血。","夏暑结巢居，冬寒穿窟穴。","传教土为台，纪事绳为结。","厥后书契兴，事事劳辞说。"]},{"t":"读史外纪 其五","f":"五言古诗","c":["太昊象日月，帝德能合天。","耦奇自有数，河洛呈其玄。","婚姻分姓氏，断桐丝为弦。","神明德可通，万类情可宣。","道统信斯启，圣圣乃相传。"]},{"t":"读史外纪 其六","f":"五言古诗","c":["伊耆蓺五谷，有熊占斗纲。","人文一以著，尧舜垂衣裳。","夏忠商尚质，周文郁有光。","绳绳隆治道，国祚绵且昌。","春秋互征伐，七雄争暴强。","嬴秦窃神器，再传二世亡。","仁义弃不施，吁嗟良可伤。"]},{"t":"子贡访原宪画为康文渊都阃题","f":"五言古诗","c":["世道不再古，浇漓凿其淳。","交朋多以面，畴能践其伦。","恒人无足让，贤者宜自亲。","云胡端木赐，坐观原宪贫。","而惟营货殖，千金贸奇珍。","焉知固穷士，衣有百结鹑。","吁嗟端木心，见道亦已真。","同侪苟云乏，分财非所嗔。","宪乎实自守，躬耕甘苦辛。","不义富且贵，视之若飘尘。","仁义自充足，道德堪润身。","相寻谈一贯，冻馁安足陈。","二贤去已远，友道犹如新。","披图三太息，聊示今之人。"]},{"t":"寿李封君绣衣","f":"五言古诗","c":["沁源有遗老，安居踰稀年。","鼻祖老聃氏，遥遥乃曾玄。","髫年入頖宫，经礼穷三千。","蟾宫高折桂，领教司陶甄。","黉堂拥师席，白昼那肯眠。","鄠邑亦多士，教铎日以宣。","慈溪还小试，吏隐聊周旋。","一朝挥印绶，去去何飘然。","庭闱足甘旨，节孝人共传。","鲤庭莱衣趋，兰桂纷相联。","蜚英有侍御，超登多士先。","中台应豸绣，龙敕推恩全。","朅来振风纪，将命历秦川。","晴云飞太行，东望心旌悬。","时维小春月，寔逢初度天。","王事念靡盬，私归宁敢专。","沁源近西土，夙昔闻其贤。","所存在忠孝，食报宜绵绵。","方今天子圣，寿域开八埏。","我诗贺而翁，庸续南山篇。"]},{"t":"春日有怀","f":"五言古诗","c":["众鸟集芳林，喧啾竞阳和。","感时坐达旦，长啸悲且歌。","念彼金石交，悠悠隔关河。","重晤良独难，相思将奈何。","岁月忽以晚，世故何其多。","嗟嗟黄小群，绀发俄成皤。","倚床发浩叹，万事皆蹉跎。","达人贵知命，对酒自吟哦。"]},{"t":"春日久阴孤坐无聊写此寓怀","f":"五言古诗","c":["青阳郁未舒，开轩坐独冷。","阴风中夜吹，迟日黯晴影。","红芳半消歇，青苔生露井。","云幕山光微，林邃鸟声静。","兀坐寂无聊，居然厌尘境。","谅惟高世人，焉能惜光景。","道德日已负，素怀徒耿耿。"]},{"t":"忠孝卷为唐府题","f":"五言古诗","c":["大本忠与孝，大伦君与亲。","君亲本一致，忠孝非两人。","于惟先哲王，见道亦以真。","大书忠孝字，训饬何谆谆。","辽鹤去不返，手泽常如新。","囊封遗一使，千里来吾秦。","再玩复再拜，披读惊心神。","省躬诚不暇，佩服当书绅。","愿言保终始，树德崇彝伦。"]},{"t":"登山诗","f":"五言古诗","c":["晨兴驱吾车，驾言徂南山。","岂徒汗漫游，直欲陟其巅。","冷冷起长啸，飘然振羽翰。","鸟道数千仞，宛若登天难。","回辕憩林麓，临流濯缨冠。","急湍泻长坂，閒云出层峦。","丛兰散清馥，幽禽时间关。","隐沦慕肥遁，羁绊迫尘寰。","斜阳催我归，回首空长叹。"]},{"t":"闰三月一日与永兴王宜川王赏花","f":"五言古诗","c":["花时开宴席，兹晨属良辰。","雁行列长幼，谊重惟天伦。","斗酒起相寿，于焉见情真。","欢乐岂徒尔，一一难具陈。","新声奋逸响，蕴结良以伸。","鸿宝启神秘，谁贻千祀身。","去年七兄弟，今岁唯三人。","茫茫大块间，宁择疏与亲。","蜉蝣竞朝夕，蟪蛄悲秋春。","何不娱心意，郁郁徒苦辛。"]},{"t":"予性不嗜酒偶读山谷集徐仲车为董元达置酒四韵有惟此酒中趣难为醒者论之句因足成之","f":"五言古诗","c":["惟此酒中趣，难为醒者论。","孟嘉乃先得，当筵对桓温。","我生不嗜酒，于此复何言。","卫侯有抑戒，耿耿明朝暾。","古人重百拜，多酌矧敢吞。","云何后世人，甘为曲蘖昏。","贤哉天随子，恒自我思存。","长揖辞醉客，无劳登我门。"]},{"t":"咏雪","f":"五言古诗","c":["尖风中宵来，势力两具足。","寒威侵人肌，素色绚我目。","高观银河迷，远望翠岭没。","春彫千梅花，夜照万蜡烛。","乔松低疏枝，老柏露瘦骨。","庭空堆飞盐，院冷折大竹。","茶空新条严，酒罄宿债促。","吟哦娱吾心，富贵匪我欲。","长愁难消除，短恨易屏逐。","来牟盈三川，集霰遍四渎。","端居叨藩维，稔岁念夏屋。","兹逢群公贤，饱我百姓腹。","吁嗟天潢分，羽葆坐衮服。","焉能酬皇仁，北望但颂祝。","如冈还如陵，万祀纳景福。"]},{"t":"弘治龙飞歌","f":"古风","c":["于皇太祖高皇帝，受命于天驭神器。","巍巍六合永为家，鸿业相承千万世。","文祖神谋治两京，武戡文化天下平。","猗欤仁祖及宣祖，洋洋雅颂同休声。","英皇智勇冠前古，百万貔貅振威武。","重登大宝日重明，至治真成步三五。","绵绵历数归宪宗，与天同运还同功。","虞舜执中传圣嗣，汉文至孝尊慈宫。","六龙返辔归何急，攀折龙髯追莫及。","红尘隔断白云乡，群臣空抱遗弓泣。","太平天子属今皇，尧眉舜目非寻常。","元老徵来居鼎鼐，群奸屏去投遐荒。","放珍禽，驱猛兽，祖训昭回光复旧。","琅玕火齐却承筐，商琏夏瑚轻莫售。","天命维新政维始，不宗佛子宗夫子。","前朝陵寝总沾恩，万国山川俱入祀。","风不鸣条海不波，四时玉烛调元和。","邈绵天统纪弘治，宗臣首倡龙飞歌。"]},{"t":"长歌为宗伯汧阳端懿王作","f":"七言古诗","c":["猗欤我祖秦之康，维岳钟秀通天潢。","嫡庶振振四男子，一一教之以义方。","我考惠王袭祖荫，分茅诸父皆封王。","鸑鷟麒麟瑞明世，中间杰出推汧阳。","玉叶金枝竟凋殒，岿然仅见存灵光。","王性恬然靡所好，孜孜为善希刘苍。","宗藩耆寿典刑在，如松斯茂兰斯芳。","厌世一朝观化去，骑箕游彼白云乡。","远近无人不嗟悼，况在骨肉情尤伤。","讣音千里达当宁，便蕃恤典非寻常。","奉常稽行谥端懿，帝曰休哉王可当。","象贤克孝有宗子，三年血泪流淋浪。","咫尺终南瘗冠剑，杜陵西畔曲江傍。","寒烟落日翳荒草，瑟瑟悲风号白杨。","吁嗟王心料无憾，含笑幽宫天地长。"]},{"t":"放情歌","f":"古风","c":["我生大块间，俯仰无愧怍。","灵台澹以虚，秪知为善乐。","五音错吾之耳明，六材滑吾之口清。","兼之雅趣在岩壑，况乃至性嗜哦吟。","富贵非吾欲，坦夷是素心。","有时宫居厌烦热，飘然直欲攀明月。","飞上莲花第一峰，更踏虹桥看银阙。","有时鹤背御罡风，扶摇直过蓬莱东。","回首沧溟一杯小，侧身为挂扶桑弓。","一笑归来还击缶，自酌天浆斟北斗。","扣歌几阕游仙词，彩凤和鸣赤虬吼。","忆初元是瑶台仙，紫皇谪我三千年。","青山为尘海为土，永与日月同周旋。"]},{"t":"具庆堂歌送高广原教授省亲还江西","f":"古风","c":["泰和为郡壮且雄，郁然佳气常葱葱。","文山字水孕灵秀，瑰奇人物生其中。","高家阿翁年七帙，双瞳点漆颜如童。","举案齐眉人亦健，身绥五福优閒同。","百年名阀诗兼礼，先后衣冠应济济。","风流江左世无双，玉树芝兰满阶砌。","个中杰者乃广原，十年辅导居藩邸。","驱驰千里省庭闱，宾筵暂辍刘交醴。","春风吹衣宫锦香，里闾草木增辉光。","承欢膝下奉颜色，具庆堂开称寿觞。","罗绮丛丛咽丝竹，壶天日月何其长。","古今万世尊常道，须信人生在忠孝。","立身无愧显双亲，移赤还应为君报。","我观具庆图，为作具庆歌。","愿言齐寿耇，更比乔松多。","紫泥封诰来銮坡，天恩浩荡沾馀波。","具庆堂，高嵯峨，芳名千载当不磨，芳名千载当不磨。"]},{"t":"爱梅歌","f":"古风","c":["罗浮仙子名姑射，影落壶天澄玉质。","严霜满地冱寒时，万木萧条更无匹。","本来的的生面同，暗香浮动冰蟾中。","老干虬蟠硬如铁，翠羽枝头夜袅风。","我有爱梅癖，梦寐常见之。","朝来散步绕花下，暮亦巡檐与鹤随。","我爱梅花岂无意，爱渠剩有调羹味。","岁寒心事愿结盟，共保坚贞莫轻弃。"]},{"t":"神骏歌","f":"楚辞体","c":["渥洼龙种世所稀，一一标格矜权奇。","房精变化降下土，飘逸肯受黄金羁。","良造一朝司控制，歘然雷电霜蹄随。","周王图里空驰骤，韩干笔端非所知。","当日临淮曾破敌，贼锋辟易何能为。","圣皇揽驭清寰宇，猛气雄姿谁敢窥。","恩深伏枥亦知报，万里沙场力未疲。","骏兮骏兮安得复生一十二，为我扫除边警苏疮痍。"]},{"t":"金鱼歌","f":"古风","c":["金鱼来自金仙国，三十六鳞谁与饰。","金仙亲手傅金泥，满池都作黄金色。","自疑身自金仙来，凿池引水青天开。","等閒俯槛玩且咏，相忘物我何悠哉。","黄金佛国真可誇，金盆又出金莲花。","呼童满进金罍酒，肯使金鱼荐齿牙。","金鱼金鱼汝幸在吾沼，育子生孙足怡老。","莫愁咀嚼莫愁烹，恣尔优游戏萍藻。"]},{"t":"梦中仙游歌","f":"古风","c":["夜梦一羽人，云是赤松子。","授我九还丹，服之能不死。","又言携尔游太清，共骑彩凤摩青冥。","相逢子晋笑相揖，为我殷勤吹玉笙。","天风泠泠振环佩，蕊珠宫阙何峥嵘。","东望蓬莱西弱水，倏忽周行数万里。","却怪天鸡唱晓频，恍惚惊回困窗底。","觉来自信还自疑，多少迷人睡初起。"]},{"t":"新燕歌","f":"古风","c":["一从秋社去，春社与谁期。","年年来往如相识，又向乌衣国里归。","王谢堂前音问绝，玉京红缕声悲咽。","垒逼高楼柳似烟，泥衔香径花如雪。","一番相见一番新，呢喃终日语频频。","双飞莫入深闺里，人在绿窗初睡起。"]},{"t":"金台王气歌","f":"古风","c":["我祖应天命，车书混南北。","定鼎制多方，当天履中极。","大都之地何雄哉，真人御世自天来。","九重宫阙三台近，万里河山一诏开。","城高北斗星辰拱，雨霁居庸青叠耸。","黄旗紫盖郁岧峣，彩凤回翔赤龙拥。","千官待漏五更寒，两柱擎天峙角端。","介胄如山趍侍辇，炉烟绕陛候迎銮。","我朝元气回前古，灵物呈祥遍天宇。","驺虞已见出南河，狮子重看贡西土。","当今天子思唐虞，维持燮理多通儒。","玉堂日日有歌颂，青琐年年无谏书。","一朵红云笼斧扆，百花仗外飘然起。","玉容侍女接丝纶，绣帽才官辉锦绮。","禁柳三眠絮欲飞，退朝閒过御桥西。","覆鞍黄帕观呈马，缠项红罗看斗鸡。","香尘紫陌人如蚁，车骑纵横溢闾里。","暗香遥引玉鞭来，满眼红妆隔帘底。","王孙公子日相从，笙歌无日不春风。","宋公自昔推清制，魏国于今表大功。","六曹五府相连络，梵刹琳宫耀丹雘。","公侯列第武功坊，耆儒应制文渊阁。","三十六宫莺乱啼，四十八卫马争嘶。","霜飞柏府乌千点，春日梨园锦万畦。","金台王气千年在，青入西山终不改。","尧天荡荡景星明，瑞日相辉助光彩。","阿谁谈笑觅封侯，莫负明时趁黑头。","深愧维藩无寸补，天高日望五云楼。"]},{"t":"对月行","f":"七言古诗","c":["城市嚣尘涨烟雾，姮娥有约谁分付。","我家咫尺隔萧墙，弱水肯容舟楫渡。","夜静深宫刻漏长，沈沈天宇生微凉。","玉盘寂历转河汉，琉璃万顷腾清光。","幽兴满怀宁复寐，姮娥此夜应无睡。","笑拈北斗酌天浆，寒气逼人浑似醉。","天香万斛摇金风，吴刚玉斧声丁东。","银桥贝阙在平地，等闲呼吸腾青空。","我为嫦娥笑开口，长生有药曾知否。","愿从白兔乞刀圭，亲向蟾宫拜登受。","桂花树下共婆娑，青鸾骑出凌沧波。","木公锡我八千岁，相看不老同山河。"]},{"t":"五马朝天行送严宗哲太守","f":"七言古诗","c":["五鼓紞如天欲曙，喧传五马朝天去。","朱轓皂盖引双旌，逸气摩空更轩翥。","文章太守真奇才，元驱五马从天来。","霜蹄二十起云雾，遥遥复上黄金台。","黄金台高几千尺，凤阁龙楼绚晴日。","台边五马系三花，入觐天颜述臣职。","年来善政满四方，口碑载道声洋洋。","赐金增秩荷殊宠，永兴山水皆辉光。","知君此去追前烈，鼎鼐盐梅待调燮。","古来郡守作三公，努力功名趁头黑。"]},{"t":"素扇歌","f":"七言古诗","c":["我家近似筼筜谷，不种蔷薇种脩竹。","呼僮洗出化龙枝，错落金刀削寒玉。","宛转雕珰献雪肤，清风满座来吾徒。","飒然置我湘帘底，手持半月摇冰壶。","一开一阖真奇绝，肯把双瞳迷五色。","等閒欲倩右军书，却恐霜笺污烟墨。","高情雅淡本相同，此柄还君掌握中。","会当扫尽三庚热，笑骑白凤凌丹空。"]},{"t":"登楼","f":"七言古诗","c":["百二金汤浮六幕，凭虚如上蓬莱阁。","九州下视不盈眸，何用盘游纵骝骆。","幸分茅土守西方，景行东平为善乐。","金罍有酒谩如泉，燮理浅深随意酌。","中人掖我登云梯，长恐檐头星斗落。","终南泰华献奇峰，万朵芙蓉簇花萼。","有时金碧变云霞，似避吾诗愁律缚。","北辰拱捧望神京，天柱高悬云漠漠。","丹心飞绕紫宸居，恨不当轩展葵藿。","回头有泪洒松楸，雨露寒霜感丘壑。","龙蟠虎踞本天成，马鬣牛眠欣有托。","浩歌穹壤不胜情，歌罢清风起寥廓。","坐听佩响落珊珊，恍惚仙人下黄鹤。"]},{"t":"早起对雪","f":"七言古诗","c":["天人剪水光玲珑，乱飘瑞叶惊酸风。","乾坤茫茫眩银海，万里山河无路通。","水晶帘幕寒威重，大地浑无一尘动。","南枝翠羽啼早春，数声唤醒梨云梦。","晓来东阁呼僮奴，净扫冰花烹竹炉。","自怜学士有清趣，不比豪家太尉粗。","我皇圣德充寰宇，太平象兆多如雨。","管取明秋大有年，四海讴歌歌舜禹。"]},{"t":"九鸶图为魏大用佥宪题","f":"七言古诗","c":["春树垂阴春雨足，潋滟银塘涨新绿。","何处飞来属玉群，相逐波间弄晴旭。","宿食飞鸣态度閒，网罗不到清溪湾。","有时一行上天去，凤凰池上联鸳班。","画工图此宁无意，得句紬思缘古义。","我师此义不师工，目睹令人心惕励。","伟哉佥宪古人徒，爱此宁殊丹穴雏。","素心一点与俱白，虚室相忘馀此图。","眼前何限丹青笔，生色虽工总无益。","不观南浦锦鸳鸯，交颈双双徒尔匹。"]},{"t":"悼鹤","f":"七言古诗","c":["有客有客来青田，贻我缟素之胎仙。","放之庭下自舒逸，有时飞上苍松巅。","落地蹁跹如寄傲，风动霜翎舞还蹈。","数声长唳彻青天，踏破苍苔犹未扫。","丹顶日深毛日苍，纷纭驾鹳敢同行。","几番露下秋空冷，树杪戛戛闻悠扬。","昨来漫尔穿林去，误落辽东华表柱。","流丸何处忽飞来，毛羽离披叹遭遇。","归来病骨不可支，浮邱老去谁能医。","可怜一夜竟捐弃，佐卿无复来庭墀。","惆怅九皋已陈迹，安得回仙为裁笛。","汉江楼上月明时，吹引天风裂山石。"]},{"t":"对萱花有感","f":"七言古诗","c":["谁向北堂培寸草，四月花开生意好。","何事南风太不情，等闲断送成衰老。","人言咀嚼解忘忧，我对此花双泪流。","乾坤有限恨何极，犬马私情难与酬。","我思柔顺萃吾亲，关雎风化行西秦。","内治远同周太姒，敢云公子皆麒麟。","七龄愧我尚蚩蚩，机杼参丸劳母慈。","一朝奄忽弃我去，鸾车杳杳焉能追。","只今已嗣亲藩爵，玉食衮衣非所乐。","悲吟镇日对兹萱，忍见花开又花落。","花落明年又复开，鸾车一去何当回。","沧溟可枯石可烂，抱泣北堂能已哉。","哀词难尽付长歌，泪笔淋漓写蓼莪。","吁嗟有国不逮养，伤心其奈萱花何。"]},{"t":"秋江晚渡图","f":"七言古诗","c":["寒江波冷西风急，况是津头日将夕。","长年引手费招呼，搔首携囊空伫立。","乾坤扰扰嗟浮生，烟波万里争微名。","如此风涛竟安适，旁观颠覆令人惊。","商人冒险如平地，只说茶船千倍利。","湘流东下欲兼程，鱼腹埋魂真可畏。","独有渔翁不为钱，渔歌欸乃叩渔船。","得鱼换酒醉明月，一轮还系江之边。","忆昨龙眠为写图，金壶墨汁何模糊。","高堂挂壁坐兴叹，知者还应寻坦途。"]},{"t":"甲辰岁关中大祲","f":"七言古诗","c":["关中连岁天无雨，泾渭扬尘水如乳。","时当四月景清和，却讶炎蒸乃如许。","太华终南无片云，草树焦枯欲自焚。","流移老稚日如蚁，啼饥远近声相闻。","面垢头髼衣百结，手足胼胝泪成血。","流离血属各天涯，多少僵尸委沟壑。","见此令人心孔伤，鼎钟那忍居高堂。","安得陈陈万仓粟，分炊尽使充饥肠。","露跣告天谁最苦，诚悃无由达天府。","欲凭大手挽银河，沛作甘霖满西土。"]},{"t":"丁巳雷雨大作","f":"七言古诗","c":["神龙倒捲沧溟水，洒作人间及时雨。","终宵达旦势倾盆，沃润枯焦胜膏乳。","狂风号怒撼乾坤，泼墨浓云白昼昏。","四檐急溜泻川峡，平田顷刻惊涛奔。","未须借剑斩妖魃，霹雳威声震寥廓。","一时灾沴尽扫除，满路流移藉全活。","当今天子坐明堂，宵旰图治心皇皇。","一念精诚格苍昊，六合骈应来祯祥。","佐时更喜调元手，方泰谁云值阳九。","凡芃禾黍屡丰年，看取国书书大有。"]},{"t":"咏雪和欧阳公禁体韵","f":"七言古诗","c":["长空汗漫呈六萼，脉脉随风旋回薄。","望穷袤广极幽潜，至巧信出天机作。","江山一洗尘土空，使我方寸成恢廓。","即妨见晛行且消，轻体不受春阳烁。","闭门静听疑有异，历乱寒声瓦沟落。","衾裯如水不成眠，起坐中庭拥裘貉。","狡兔失穴不得归，饥鹰敛翮难施攫。","农仓有粟床有酝，醉饱歌讴跃如雀。","出门玩赏恣所如，水行孤舟陆双屩。","一方坐食百无补，矧敢暇逸先民乐。","题诗苦无道韫续，取茗不待家姬瀹。","纸窗官烛夜沈沈，翠柏苍松云漠漠。","翻思吟社十年事，白战坛中曾拥槊。","短歌聊尔代风谣，不似寻常浪吟噱。"]},{"t":"寿夏廷赞行人母八帙有三","f":"七言古诗","c":["春江雨过春波绿，银瓮香生春酒熟。","肥鱼鲜笋杂初筵，一派笙歌沸华屋。","江南名郡说高邮，清门积德如山邱。","有美来嫔馀八十，翟冠霞帔心忘忧。","高堂坐拥红氍毹，掌上看成明月珠。","当年慈训动人耳，手和熊胆劳勤渠。","凤雏早上青云程，淋漓御墨亲题名。","行人远使传天语，四牡騑騑玉节荣。","一函赉赐来西土，文采威仪快人睹。","春风便道归故乡，昼锦优游轻负弩。","綵衣正及杏花天，称觞起舞庭阶前。","世间瀛岛是仙宅，阿母来降三千年。"]},{"t":"雨竹","f":"七言律诗","c":["凤毛䙰褷洒寒雨，绿玉团云飞不起。","窗涵翠滴润图书，凉气满天秋若洗。","湘江曾梦泊孤舟，一片潇潇落篷底。","夜深惊起倚阑干，却忆美人隔秋水。"]},{"t":"中秋无月","f":"七言古诗","c":["去年今夕秋雨晴，银蟾出海何晶明。","中庭宴集惬幽赏，良夜况与清风并。","水精帘开广寒府，十二琼楼辉玉宇。","漙漙白露洗瑶空，桂影婆娑素娥舞。","仰天举酒吸寒芒，万顷金波流肺腑。","恍疑身世在蓬瀛，漏下人间惊五鼓。","今年此夕何重阴，浓烟黑雾天沈沈。","老桂无香素娥倦，冰帘不捲琼楼深。","庭院无人苔藓湿，萧萧树杪秋声急。","青灯兀坐转无聊，四壁阴蛩宛如泣。","阴晴变态真浮沤，休信青春难白头。","不见去年与今岁，清光可得长淹留。"]},{"t":"临池","f":"七言古诗","c":["我性元来喜幽独，长笑痴人避空谷。","临流处处得天真，不问外边丝与肉。","一区有地东之偏，甃池那用青铜钱。","池深怪我欲何事，聊以贮此千斛泉。","华峰船藕谁能掘，玉井千年亦空竭。","无缘高觅十丈根，随骑等閒来百粤。","朱明守夏薰风凉，花开正作黄金妆。","红者惟红白者白，宫城十里飘清香。","金鱼无数长过尺，出水荷翻尾摇赤。","地底休誇锦作铺，古来浮浪皆陈迹。","石鲸风动昆明寒，华清堕翠成阑珊。","何如此池开半亩，直与君子长交欢。"]},{"t":"春晓","f":"七言古诗","c":["宫壶夜尽铜龙水，万户千门晓钟里。","美人犹自拥罗衾，刚被绿窗莺唤起。","我时起坐围锦屏，深宫讵敢忘晨兴。","韶华明媚有如许，况与丰年上瑞并。","园官走报春将老，骇紫惊红花正恼。","朱衣小队随肩舆，亭沼悠然胸次好。","春风看遍名园花，坐对芳尊恋物华。","凤笙龙管百年醉，但令颜色如丹砂。"]},{"t":"西园竹","f":"七言古诗","c":["渭川半亩西园竹，远比猗猗在淇澳。","和烟带雨初移来，一片鸣珰响清玉。","出林新长万琅玕，阶前日日报平安。","箨龙满地碍行径，飕飕风动生清寒。","雅性从来无所好，独爱此君频索笑。","呼童汲水煮新茶，坐对吟诗更奇妙。","汝生气味同吾人，德音自是吾嘉宾。","虚心直节每相许，岁晚为我添精神。","垂垂拟结千年实，凤鸟飞来还恣食。","等閒月下有人过，乞与回仙制长笛。","露华如洗翠作丛，铿金击石声摩空。","出门如见此君在，犹愧当年卫武公。"]},{"t":"读李太白诗","f":"七言古诗","c":["天上酒星终日醉，寒芒犹占长庚位。","敢入蟾宫窃侍儿，酣迷不省身遭累。","一朝天帝怒且嗔，自天谪降埋红尘。","长安市上酒家卧，睨视四海如无人。","莲峰为笔天为纸，天纵奇才厌馀子。","斗酒真成诗百篇，秀似芙蓉出秋水。","醉来花下还一呷，遮莫清光照华发。","海吸鲸吞未放乾，等閒字字皆英发。","有时踏翻鹦鹉洲，有时搥碎黄鹤楼。","偏师突出敌崔颢，肯让区区先一头。","可惜仙才竟弃捐，江头弄月身翻然。","骑鲸万里上天去，精灵料得归星躔。","文章流落在人世，万丈虹蜺烛天地。","何当烈火鍊黄金，为铸斯人示吾契。"]},{"t":"题山水卷","f":"七言古诗","c":["万朵芙蓉插天碧，叠嶂层峦森列戟。","云外鸟啼松径深，渡头冰泮春流急。","落花飞絮踏成泥，兰茁紫芽蒲叶齐。","桃花依约天台路，烟霞彷佛武陵溪。","物外神仙居海岛，琼芝珠树连瑶草。","楼阁参差入望迷，眼前便觉人寰小。"]},{"t":"林良双凤鸣阳图","f":"七言古诗","c":["岭南画师称国手，出入相门呼老友。","意态居然成一家，风流奇绝前无偶。","朝阳赫赫来天东，一轮涌出海霞红。","羲和如驾复停驭，高冈对峙鸣雌雄。","九苞瑞世仍华国，灵囿千年宁复得。","文明有象入清朝，指鸟何人敢狂惑。","画师文采亦出尘，阿阁清严为写真。","眼前多少啁啾状，肯使凡毛易混珍。","庭院风清竹梧细，隐约枝头声哕哕。","四座周回展卷看，此身如在苍姬世。"]},{"t":"弘治辛亥夏久雨","f":"七言古诗","c":["万里阴云阔如席，太空欲净风无力。","老龙下捲河水乾，咫尺终南浑莫识。","昼夜翻盆未肯休，宫庭行潦成横流。","千门万户虞覆压，顾我仍怀杞国忧。","秦川父老念禾麦，坐视泥涂愁窘迫。","三边赋税积如山，转运动烦千万石。","安得阳乌现海东，照彻后土天之中。","照彻后土天之中，遂令佳气回年丰。"]},{"t":"假山","f":"古风","c":["金天昨夜风雷起，知是巨灵移碨礧。","擘破莲花第一峰，为吾安置庭除里。","云根耸立本天成，苍苔无数雨中生。","仇池不羡石为宝，等閒相对怡心情。","有时吟咏消尘虑，信步推敲忘去住。","竟日从容到上头，四顾悠然适佳趣。","绿窗朱户厌深宫，雕阑倦赏延州红。","何如身在小蓬岛，飘飘两袖乘天风。","剩欲开尊?一醉，不须远召东山妓。","掀髯唤起谪仙人，酒边敲碎玉如意。"]},{"t":"绿阴清昼","f":"七言古诗","c":["金炉香烬日初永，鼓吹声闻厌蛙黾。","槐阴满地翠且重，水畔坐移帘底影。","飘飘天末轻风来，凉生小殿胜蓬莱。","苑墙花雾尚红湿，来青楼下净飞埃。","谈边霏雪能销暑，宾从凭谁供笑语。","綀衣隔竹敲南薰，一曲潇湘带烟雨。","支颐尤爱诵南华，逍遥物外奚纷哗。","小奴引绠汲深井，为我细煮黄金芽。","朱阑绣户遮筠箔，翠袖红裙恣欢谑。","扰扰浮生醉梦中，白昼如年惜抛却。"]},{"t":"听嵇美中弹琴","f":"七言古诗","c":["有客有客携焦尾，玉立庭阶俨容止。","胠囊为我拂金徽，一泻幽怀弄清徵。","游心太古契冰弦，五音高下声相宣。","调成起立命之坐，焚香先鼓南薰篇。","初疑眤眤语儿女，指下丝声写凄楚。","忽然放手如风生，猛士战场齐奋举。","须臾一段在高山，穿云裂石谁能攀。","终南泰华几千仞，恍惚置我庭除间。","宫沈羽振复流水，倒泻银河犹未已。","龙门九折出昆崙，骇驶惊翻千万里。","吾生雅澹厌纷纭，赵瑟秦筝浑蔑闻。","为君净洗钟生耳，共随白鹤巢松云。"]},{"t":"子昂万竿烟雨卷","f":"七言古诗","c":["风流学士宋公子，玉堂挥洒金壶水。","渭川千亩贮胸中，烟雨都归笔锋里。","筼筜无数长琅玕，彩凤飞来玉宇寒。","箨龙蜕骨何太暮，孤梢还拂云之端。","隔世可人如对立，凄迷浓墨看犹湿。","百年心事付南枝，疑共湘灵夜中泣。","呜呼此老神仙流，七绝奚啻此君遒。","苕溪山水亦何意，令人独说东陵侯。"]},{"t":"闻莺","f":"七言古诗","c":["长安雨霁东风急，满目春光逾六十。","鸳鸯睡暖燕初来，金衣公子正愁湿。","苑墙雾薄花欲然，一声啼出墙东偏。","美人楼上暂停绣，歌喉宛啭相留连。","过耳好音真有限，翻讶枝头争睍睆。","肩舆驻听还低徊，似向花前催酒盏。","欲凭鼓吹鸣诗肠，青春白日何悠扬。","丁丁伐木起遐思，出谷迁乔咏不忘。"]},{"t":"闻余士英都宪征西得捷时予国戚廖廷玺都阃在麾下得功尤多","f":"七言古诗","c":["年来小丑何陆梁，蚩蚩敢尔窥边疆。","我军未出本持重，坚壁清野归牛羊。","尘沙捲地惊都护，上请龙颜赫斯怒。","临轩授钺谁敢当，视师乃有唐裴度。","公才况是眉山英，凿凿胸中皆甲兵。","指麾一扫无遗穴，四塞河湟金鼓鸣。","维时亦有廖都帅，勇冠三军气尤迈。","挥刀上马轻如飞，叱咤一声敌尽败。","视师严毅都帅雄，白日杀伐生天风。","铙歌新奏凯旋曲，万马骄嘶如蹴空。","文雄露布走双骑，捷报欢呼动天地。","边人安枕乐耕桑，酒熟蒲萄几家醉。","圣恩稠叠赏元功，文资武级兼高崇。","凌烟阁上动光采，会写余公与廖公。"]},{"t":"送致政蒋用璋知县还吴","f":"七言古诗","c":["长安陌上花正飞，苏台游客初辞归。","一年南北慕丰采，相见那忍仍相违。","关陕适逢天久旱，山川草木无精辉。","灞陵行馆尽萧索，满道流移恒苦饥。","秦人半死委沟壑，肝脑涂地豺狼肥。","送君此日空惆怅，离筵把酒风吹衣。","嗟君夙昔多抱负，眼见颠连忍含哺。","济时长策满胸中，袖手胡为乎中路。","江南景物吴门偏，风月常随诗酒船。","纶巾野服任萧散，飘飘俨若瀛洲仙。","忆君年少曾登第，百里花封民感惠。","官轻便觉折腰难，墨绶铜章遽捐弃。","流光庆泽钟贤郎，广寒丹桂飘天香。","十载灯窗富文学，飞黄指日当腾骧。","愿言行义以达道，登庸慎莫仍韬光。"]},{"t":"四时词 其一","f":"七言古诗","c":["东君着意净尘土，无限春藏旧花坞。","风雷初动曲江头，鞭起苍龙夜喷吐。","喷云作雨结微阴，红绿扶春上远林。","秋千院落人如玉，一刻直抵千黄金。","绿窗风暖语鹦鹉，香气薰人日亭午。","海棠睡足倚雕阑，花罥游丝帘外舞。","凤笙龙管金叵罗，乌衣能舞莺能歌。","春光九十转头去，有酒不饮如诗何。"]},{"t":"四时词 其二","f":"七言古诗","c":["长安炎蒸无地著，望望翠乾云扫岳。","南来天上火龙飞，谁敢冲烟犯头角。","宫院沈沈白昼长，槐阴满地蔷薇香。","水晶帘动侍儿入，玉壶金碗供寒浆。","碧池荷叶圆如镜，为折荷花断荷柄。","捲来荐酒藉清香，满泛流霞飞逸兴。","鬅鬙露坐日养慵，三庚惮暑难为容。","乘酣直欲袖明月，飞上终南第一峰。"]},{"t":"四时词 其三","f":"七言古诗","c":["金天凉冷金风急，万点金萤照宫掖。","银床夜夜落梧桐，宫树朝来零露湿。","乘闲试上来青楼，咫尺南山入远眸。","阑干徙倚括奇观，诗成敲折珊瑚钩。","东篱采采黄金蕊，远致南阳菊潭水。","安排服食制颓龄，水味花香溅牙齿。","酒满金罍秋月明，可人别去不胜情。","短书欲寄何由达，万里长天一雁声。"]},{"t":"四时词 其四","f":"七言古诗","c":["长安一夜酸风吼，雪片朝来大如手。","红炉乍煖凤笙温，旋割羊羔荐春酒。","金天肃杀春到迟，貂裘无奈冷相欺。","小奴走报启扉入，梅花方著东南枝。","雪霁怀人动清兴，剡溪灞上多奇胜。","呼舟策蹇两相妨，区区富贵谩千乘。","方阁护云颜渥丹，青绫纸帐薰沈檀。","人间清夜不成寐，天上琼楼几许寒。"]},{"t":"长江万里图","f":"七言古诗","c":["江豚吹浪江风起，地坼惊蛇绾江水。","日暮津头愁杀人，极目烟波几千里。","扁舟南下急张帆，黄头屏气窥惊湍。","天吴戟手真可畏，始信人间行路难。","寄声射利千金子，水马乘危恐难恃。","一朝宛见蹶霜蹄，忍使全躯饱鳣鲔。","忧谗更忆南迁客，独倚危樯心欲拆。","故园京国路茫然，黑首须臾变成白。","黄芦两岸栖渔翁，钓丝轻飏随西东。","得鱼沽酒亦自喜，不落人间风浪中。","坐阅此图长太息，蜗名蝇利竟何益。","争似青山卧白云，瓦缶泉香漱终日。"]},{"t":"四美人图为永寿王东轩题 其一","f":"七言律诗","c":["春宵苦短春昼长，梦回残月穿回廊。","西楼晓晴花气重，东风吹入帘栊香。","起傍雕阑久延伫，雾煖只愁花睡去。","高烧银烛绕花傍，唱彻金鸡海天曙。"]},{"t":"四美人图为永寿王东轩题 其二","f":"七言律诗","c":["绿烟散尽天如洗，露滴银床尘不起。","寒冰一片湿欲流，冷浸碧空秋万里。","倚阑相对不胜情，翠袖飘风舞态轻。","香烬宝炉檀板歇，桂花阴底夜三更。"]},{"t":"四美人图为永寿王东轩题 其三","f":"七言律诗","c":["银蟾夜落金盆冷，玉手翻波弄晴景。","广寒移入水晶宫，掌上分明见清影。","深闺静悄不成眠，欲问嫦娥路渺然。","秦楼人去彩鸾杳，冰光此夕因谁圆。"]},{"t":"四美人图为永寿王东轩题 其四","f":"七言律诗","c":["惜春无计留春住，手撚花枝绕花树。","嫩红深白总堪怜，来往徘徊不能去。","归来妆阁日未曛，满身花露喷馀芬。","笑舒玉指捲双袂，试问女奴闻不闻。"]},{"t":"秋夜即事","f":"七言古诗","c":["深宫夜静金风冷，满地梧桐漏疏影。","月华漾漾露零零，长唳一声闻鹤警。","我时无睡倚床屏，百感中来万事并。","披衣起步庭阶下，不觉技痒诗相萦。","金炉爇火焚龙脑，偶尔诗成问房老。","试听吾诗汝解不，玄酒元来淡方好。","银烛高烧夜未央，隔帘爽气侵衣裳。","侍儿似解主人意，得句便欲移新腔。","对景谁能负今夕，佐兴还须泻云液。","试教歌我秋夜篇，一片商声振金石。"]},{"t":"玩假山池亭","f":"七言律诗","c":["新碧鳞鳞涨沙渚，一点红尘飞不起。","好山四面画屏开，百斛青螺净如洗。","从倚阑干日正长，濯缨何必临沧浪。","假山虽假有真趣，云影倒蘸涵天光。"]},{"t":"怀马天禄少卿","f":"七言古诗","c":["可人昔自长安别，别后音书成断绝。","五云宫阙郁岧峣，几度瞻天仰卿月。","忆君承诏似登仙，双旌北上何翩翩。","左右执法赖平允，释之定国真齐肩。","曾侍玉皇香案侧，十载弹文飞白雪。","暂令仙鹤下人间，独立霜毛誇峻洁。","魁选人称倚马才，至今价重黄金台。","诗成四韵只三步，敏捷何烦击钵催。","外台最好能持节，精鉴时髦类澄澈。","陈陈诗案积如山，到处淋漓有题墨。","自君之去几经春，索君深愧秦无人。","凄凉空赋怀贤咏，渴心日日生埃尘。","朝来有使金台去，草草椷题寄长句。","停云千里倚阑干，满地清风起庭树。"]},{"t":"送道士还山","f":"七言古诗","c":["山人只在山中醉，醉爱白云深处睡。","偶然卖药入城闉，手抱瑶琴见清致。","猗兰古调竟何之，当轩为我鸣朱丝。","曲终狂笑天地窄，三斗自吸宁能辞。","虚名抛掷如敝屣，只说终南多石髓。","一匕入口甘如饴，辟谷于今若干纪。","拂袖携囊归旧巢，天风满路轻飘飘。","凌空一跃仙人杖，拄倒来时旧铁桥。"]},{"t":"梦萱为新斋兄赋","f":"七言古诗","c":["当年堂北萱花开，慈亲正少儿提孩。","今日慈亲竟何逝，忽惊风雨萱花摧。","谁道吾家风景好，慈闱寂寞萱花老。","罔极常思鞠我恩，未应唤作忘忧草。","长夜沈沈宫漏迟，氤氲宝篆销金猊。","神游天上隔风雨，今夕分明梦见之。","醒来感叹情何极，举目茫茫泪沾臆。","伤心不忍睹兹花，尘满北堂空伫立。","徘徊我亦绕花傍，仙源一脉同天潢。","七龄慈母早见背，此恨相为天地长。"]},{"t":"女仙图","f":"七言古诗","c":["碧桃花外飞青鸟，金母麟车踏瑶草。","御书有约会麻姑，弱流遥望蓬莱岛。","天风飒飒吹霓裳，九霄环佩声琅琅。","双成手把玉如意，车前作伴呼阿香。","尘埃难染圭璋质，名姓生来入仙籍。","云窗雾阁隔人寰，陌上少年空自惜。","燕罢瑶池拾翠翘，玉箫声断彩云飘。","阳台总是荒唐梦，金屋何须贮阿娇。"]},{"t":"春江捕鱼图","f":"七言古诗","c":["昨夜震霆难掩耳，朝来江上添新水。","万鱼喁噞讵知名，粗识鲦鲿与鰋鲤。","鳣鲔胜舟大更长，个中滋味推鲈鲂。","河豚珍重西施乳，入喉但恐生锋铓。","往来尽爱江鱼美，扁舟出没波涛里。","腥风起处动冯夷，一网千头贵知止。","江花照眼江水肥，鼓枻江头及早归。","水底蛟龙能覆柂，相看多少蹈危机。"]},{"t":"寄暹日华上人","f":"七言古诗","c":["浮屠几许栖京师，白足登坛惟阿师。","落纸争求怀素字，逢人多诵贯休诗。","大颠曾致昌黎老，参寥更与坡翁好。","文章蔬笋气全无，论到阿师每倾倒。","早年投礼大医王，活人功效非寻常。","调和不假万金术，湔洗惟凭三昧汤。","向来为我飞金锡，甘露分尝蠲宿疾。","野鹤闲云恣所如，飘然何处寻踪迹。","金色界中曾结缘，于今烈火生红莲。","能来更为住三宿，慈海期登般若船。","带砺河山逢圣代，已證金刚真不坏。","因缘早现国王身，有发何妨持五戒。"]},{"t":"琴书自乐","f":"七言古诗","c":["我家肇造自皇祖，我祖分茅守西土。","嗣予理国日兢兢，宁敢流连纵歌舞。","宁王吹笛岐王醉，肉盘多少申王妓。","猎车十乘走南山，浪说齐王多快意。","前鉴斯人皆覆车，吾之二友惟琴书。","五弦远慕有虞圣，六籍学为孔子徒。","琴满锦囊书满库，游心太始何真素。","百年三万六千日，日日追陪送乌兔。"]},{"t":"哀娄克让方伯","f":"七言古诗","c":["忆昨西台持宪节，金玉当筵识颜色。","每同苑圃赏春花，更与池亭醉秋月。","怜君文雅复能诗，等闲出口皆奇辞。","清音不啻振金石，妙思真如抽茧丝。","一从作牧西川去，食少事烦劳百虑。","漏天湿暗芙蓉城，晴雪光摇紫薇署。","去年听说监文场，六经入手生寒芒。","精神坐耗真可惜，冰魂雪魄成茫茫。","赤虬天上来符吏，知是虚皇徵作记。","空堂永夜冷凄凄，寂寞谁承身后事。","兰台柱史重歔欷，为作祠堂在棘闱。","我亦临风歌楚些，还思化鹤一来归。"]},{"t":"题脊令图","f":"七言古诗","c":["黄芦瑟瑟吴江冷，烟月空濛湿秋景。","脊令对对在原头，来往飞鸣翻瘦影。","何人写此意应殊，生色初疑造化俱。","世情徒解誉名笔，我独临风悲友于。","忆昔同胞将七弟，钟爱先王分一气。","凤雏龙种竟难成，芳草斜阳尽捐弃。","黄金色相玉精神，暂缘谪限留风尘。","不是吾家吝茅土，多应霄汉回星辰。","谫薄嗟余嗣重位，国玺相传恒恐坠。","披图忆弟更思亲，独立乾坤洒清泪。"]},{"t":"陈所翁双龙卷","f":"七言古诗","c":["云满虚空雷电激，风猛波翻江海立。","双龙奋出同蜿蜒，头角峥嵘烟雾湿。","所翁疑是人中龙，沧溟曾与龙相逢。","等闲落笔写神异，分明首尾成雌雄。","斯翁久矣骑龙去，遗墨千金叹神遇。","高堂展玩忽生寒，六月令人毛发竖。","怪哉此卷须珍藏，通灵变化非寻常。","床头深夜动风雨，秪恐破壁倾淋浪。"]},{"t":"寿伯汧阳王六十","f":"七言古诗","c":["乾坤万里来春风，天开寿域天昭融。","天人降诞乃今日，葱葱瑞气腾苍穹。","吾藩尊行惟吾伯，锡爵汧阳绵世泽。","忠孝贤声彻帝聪，文章令誉光先德。","群仙入贺启华筵，龙管鸾笙声沸天。","宗室儿孙今万亿，遐龄同祝三千年。","维王乐善慕东平，遥遥相望真齐名。","却笑刘安困金石，时人浪说终飞升。","吾爱吾王何所祝，努力加餐休辟谷。","长生不老对南山，日日平安膺五福。"]},{"t":"题凤翔赵太守红梅图","f":"七言古诗","c":["凤翔太守非凡夫，见我手执红梅图。","猩红万点照人眼，恍疑击碎新珊瑚。","乾坤佳丽江南好，染出一枝春信早。","北人未识误呼名，梅格凭谁诘诗老。","我园亦自有红梅，移根元自江南来。","万花头上占春色，粗桃俗李徒嫌猜。","太守长才足经济，郡斋坐对收清气。","何当携取真盐梅，为我天家调鼎味。"]},{"t":"端阳日池亭对雨","f":"七言古诗","c":["何事秦人怜楚节，家家蒲酒相怡悦。","苫居嗟我久忘情，停诵蓼莪罢朝谒。","肩舆暂出坐池亭，悠然喜见南山青。","忽惊头上黑云起，四檐飞瀑声泠泠。","却忆吴侬当此日，竞渡龙舟逞飞疾。","锦幖夺得气凌人，不管沈骸坠蛟室。","从来楚俗恤无辜，千古犹怜屈大夫。","角黍綵丝传故事，三闾精爽今存无。","为话前贤挥玉麈，汨罗江远伤遭遇。","离骚读罢鉴前王，谩听淋漓池上雨。"]},{"t":"和苏长公聚星堂禁体雪诗韵","f":"七言古诗","c":["簌簌窗前蚕食叶，知是尖风又吹雪。","烟消榾柮地炉寒，兀坐书空正愁绝。","后园脩竹委长身，戛戛声中都压折。","幽禽冻杀不知数，猛虎深林踪迹灭。","海底灵鳌亦伏藏，纵有长竿孰能掣。","冻芽满地未穿土，安得盈筐供采缬。","呼舟策蹇亦何事，来往搜奇徒屑屑。","人生有酒但宜醉，回首光阴真一瞥。","仰面呜呜双耳热，功名富贵吾何说。","只恐诗成不著题，铸错难聚九州铁。"]},{"t":"题姮娥归月画","f":"七言律诗","c":["嫦娥飞入清虚府，贝阙珠宫隔尘土。","万古青铜竟不磨，谩劳八万三千户。","有时自抱玉兔归，露华沁湿春云衣。","天上高寒谁与侣，桂影婆娑香雾霏。"]},{"t":"挽李都阃","f":"七言古诗","c":["火星坠营天欲泣，万木冰生夜僵立。","旌旗影淡塞云黄，笳鼓声沈朔风黑。","辕门虎将真丈夫，雄姿赳赳何魁梧。","半生豪放纵所适，意气落落吞江湖。","一剑沙场奋威武，誓欲将身报明主。","马革裹尸志莫酬，嗟乎无乃天之数。","忠魂自昔飞上天，回首人间二十年。","流水落花空寂寂，斜阳芳草自芊芊。","将门有将三军帅，能读父书六韬在。","相机制胜无拙谋，拜将封侯应可待。","天恩旷荡贲泉扃，山川草木皆光荣。","平生心事料无憾，英风凛凛还如生。"]},{"t":"秋闺","f":"七言古诗","c":["铜龙漏咽良宵永，风透玉楼罗袂冷。","倚遍阑干思悄然，云鬟斜亸谁为整。","溅齿梅酸蹙黛蛾，闲愁默默当如何。","举头碧落星河淡，露下空庭金气多。","归来香烬银缸灭，半窗凉影梧桐月。"]},{"t":"红梅","f":"七言律诗","c":["美人宴罢罗浮月，一片春云锦屏热。","困倚东风逞醉妆，水晶宫里飞香雪。","宿酲满颊朝未消，脱却素衣披绛绡。","岁寒自许心如铁，俗李粗桃徒尔娇。"]},{"t":"沈启南写山水花禽四幅见寄以诗答之","f":"七言古诗","c":["石田居士东吴叟，人品清高称妙手。","诗中兼画画兼诗，酒后放歌歌放酒。","平生怕入利名场，胸中万顷涵沧浪。","兴来濡笔写天趣，坐令万象无精光。","信手画山还画水，幻出山僧与仙子。","珍禽异草入乌丝，怪石苍松落书几。","昨朝有使东吴来，囊封千里轻琼瑰。","高堂展玩那忍弃，不觉令人心眼开。","君才诗画真三绝，肯让前朝赵松雪。","乾坤游戏了馀生，海内何人呼俊杰。","一缄简札遥相闻，却恨关山隔暮云。","记取蓝田餐玉法，殷勤传去一酬君。"]},{"t":"喜西安严太守祷雨有感","f":"七言古诗","c":["火云衔日烧天地，万井炎蒸腾火气。","终南泰华翠欲乾，水底乖龙正昏睡。","大造茫茫不可呼，天符何事封江湖。","岳神不敢作云雨，三川二麦垂焦枯。","神明太守共天职，廉平允合神明德。","朝祈暮祷曲江池，马上去来无倦色。","南山缚虎斫其头，黄冠持篆沈中流。","绿章飞奏沥肝胆，天门夜启风飕飕。","帝命金童追雨部，顷见云师布天宇。","雷声震起五方龙，三日淋漓泻膏乳。","二麦从今庆有秋，更期百谷盈西畴。","官家在在足仓廪，烝黎处处兴歌讴。","旱魃潜回灾沴息，多君独有回天力。","秦人若解纪声诗，穹碑定伐南山石。"]},{"t":"后园写景","f":"七言古诗","c":["城中寸金营寸土，我爱斯园带花坞。","依稀风景小蓬莱，始信神仙有宫府。","钱刀不惜走天涯，殷勤远致江南花。","沿阶异草多葱茜，参天老木何槎牙。","谁移泰华终南石，巧作山峰叠青壁。","山下池中几种莲，赤白红黄更青碧。","金鲤银鲂玳瑁鱼，往来自适恒如如。","一点尘埃飞不到，水晶宫殿涵清虚。","花时最爱花王好，魏紫姚黄开更早。","玉盘斜瑩寿安红，却为迷离被花恼。","两行槐幄夹高柳，时送清风到窗牖。","绿阴啼鸟共幽人，爽气自能消宿酒。","黄花采采开深秋，满林红叶霜初收。","几度醉游明月夜，天香万斛沾轻裘。","山头一夜风吹雪，万木萧条寒栗烈。","索笑闲寻绿萼梅，三种还分蜡红白。","松柏苍苍桧竹青，相看同结岁寒盟。","满前好景道不得，四时诗兴还相萦。","柏台豸史薇垣老，吴语诗翁共襟抱。","能吟宾从亦相从，好谜奇猜多绝倒。","优游幸际太平时，有园有酒宁无诗。","但愿花开诗侣健，年年共醉黄金卮。"]},{"t":"和杨应宁佥宪咏雪韵","f":"七言古诗","c":["尘世茫茫昏又晓，眼底何人能了了。","闻君玉节驻分司，试卷委填知几抱。","是时天女剪冰花，妆点人间何太巧。","对此犹疑万玉妃，缀凤裁鸾竞相效。","丰年有兆笑声多，无那贫儿却成恼。","萧条门巷断人行，风沙扰地凭谁扫。","江山觱栗如摧枯，一夜长梢都压倒。","乾坤幻作水晶宫，玉峰万仞成纤眇。","侵凌亦有堂前萱，不及梅花颜色好。","海云滚浪还促空，倒撒珠玑落天表。","驿途来往亦良苦，驱驰不异蓝关道。","推敲马上有新诗，象外神游劳腹稿。","形容变态步今古，大笔端能补天造。","周诗曾咏屡丰年，谁识丰年为国宝。","百谷于人皆有功，岂若来牟最收早。","我愿东西南北人，鼓腹熙熙各温饱。","老翁击壤不知寒，倚醉欢呼臂先掉。","行台题咏极清新，眼底如君应最少。","长歌和竟起清风，坐拥冰壶天杳杳。"]},{"t":"勤有斋","f":"七言古诗","c":["六经充栋填华屋，插架更馀三万轴。","黄金散尽宝奁空，犹自逢人叩书目。","汧阳老伯吾藩尊，积书远欲贻儿孙。","自恐疏慵陷骄惰，手持黄卷穷朝昏。","鸡鸣起坐更终日，隐几吾伊忘饮食。","小斋帘捲麝煤销，不管青衣花外立。","夜归蜡炬射金莲，犹对朝来未尽编。","穷搜苦索肯辞倦，翻笑当年边孝先。","无限好书皆烂熟，磊落争誇载其腹。","有时延访出朱扉，应有诸儒羡书簏。","万卷开残不可当，直从今日尽羲皇。","挥毫顿觉鬼神泣，嘻笑怒骂皆文章。","始信诗书勤乃有，子建安能专八斗。","有斐无惭淇澳诗，珍重吾藩有耆耇。"]},{"t":"恕斋","f":"七言古诗","c":["二气于人均禀赋，圣贤亦自由人做。","我家老伯绍前脩，识得如心之谓恕。","当年子贡请终身，仲尼教戒何谆谆。","一言说破用无尽，已所不欲无施人。","小斋斗大聊容膝，华扁相看警朝夕。","物情世态任纷拿，以理消除真有益。","阿翁心地自旷然，何须问道更参禅。","有德元来食阳报，定知遐算垂千年。"]},{"t":"宫人戏婴","f":"七言古诗","c":["宫漏迟迟清昼长，落花乳燕春茫茫。","君王放蝶恣游幸，三千粉黛争辉光。","何物佳人独沾宠，流苏帐煖生龙种。","眉目分明画不如，一颗明珠掌中捧。","侍儿稳抱近华清，笑啼时作呱呱声。","奋身似欲就其母，招呼解识宫娥名。","内家堕地皆宗子，分得天潢一泓水。","大者为王小者侯，继继绳绳永无已。","却笑三郎懒作家，恣渠野鹿衔宫花。","锦绷儿娇玉环醉，金钱赐予何其奢。","良工画此非无意，用戒宫闱禁儿戏。","古来惟数太任贤，胎教文王传万世。"]},{"t":"携琴访友画","f":"七言古诗","c":["危峰削玉插晴空，淋漓秀气含鸿濛。","两间万物有时易，惟有青山今古同。","隐君山下营茅屋，烟霞笑傲逃尘俗。","日长心境鹤俱闲，自扫白云松下宿。","溪头野老行迟迟，杖屦携琴过竹篱。","猗兰调古少人听，等闲来此寻钟期。"]},{"t":"芭蕉","f":"七言古诗","c":["朱弦弄罢南薰起，雨过空庭净于洗。","太湖石畔绿䕺䕺，新叶乱抽青凤尾。","隔户还疑拥碧幢，更宜石下水淙淙。","美人翻恶湿阴重，日午停针围绣窗。","我时散步来还去，为爱清奇闲倚柱。","吟成却忆横渠翁，新德新知引新趣。","剩欲题诗留醉墨，只恐西风凋翠叶。","何当写入无声诗，永向吾斋助奇绝。"]},{"t":"葵榴","f":"七言古诗","c":["南风催送东风去，锦绣离披万花树。","眼前富贵竟成尘，喜有葵榴供逸趣。","我爱丹心向太阳，肯随桃李争芬芳。","更喜朱英喷真火，累累成实包天浆。","飞蝇不到宫庭肃，隐几相看乐幽独。","窗前一雨洗深红，更露本来真面目。","藩维事简守真一，鼓罢虞琴玩湘帙。","兴来咏物适閒情，一笑优游且消日。"]},{"t":"雨中漫兴 其一","f":"五言律诗","c":["空庭人寂寂，深院雨濛濛。","博具棋无敌，愁城酒有功。","苔痕沿砌绿，花蕊堕林红。","闭户真为乐，交情异孔融。"]},{"t":"雨中漫兴 其二","f":"五言律诗","c":["一室惟容膝，閒吟散郁烦。","宫云浓泼墨，窗雨急翻盆。","地僻人来少，心清道自尊。","真宜守渊默，世事不须论。"]},{"t":"雨中漫兴 其三","f":"五言律诗","c":["岁月如流水，新年异旧年。","閒眠非病酒，痴坐类癯禅。","乳燕双翻雨，饥鸢独戾天。","自知心有主，肯被俗情牵。"]},{"t":"雨中漫兴 其四","f":"五言律诗","c":["风雨连朝恶，馀寒尚袭衣。","莺花经目老，车马及门稀。","自喜一心静，休论万事非。","任渠群燕雀，终日傍檐飞。"]},{"t":"雨中漫兴 其五","f":"五言律诗","c":["腐迂甘守约，澹泊讵云悭。","谋巧翻成拙，才疏只类顽。","肯因身外事，变却镜中颜。","日日钩帘坐，悠然对晚山。"]},{"t":"雨中漫兴 其六","f":"五言律诗","c":["地僻尘嚣少，斋居坐晏如。","清风回枕簟，细雨润琴书。","野竹当窗密，山云入座虚。","自缘非吏隐，能与世情疏。"]},{"t":"雨中漫兴 其七","f":"五言律诗","c":["对景多清兴，悠然得趣时。","閒临怀素帖，细咏少陵诗。","往事皆天定，前贤不我欺。","达人斯契合，处世复奚疑。"]},{"t":"雨中漫兴 其八","f":"五言律诗","c":["俯仰浑无累，迂疏百不能。","未忘君子操，肯畏俗夫憎。","古调轻齐瑟，新诗付剡藤。","萧然无物我，兴味似山僧。"]},{"t":"晚眺","f":"五言律诗","c":["云散雨初收，乘閒独倚楼。","岚深青可染，树重翠将流。","斜日林间下，轻烟象外浮。","严城将试钥，点点乱鸦稠。"]},{"t":"春日喜晴","f":"五言律诗","c":["长空开霁色，腐草亦生辉。","列岫螺千斛，群花锦万机。","林深山鸟弄，天阔野云飞。","莫负寻芳约，韶华过眼稀。"]},{"t":"丙午元夕遇雪","f":"五言律诗","c":["今夕为元夕，玄冥苦作威。","袭衣风猎猎，扑面雪霏霏。","里巷笙歌歇，楼台灯火稀。","定知丰稔兆，宁叹赏心违。"]},{"t":"寄戴松崖宪副","f":"五言律诗","c":["南北路漫漫，长嗟会面难。","碧桃开复谢，黄菊看将残。","露冷蛩声切，天空雁影寒。","夜深惟有梦，飞度越江干。"]},{"t":"秋声","f":"五言律诗","c":["凉飙起天末，万籁发商音。","候雁霜前度，寒蛩月下吟。","小楼吹短笛，何处捣残砧。","满耳秋声入，离人思不禁。"]},{"t":"残月","f":"五言律诗","c":["嫦娥倦梳掠，销瘦不如前。","镜面半收匣，弓眉初下弦。","影随更漏尽，光并晓星悬。","不用频嗟感，盈亏理自然。"]},{"t":"即景","f":"五言律诗","c":["一雨消残暑，金风起树端。","草根蛩唧唧，天末露漙漙。","地僻人偏逸，心清梦亦安。","吟成无个事，对景独凭阑。"]},{"t":"冬风","f":"五言律诗","c":["蜚廉从北帝，入丑恣威权。","细舞霜回瓦，高飞雪满天。","声寒催铁骑，势促脱韝鹯。","摇落群芳尽，松篁独挺然。"]},{"t":"十四夜月","f":"五言律诗","c":["二七中秋近，金波湛碧天。","似悭来夕满，却比昨宵圆。","白璧旋应合，青铜觑少偏。","嫦娥藏贝阙，妆束未能全。"]},{"t":"十六夜月","f":"五言律诗","c":["兔魄过三五，光同昨夜清。","嫦娥非有意，尘世自无情。","莫讶一分减，何伤千里明。","达人穷物理，应解戒持盈。"]},{"t":"春晓","f":"五言律诗","c":["万井一声鸡，晨光渐不迷。","林梢金镜暗，楼外玉绳低。","露重花偏湿，风和鸟缓啼。","惜春人起早，香雾散轮蹄。"]},{"t":"松风","f":"五言律诗","c":["灵籁生何处，巢笙更越琴。","穿林惊鹤梦，入涧和龙吟。","万顷涛翻翠，千岩粉堕金。","坐来疑漱石，真可涤尘襟。"]},{"t":"对雨","f":"五言律诗","c":["叆叇浑无罅，淋漓不渐停。","平添深涧绿，净洗远山青。","足慰农夫望，休令旅客听。","林鸠啼未歇，花妥正冥冥。"]},{"t":"悲秋","f":"五言律诗","c":["草木皆摇落，清霜袭绮裘。","蛩声和露泣，月影带江流。","暗改潘安鬓，明添宋玉愁。","乾坤真逆旅，极目一登楼。"]},{"t":"九日席上次戴松崖先生韵","f":"古风","c":["九日斯文会，登高醉菊花。","酒?三斗尽，帽插一枝斜。","礼秩矜疏放，盘盂愧静嘉。","华笺写新句，香染墨如鸦。"]},{"t":"齐居杂兴 其一","f":"五言律诗","c":["地幽忘盥栉，心远觉逍遥。","喜共高人话，宁从俗士招。","雨晴花气湿，风细鸟声娇。","最爱春泉活，时分灌药苗。"]},{"t":"齐居杂兴 其二","f":"五言律诗","c":["深居谢尘鞅，萧散兴何长。","帘捲薰风细，窗涵夜月凉。","清谈挥麈尾，高卧据绳床。","车马长安客，浮生为底忙。"]},{"t":"齐居杂兴 其三","f":"五言律诗","c":["一面新开霁，悠然野趣真。","露悬蛛网湿，花落燕泥新。","皓月能随我，清风最可人。","好怀无处著，觅句肯辞频。"]},{"t":"齐居杂兴 其四","f":"五言律诗","c":["万事皆由命，行藏信所之。","推窗閒看竹，把卷细敲诗。","事少晨兴懒，吟多夜卧迟。","拊心江汉远，无补圣明时。"]},{"t":"张太妃挽词 其一","f":"五言律诗","c":["阿母乘鸾去，瑶池宴不归。","杜鹃啼有血，婺女淡无辉。","漠漠梨云冷，瀼瀼薤露稀。","生平多少恨，万事与心违。"]},{"t":"张太妃挽词 其二","f":"五言律诗","c":["早岁膺封册，嫠居五十年。","镜中鸾独舞，天外月空圆。","清苦共姜节，幽閒大姒贤。","白杨风起处，原草共凄然。"]},{"t":"甲辰元夕同戴松崖吴元素郑子初汤俟庵诸先生燕集时在镇安邸","f":"五言律诗","c":["长安初霁雪，元夕值丰年。","盛聚文章士，弘开翰墨筵。","星桥通贝府，火树烛瑶天。","莫惜今宵醉，流光等逝川。"]},{"t":"甲辰元夕","f":"五言律诗","c":["今夕复何夕，蟾光喜未阴。","笙歌嫌漏促，灯火觉更深。","人事如朝暮，年华自古今。","细翻新乐府，转调入沈吟。"]},{"t":"秋日即事","f":"五言律诗","c":["水净鹭拳沙，天空鹜带霞。","数声楼外雁，几点树头鸦。","露冷枫飘叶，霜轻菊吐花。","独怜关外戍，乡思动胡笳。"]},{"t":"题永寿王寿萱手卷","f":"五言律诗","c":["谁把宜男草，移来种北堂。","露滋鹄觜润，风袅凤翎长。","子爱颜偏好，母看忧自忘。","寿筵开此日，香溢紫霞觞。"]},{"t":"竹亭偶成","f":"五言律诗","c":["自笑耽幽僻，能忘对此君。","绿云环冉冉，苍雪落纷纷。","晚节经霜见，秋声入夜闻。","渭川湘水趣，未许俗人分。"]},{"t":"瑞香次韵","f":"五言律诗","c":["异种产南方，移来道路长。","牡丹空国色，桂子自天香。","雅有清癯意，浓无滑腻妆。","岁寒怜尔在，高出压群芳。"]},{"t":"有怀王尚文少参","f":"五言律诗","c":["目断江东路，怀人独倚楼。","蝉鸣黄叶晚，雁度碧云秋。","诗酒添新况，园池感旧游。","何时复相见，谈笑更绸缪。"]},{"t":"閒居漫兴 其一","f":"五言律诗","c":["藩邸多清暇，閒居爱日长。","疏帘晴霭散，小殿午风凉。","叠石诗中画，分泉静里忙。","伊人有高致，宁惜共徜徉。"]},{"t":"閒居漫兴 其二","f":"五言律诗","c":["古鼎袅馀薰，空庭绝点尘。","花香风外细，树色雨中新。","瀹茗延醒客，裁诗寄远人。","最便閒乐处，吾欲养吾真。"]},{"t":"夏多雨","f":"五言律诗","c":["时光临季夏，终日苦滂沱。","曲径深苍藓，方塘涨碧波。","炎威侵幌少，寒气袭人多。","为问调元手，阴阳理若何。"]},{"t":"题公子游春卷","f":"五言律诗","c":["玉勒鞚青骢，寻春上苑东。","绮罗明晓日，弦管沸春风。","杨柳摇杯绿，桃花夹座红。","鸟惊金弹落，归路夕阳中。"]},{"t":"夜坐有怀郑司寇时良 其一","f":"五言律诗","c":["青灯孤坐久，百感雨中生。","驻目关山隔，惊心岁月更。","寒蛩鸣四壁，征雁度重城。","歌罢停云句，寥寥梦不成。"]},{"t":"夜坐有怀郑司寇时良 其二","f":"五言律诗","c":["湖海论心少，惟君最我知。","几年成旷别，千里动遐思。","细雨灯残夜，寒风叶落时。","天涯云树隔，会晤杳难期。"]},{"t":"酒家","f":"五言律诗","c":["香篘闻十里，人指画桥东。","紫瓮盛秋露，青帘飐晓风。","曲尘飞柳外，檀板响楼中。","社鼓枫林急，村村卧醉翁。"]},{"t":"渔家","f":"五言律诗","c":["烟波为活计，结屋近沧浪。","地接黄芦岸，村开绿柳庄。","轻蓑冲细雨，小艇系斜阳。","斫鲙茅檐下，呼儿煮酒尝。"]},{"t":"元夕次韵","f":"五言律诗","c":["蟾窟当空满，鳌山动地来。","六街香雾合，万井户扃开。","烟火藏机弄，灯词作谜猜。","红妆人结伴，杳杳下楼台。"]},{"t":"苦寒","f":"五言律诗","c":["万象冰壶里，同云满太空。","闭门三日雪，刮面五更风。","羸马卧僵殍，冻鸱蹲老翁。","铁衣犹塞外，忍对地炉红。"]},{"t":"水阁","f":"五言律诗","c":["数椽依曲沼，高兴寓沧浪。","鸥鹭随波戏，菰蒲近岸香。","开窗山雨润，入坐水风凉。","应笑长洲苑，尘迷响屧廊。"]},{"t":"烟","f":"五言律诗","c":["似雾纷还郁，如尘散复迷。","斜阳芳草渡，细雨绿莎堤。","入坞笼花放，沿山瘴鸟啼。","何时天禄阁，照坐出青藜。"]},{"t":"华山","f":"五言律诗","c":["百里盘根远，孤高倚太空。","云开仙掌日，鸟度石莲风。","磅礴含元气，薰蒸妙化功。","终南与太白，未许并争雄。"]},{"t":"春雪","f":"五言律诗","c":["入臈宜三白，春风底用赊。","漫空欺柳絮，著树失梨花。","顷刻成行潦，微茫没浅沙。","眼前应有象，人事尽浮华。"]},{"t":"晴望","f":"五言律诗","c":["浓云归远岫，霁色满层空。","烟抹楼台碧，霞蒸草树红。","终南随鹘没，直北隐鸿蒙。","坐久疏帘静，凉生绿树风。"]},{"t":"先天观","f":"五言律诗","c":["路入无尘境，琳宫日月长。","紫芝生白石，绿竹荫丹房。","晓日鸾声哕，秋风鹤梦凉。","先天参透处，斟水醮虚皇。"]},{"t":"故宫","f":"五言律诗","c":["前代豪华地，烟尘一梦空。","燕归宫树老，鹿去苑花红。","辇路埋秋藓，歌楼散晓风。","御沟犹涨腻，流出恨无穷。"]},{"t":"云","f":"五言律诗","c":["肤寸起遥岑，晴空忽作阴。","卷舒空有态，聚散本无心。","伴鹤閒栖树，从龙惯作霖。","蓬莱常五色，应护斗间深。"]},{"t":"溪居","f":"五言律诗","c":["南市津相近，柴门日系船。","晓峰明似画，春水远如天。","鹅鸭应常数，凫鹥秪自怜。","夜来风雨恶，龙过屋山颠。"]},{"t":"夏夜","f":"五言律诗","c":["赤日当空下，轻飙送晚凉。","鬅鬙便露坐，沆瀣足天浆。","扇扑流萤乱，帘浮睡鸭香。","炎熇尚烦郁，苦乐未能忘。"]},{"t":"盆池","f":"五言律诗","c":["凿破庭前地，光含鉴影多。","雨馀添小涨，风急动微波。","冷浸一拳石，平铺数点荷。","儿嬉同泖曲，吾亦放吾歌。"]},{"t":"花影","f":"五言律诗","c":["重重还叠叠，万卉任荣枯。","日月照来有，亭台阴处无。","丹青谁着笔，水墨自成图。","只恐风撩乱，残花委地铺。"]},{"t":"过山家","f":"五言律诗","c":["岩壑结芳邻，衡茅远俗纷。","林深迟见日，石乱自生云。","树影当窗翳，泉声入座闻。","幽居同木石，鹿豕更成群。"]},{"t":"过田家","f":"五言律诗","c":["结庐依畎亩，耕作足生涯。","门巷閒眠犊，池塘乱叫蛙。","园收新芋栗，墙荫旧桑麻。","岁晚村翁会，比邻酒任赊。"]},{"t":"竹风","f":"五言律诗","c":["拂拂起林梢，扶疏影动摇。","湘娥鸣玉佩，秦女弄琼箫。","锦箨飘香粉，青鸾舞翠翘。","王猷当此际，尘虑定应消。"]},{"t":"绿筠轩","f":"五言律诗","c":["一区幽寂地，寒绿万竿馀。","秀色当窗见，凉阴入座虚。","风帘声簌簌，雨榻梦蘧蘧。","比管还吹凤，翩翩上玉除。"]},{"t":"拟早起","f":"五言律诗","c":["一枕梦魂清，披衣出户庭。","楼头低兔魄，屋角乱鸡声。","入市人稀到，开关戍未行。","东方看渐白，隐隐海霞明。"]},{"t":"惜花","f":"五言律诗","c":["一年春正好，莫放小车空。","绣幄笼晴日，雕阑怯晓风。","未能辞眼底，可忍污泥中。","百匝千回看，巡檐骇落红。"]},{"t":"春晴","f":"五言律诗","c":["长空新雨过，正及艳阳时。","淡淡东风软，融融丽日迟。","迷漫飞落絮，摇曳堕游丝。","紫陌寻芳遍，莺花处处宜。"]},{"t":"假山","f":"五言律诗","c":["凿破终南骨，移来置广庭。","巉岩从地立，峭拔类天成。","秀色凌苍霭，晴岚湿翠屏。","道人幽兴远，相对每忘情。"]},{"t":"秋雨","f":"五言律诗","c":["西风吹淅沥，檐溜响浪浪。","废沼添寒绿，疏林落萎黄。","天边迷去雁，阶下乱啼螀。","滴碎羁人梦，音书滞一乡。"]},{"t":"经横渠镇废寺","f":"五言律诗","c":["瞻彼空王宅，依稀旧迹存。","雨馀苔满壁，风搅叶堆门。","石鼎香烟断，崖碑字刻昏。","异僧回月下，扫石忆精魂。"]},{"t":"题荐福寺塔","f":"五言律诗","c":["浮图逾百尺，突兀倚层空。","人语半天上，鸟飞平地中。","宝轮朝炫日，金铎夜鸣风。","极目乾坤远，川流尽向东。"]},{"t":"道傍废宅","f":"五言律诗","c":["衡门终日掩，不见主人归。","春到花空放，年深草自肥。","颓垣多鼠穴，古砌上苔衣。","独有梁间燕，双双似旧飞。"]},{"t":"秋风","f":"五言律诗","c":["蘋末萧萧起，编茅尚几家。","井寒梧叶堕，圃老菊香赊。","阶下蛩声切，天边雁影斜。","晓来青镜里，吹鬓落霜花。"]},{"t":"赏春","f":"五言律诗","c":["春光明远近，红紫正芳妍。","野外张帷幄，风前沸管弦。","绮罗人拾翠，騕袅客停鞯。","落日城南路，香尘障瞑烟。"]},{"t":"题山寺亭壁","f":"五言律诗","c":["面面峰峦秀，开窗景绝幽。","岚光檐外滴，花气座间浮。","野鹤依云宿，山泉带雨流。","禅心忘世虑，终日自悠悠。"]},{"t":"延春亭","f":"五言律诗","c":["绕檐皆竹木，春事此中多。","啼鸟将弦管，繁花簇绮罗。","蝶穿红锦幛，人在翠云窝。","若个长延得，何烦载酒过。"]},{"t":"宿山寺","f":"五言律诗","c":["胜游心未竟，日暮泊禅房。","月转回廊白，风清法界香。","问僧嫌偈短，听漏厌更长。","树杪天鸡舞，钟声起上方。"]},{"t":"春寒","f":"五言律诗","c":["浓云朝结暝，倏忽蔽层空。","点点廉纤雨，番番料峭风。","柳眉颦嫩绿，花脸黯轻红。","无限融和趣，都归冷淡中。"]},{"t":"早行","f":"五言律诗","c":["肃肃倦宵征，晨兴促驿程。","软风随去马，残月照行旌。","野店鸡三唱，谯楼漏五更。","车徒经数里，河汉尚纵横。"]},{"t":"白牡丹","f":"五言律诗","c":["洗却红妆面，天然粉态真。","花王冰作骨，姑射水为神。","缟袂迎风暖，琼杯捧露新。","东皇嫌冶丽，别幻一般春。"]},{"t":"春日久阴","f":"五言律诗","c":["二月春如海，长空未放晴。","林花羞褪色，山鸟噤无声。","薄雾寒笼树，浓云重压城。","寻芳空有约，风景太无情。"]},{"t":"月蚀","f":"五言律诗","c":["万里冰轮满，阴氛蓦地加。","青铜微有晕，白玉渐生瑕。","望汉群心竦，量天几秒遮。","凭谁操白刃，为我斩妖蟆。"]},{"t":"风","f":"五言律诗","c":["囊口徐徐起，号呼万窍通。","秋林添病绿，春苑堕惊红。","吹雨荒陂外，翻涛大海中。","杜陵茅屋破，飘转瀼西东。"]},{"t":"温泉","f":"五言律诗","c":["坎德乘阴火，灵源一气真。","玉壶冰瑩洁，岩窦雪嶙峋。","汩汩浑非潦，溶溶暖似春。","衣成单祫制，来学浴沂人。"]},{"t":"即事","f":"五言律诗","c":["轩扉闲白日，槐柳荫清渠。","阶下千竿竹，床头万卷书。","草香薰蛱蝶，水暖养芙蕖。","对景情无限，清吟兴有馀。"]},{"t":"中秋","f":"五言律诗","c":["今夕为何夕，平分一半秋。","月明梧影乱，风细桂香浮。","碧落茫无际，银河烂不收。","凭谁招庾亮，携酒共登楼。"]},{"t":"閒居即事","f":"五言律诗","c":["地僻尘纷静，重门昼不开。","虚庭团竹树，曲径换莓苔。","阶下无人过，窗前有鹤来。","自焚香炷坐，吟赏谩徘徊。"]},{"t":"海棠花","f":"五言律诗","c":["空谷有佳人，天然态度真。","杨妃春睡足，西子晓妆匀。","露浥胭脂湿，风飘绮縠新。","汉宫遗恨在，应复怨花神。"]},{"t":"牡丹","f":"五言律诗","c":["新曲传供奉，名花擅洛阳。","风神应国色，标格自天香。","百草皆为隶，孤丛特拟王。","沈香亭在否，今古笑三郎。"]},{"t":"秋日牡丹","f":"五言律诗","c":["万木皆萧索，何缘有此风。","飘香同桂子，敛色陋芙蓉。","露冷春容在，霜清晓睡浓。","悲秋嘲可解，莫妒宋词工。"]},{"t":"冬日牡丹","f":"五言律诗","c":["众芳摇落后，雪里见春红。","煖律回寒律，东风占北风。","林空香作阵，叶落锦成丛。","拟与梅花匹，都忘富贵中。"]},{"t":"杜鹃花","f":"五言律诗","c":["东风啼蜀魄，血泪染花深。","带雨眉犹蹙，迎风力未禁。","飘零今日怨，忘化昔年心。","万里无兵火，根应返鹤林。"]},{"t":"葵花","f":"五言律诗","c":["花开如木槿，照水更依墙。","淡白偎深紫，轻红间浅黄。","倾心臣职分，注意道家装。","肯被铅华涴，随风近紫阳。"]},{"t":"水仙花","f":"五言律诗","c":["仙娥游水府，肌骨是耶非。","解佩逢交甫，凌波讶宓妃。","清风常洒洒，香雪自霏霏。","不作人间梦，湘魂一片飞。"]},{"t":"夏晓","f":"五言律诗","c":["骄阳将出海，斜月淡无光。","槛竹摇风细，池荷浥露香。","辘轳鸣曙井，褦襶促晨装。","徙卧南荣下，居然枕簟凉。"]},{"t":"昼寝","f":"五言律诗","c":["一枕竹方床，蘧蘧午梦长。","黑甜聊自足，清苦为谁忙。","石晷移时刻，金炉冷篆香。","黄粱犹未熟，人事几兴亡。"]},{"t":"春雨","f":"五言律诗","c":["雨丝池水上，云片屋山东。","沥沥檐花落，盈盈地脉通。","摇村江柳绿，照槛苑桃红。","入夜蛙声急，田家报岁丰。"]},{"t":"拟元日立春","f":"五言律诗","c":["甲子开元旦，春深转斗魁。","初筵浮柏叶，急琯动葭灰。","宇宙真阳始，山川淑气回。","青丝兼綵胜，节物自相催。"]},{"t":"送春","f":"五言律诗","c":["青帝收春律，中宵法驾旋。","暖风芳草渡，细雨落花天。","深树迷蝴蝶，空山叫杜鹃。","一樽从此别，相见动经年。"]},{"t":"春宵","f":"五言律诗","c":["宫壶传漏刻，刻刻价非轻。","杨柳风初软，梨花月正明。","秋千微有影，檀板寂无声。","怪底长门内，通宵梦不成。"]},{"t":"村行书事","f":"五言律诗","c":["结屋临流水，柴门薜荔墙。","四山松叶碧，一径菜花黄。","草软牛羊卧，炊新麦豆香。","邻翁閒聚处，浊酒话农桑。"]},{"t":"听康都阃弹琴","f":"五言律诗","c":["金炉香篆袅，玉轸韵铿然。","玄酒真无味，清商不在弦。","带霜鸣候雁，和月泻寒泉。","一曲猗兰古，将军妙莫传。"]},{"t":"送邓二南还","f":"五言律诗","c":["西来情款款，南去计匆匆。","走马辞关右，看山过洛中。","江湖千里隔，池馆几时同。","亲旧风流少，长歌渭水东。"]},{"t":"始与晋卿先生茶话","f":"五言律诗","c":["千里神交久，新来始识荆。","关山多宦迹，湖海重诗名。","瑞世祥麟出，朝阳彩凤鸣。","外台知暂驻，双佩早朝京。"]},{"t":"南园对景偶书","f":"五言律诗","c":["南园风色暖，二月已回春。","宴笑皆文士，过从少俗人。","槛花红已遍，庭草绿初匀。","富贵非吾事，韶光过眼新。"]},{"t":"送郭上舍使云南回京","f":"五言律诗","c":["乃祖吾藩相，而孙上舍生。","一门贤子弟，三辅旧家声。","僰道羊肠险，秦关马足轻。","圣朝科目重，莫负读书名。"]},{"t":"汉中八景为朱景云宪副作 其一 汉台春望","f":"五言律诗","c":["炎汉兴王地，千年尚有台。","江山犹似昨，人事重堪哀。","鸟向离宫没，花从旧苑开。","不知东向日，谁塞汉中来。"]},{"t":"汉中八景为朱景云宪副作 其二 将坛晚眺","f":"五言律诗","c":["上将坛犹在，荒凉带夕晖。","兴刘功不赏，灭项事成非。","彻说真难夺，豨谋可独归。","自王疑莫解，况复与期违。"]},{"t":"汉中八景为朱景云宪副作 其三 韩沟晓月","f":"五言律诗","c":["萧相追韩处，遗踪尚可攀。","拿云龙易失，出柙虎重还。","曙色催飞骑，清光照壮颜。","向来非国士，何意出秦关。"]},{"t":"汉中八景为朱景云宪副作 其四 汉山夕照","f":"五言律诗","c":["薄暮山逾好，凭高眼界空。","岚光真可掬，倒影抑何穷。","万壑澄江紫，千林带叶红。","行人思往事，立马问褒中。"]},{"t":"汉中八景为朱景云宪副作 其五 中梁古刹","f":"五言律诗","c":["宝色风霜古，颓檐老瓦催。","碑文多剥落，山势独崔嵬。","宿鸟惊还定，游僧去复回。","人间经几劫，地下有馀灰。"]},{"t":"汉中八景为朱景云宪副作 其六 诸葛遗墟","f":"五言律诗","c":["大将星初殒，长城一夕空。","山川消王气，天地老英雄。","分鼎徒遗恨，挥戈未奏功。","犹疑龙尚卧，高冢夕阳中。"]},{"t":"汉中八景为朱景云宪副作 其七 龙江过雨","f":"五言律诗","c":["浩浩长江水，滔滔日夜流。","雨添千里润，凉送一天秋。","滩响山疑动，沙明岸欲浮。","袭人花气重，点点扑行舟。"]},{"t":"汉中八景为朱景云宪副作 其八 栈阁连云","f":"五言律诗","c":["秦蜀元相隔，何年鸟道开。","登天穷险阻，构木凿崔嵬。","苍狗依岩宿，青骢自陇来。","安危真可念，须仗济时才。"]},{"t":"人日喜晴","f":"五言律诗","c":["浃旬阴忽散，楼雪尽融城。","花缕迎新快，梅妆带艳明。","最灵今日兆，偏胜往年情。","更喜儿童唱，家家醉太平。"]},{"t":"探春","f":"五言律诗","c":["天上星杓转，东园景若何。","渐看生意满，顿觉赏心多。","浅碧山舒黛，新黄柳破鹅。","催花人火急，不惜马蹄过。"]},{"t":"西园池亭","f":"五言律诗","c":["池亭閒坐久，烦郁顿消除。","水气侵衣薄，山光入座虚。","浅沙眠白鹭，细藻跃金鱼。","最喜无尘杂，吟哦趣有馀。"]},{"t":"雨过","f":"五言律诗","c":["旭日初开霁，东风积雨过。","一溪新水涨，满地落花多。","山色明于画，莺声巧似歌。","休嗟春事去，亭沼渐清和。"]},{"t":"九日遇雨","f":"五言律诗","c":["登高何处是，风雨苦相仇。","人比黄花冷，山横翠黛愁。","隔宵淹去马，绕坞听鸣鸠。","醉把茱萸看，凭谁共倡酬。"]},{"t":"井","f":"五言律诗","c":["凿地牵泉脉，泠然百丈清。","细涵天色杳，倒浸月华明。","启钥通银槛，沈丝下玉罂。","诗人多肺渴，频听辘轳声。"]},{"t":"社日","f":"五言律诗","c":["社鼓年年响，村醪处处同。","物丰人自乐，赛尽蜡还通。","庭院来巢燕，江湖叫塞鸿。","炮羔兼䐑脍，随地得民风。"]},{"t":"尘","f":"五言律诗","c":["漠漠旋空起，花前柳外扬。","长途随马去，近市逐人忙。","雨浥天街净，春生辇路香。","元规何处避，唯有水云乡。"]},{"t":"次韵山阳道中","f":"五言律诗","c":["岁晚劳行部，千山及万山。","使旌纡雪里，候吏立沙间。","路滑心常骇，诗成兴不悭。","眼前梅与竹，聊慰客中颜。"]},{"t":"颁赐新历","f":"五言律诗","c":["皇明开泰运，太史独前知。","文轨同尧象，璇玑用夏时。","袭藏归祖庙，拜舞受阶墀。","何幸连潢派，年年睹盛仪。"]},{"t":"丙辰元旦试笔","f":"五言律诗","c":["岁德又逢辰，龙飞第九春。","青阳回凤历，玉烛转鸿钧。","禹服河山旧，尧天景物新。","太平今有象，共作太平人。"]},{"t":"送袁推府膺荐之京","f":"五言律诗","c":["行行上玉京，得意马蹄轻。","乌府徵书急，黄堂狱讼平。","子容人颂德，若水史垂名。","会入端公选，应教一道清。"]},{"t":"听雨不寐","f":"五言律诗","c":["风送檐花落，沈沈听转更。","银缸留湿焰，玉漏滴寒声。","谪戍魂先杳，怀人梦未成。","杜陵当此夜，醉咏动高情。"]},{"t":"春日过杜曲从臣指言唐杜拾遗故宅在此今不可寻矣","f":"五言律诗","c":["此日终南道，春风动物华。","云连千陇麦，霞烂一川花。","林杪穿驯鹤，池塘沸乱蛙。","茅茨接烟火，谁是拾遗家。"]},{"t":"郊行","f":"五言律诗","c":["晓行东郭外，月色尚平分。","老柏迷深寺，新花对古坟。","野烟随雾合，渔唱隔溪闻。","满眼皆吟趣，归来欲夕曛。"]},{"t":"即事","f":"古风","c":["朱帘当昼捲，偏是爱风光。","雨过?芜湿，风来杜若香。","拍酣晴蝶醉，课急午蜂狂。","一笑诗成处，陶然倒玉觞。"]},{"t":"咏黄莲花","f":"五言律诗","c":["水花分别种，红白敢争妍。","南国灵根老，中央正色鲜。","宫妃重入步，院吏误相传。","安得濂溪种，移来共岁年。"]},{"t":"过东轩墓","f":"五言律诗","c":["中却中山酒，长眠竟不醒。","脊令悲夜雨，鸿雁落晨星。","冢树连云暗，园芜带露青。","空馀丝竹在，地下杳难听。"]},{"t":"漫兴","f":"五言律诗","c":["终南谁是主，分守愧明时。","曹植非吾友，刘苍是我师。","有园惟种竹，无日不吟诗。","入夜重门合，天心月上迟。"]},{"t":"送张断事考绩严太守代求","f":"五言律诗","c":["早通三尺法，戎幕擅才猷。","名喜中丞荐，诗烦太守求。","清风生狴犴，高论动貔貅。","好去燕山道，重来觅旧游。"]},{"t":"愚","f":"五言律诗","c":["大块徒生我，蚩蚩无所知。","放鱼谁逆诈，失马未为痴。","䊵绮聊遮煖，膏粱不苦饥。","惟应有诗癖，句拙可能医。"]},{"t":"懒","f":"五言律诗","c":["习懒真成懒，年来懒更便。","杜门非寡合，隐几即閒眠。","倦洗窗前竹，慵听石上泉。","不知尘境外，可有懒中仙。"]},{"t":"拙","f":"五言律诗","c":["散人无所事，竟日避纷纭。","甘比催科政，思追乞巧文。","何须繁似露，焉用变于云。","莫笑鸠呼妇，閒中最喜闻。"]},{"t":"狂","f":"楚辞体","c":["口竭西江水，乾坤信所之。","草髡张旭发，醉炙郭舒眉。","抚掌高歌处，掀髯大笑时。","凤兮今不返，且和接舆词。"]},{"t":"贺致政王少府九十之寿其孙黄门求","f":"五言古诗","c":["贤关称俊乂，县佐著能为。","平易民心悦，公廉士论宜。","兰亭追往事，松径赋新诗。","倦鸟投林早，门云出岫迟。","江涛翻浩荡，舟楫脱艰危。","德贵阴施者，天其默相之。","瞿昙真有识，馀庆已先知。","迹隐青山旧，堂开绿野奇。","三槐承世泽，一桂发孙枝。","凤咮依金阙，鹓行接玉墀。","芳名归月旦，遐算逾期颐。","奉使还朝日，称觞献寿时。","希声歌白雪，妙舞间朱丝。","况际雍熙世，何欢可代兹。"]},{"t":"半村为姑苏汤隐士赋","f":"七言律诗","c":["别墅深深习隐居，半依城郭半郊墟。","门前流水渔郎棹，道上飞埃使者车。","隔岸市諠来座远，捲帘山色入窗虚。","云泥出处都随分，野有良田案有书。"]},{"t":"送都宪孙世荣四川巡抚","f":"七言律诗","c":["紫泥封敕下金銮，进擢都台镇锦官。","分陕未终秦地爱，济川应遂蜀人欢。","雪山又为公来重，云栈宁辞马度难。","从此诸番皆慕义，不劳兵甲从戎鞍。"]},{"t":"一览亭为保安王肃斋题","f":"七言律诗","c":["搆得幽亭瞰小池，四时风景总相宜。","百年图史劳双眼，万里乾坤醉一卮。","花雨扑帘红片片，玉山当户白差差。","傍人却讶仙凡隔，载酒无因为问奇。"]},{"t":"送李少参希范致政还乡","f":"七言律诗","c":["囊封情疏达天阍，乞得身閒荷宠恩。","召伯爱多棠勿剪，渊明归早菊犹存。","九峰结社诗千首，三泖维舟酒一樽。","除却赏心并乐事，只将家学授儿孙。"]},{"t":"送郁文博少参致政还上海","f":"七言律诗","c":["天恩乞得下明光，回首乡关旧路长。","风月有情归箧笥，烟霞无梦到岩廊。","数杯浊酒黄花径，十里青山绿野堂。","遥想鲈鱼秋正美，一竿终日钓沧浪。"]},{"t":"游仰天池留别性空和尚","f":"七言律诗","c":["绝巘灵湫一脉通，翠光垂彩浸虚空。","三千世界红尘外，十二楼台宝镜中。","琪树影长留晚照，昙花香煖递春风。","我来自有三生约，最喜高人得远公。"]},{"t":"寿伯汧阳王恕斋五十","f":"七言律诗","c":["半百年来五福全，秀钟光岳陆生莲。","苍松翠柏风霜古，玉叶金枝雨露偏。","鹤背有书来碧海，弧南增彩烛瑶天。","霞杯满进长春酒，愿祝庄椿寿八千。"]},{"t":"印湛然鍊师道院","f":"七言律诗","c":["五铢霞帔七星冠，洞府朝元礼数宽。","一榻白云香篆袅，半窗灵籁竹声寒。","瑶坛鹤占千年树，金鼎龙蟠九转丹。","物外红尘浑不到，碧桃花老任春残。"]},{"t":"病鹦鹉","f":"七言律诗","c":["灵禽不耐病摧残，衣褪秾蛾嘴褪丹。","无力似人方倦极，有情对主欲言难。","云深陇树归心远，月满秦楼旧梦寒。","敲损玉壶浑不应，空馀香稻长阑干。"]},{"t":"秋夜","f":"七言律诗","c":["烛黯绯罗火尚温，卧闻清漏咽重门。","露漙仙掖兰香细，月转雕栏桂影繁。","遣戍有怀劳士马，维藩无补愧君恩。","起来吟得悲秋句，却怪诗魔恼梦魂。"]},{"t":"刘节妇","f":"七言律诗","c":["结发曾期百岁同，可堪中岁命途穷。","孤鸾影去青铜冷，别鹤声沈绿绮空。","烈火难销心上铁，韶华不到鬓边蓬。","西风一榻清秋夜，露叶萧萧坠井桐。"]},{"t":"赋得潼关晓骑送盛舜臣还吴","f":"七言律诗","c":["重关高耸玉绳低，曙色微分柳外堤。","远道有人催去马，清时无客效鸣鸡。","帝城瑞日瞻来近，亲舍孤云望欲迷。","去去不须增感慨，好将形胜入新题。"]},{"t":"送戴松崖之浙江宪长","f":"七言律诗","c":["三年提学擅芳名，此日迁官沐宠荣。","关右文风归浑厚，越中民物待澄清。","霜寒驿路豺狼遁，日煖梧冈凤鸟鸣。","此去台端聊驻马，圣明虚席待阿衡。"]},{"t":"挽国戚廖都阃之父 其一","f":"七言律诗","c":["少住人间四十秋，乘云又作帝乡游。","紫宸有宠来丹诰，黄土无情瘗黑头。","共倚嫖姚终破敌，谁知李广不封侯。","白杨风起棠梨冷，地下英雄亦解愁。"]},{"t":"挽国戚廖都阃之父 其二","f":"七言律诗","c":["壮志曾期马伏波，功名未遂恨如何。","鸳雏继武勋劳重，鸾诰貤恩宠渥多。","海上有时来白鹤，人间无路返青骡。","刻铭幸有如椽笔，千古声名耿不磨。"]},{"t":"挽廖母秦太夫人 其一","f":"七言律诗","c":["万里良人事远征，义方教子早成名。","七旬禄养三牲备，双诰恩封二品荣。","夜雨萱花堂背落，春风芳草墓前生。","贤郎阃帅追思处，忍听慈乌夜夜鸣。"]},{"t":"挽廖母秦太夫人 其二","f":"七言律诗","c":["星沈宝婺夜光微，七十年来禄养违。","不意丛萱摧暮雨，空令寸草恋春晖。","瑶池有路旌幢远，沧海无潮信息稀。","留得阶前慈竹在，清风依旧满庭闱。"]},{"t":"挽国戚廖廷玺都阃 其一","f":"七言律诗","c":["剑气横空结暝阴，英雄触目亦伤心。","龙蛇阵古风雷壮，狐兔群多草木深。","云散柳营春寂寂，鹤归虎帐夜沈沈。","边城爪士知多少，目断旌旗泪满襟。"]},{"t":"挽国戚廖廷玺都阃 其二","f":"七言律诗","c":["战袍簇锦炫朝晖，万里边城纵武威。","沙苑不归蕃帐马，将星空堕塞垣扉。","草荒高冢埋金剑，云锁空山暗铁衣。","一段英雄招不返，野花香冷雨霏霏。"]},{"t":"挽廖母孙夫人 其一","f":"七言律诗","c":["瑶池梦断綵云飞，为吊芳魂泪一挥。","韬略资夫登阃帅，贤明有女拜宫妃。","麝兰已向风前散，环佩何时月下归。","喜有贤郎真将种，龙泉出匣更辉辉。"]},{"t":"挽廖母孙夫人 其二","f":"七言律诗","c":["珍重芳名举世贤，老苍何事涩长年。","情知龙剑终归水，忍使鸾胶别续弦。","珠翟已空堂上母，彩軿翻引洞中仙。","惟馀二品夫人诰，夜夜虹光射九天。"]},{"t":"除夕有怀戴松崖","f":"七言律诗","c":["坐销银烛夜窗虚，感慨流光逼岁除。","千里故人空有约，三湘归雁竟无书。","风惊爆竹鸦声乱，雪映寒梅鹤影臞。","满酌屠苏还自遣，关西何日候輶车。"]},{"t":"送梁廷美都宪巡抚湖广","f":"七言律诗","c":["九五飞龙泰运开，大藩方伯进都台。","随车雨自秦关去，有脚春从楚甸来。","和璧定为稀世宝，傅舟原是济川才。","圣明正尔思贤佐，双佩还应接上台。"]},{"t":"藩庭别意为贾希召都宪赋","f":"七言律诗","c":["祖席休辞酒满斟，匆匆离思转难禁。","乾坤纳纳谁非客，湖海悠悠独此心。","素履久同冰与蘖，归装赢得鹤随琴。","天涯明日遥相忆，目极暮云春树深。"]},{"t":"寄戴松崖","f":"七言律诗","c":["地北天南叹别离，此心无日不兴思。","云霏茗椀閒边话，月隐华灯醉里诗。","秦苑阳回花放早，越江霜冷雁来迟。","孤山闻说梅如玉，莫惜春前寄一枝。"]},{"t":"送齐应璧鸿胪脩祀礼成还朝","f":"七言律诗","c":["万年天子笃同宗，遣祀园陵礼秩崇。","使者虔恭将德意，先灵彷佛著仪容。","空山夜静风云绕，大地春回雨露浓。","归近天颜如有问，为言存没感恩同。"]},{"t":"哭宪皇帝","f":"七言律诗","c":["玉帛常思拜冕旒，此生谁道竟无由。","九重宫阙风云惨，万里山河草木愁。","昧谷日沈天漠漠，鼎湖龙去路悠悠。","宗臣一掬伤心泪，洒向黄河日夜流。"]},{"t":"送汤半村西游","f":"七言律诗","c":["千里来游百二州，又骑羸马向西游。","萧条自叹冯唐发，凋弊谁怜季子裘。","渭水断鸿投远渚，陇山落木动高秋。","老怀料得行吟惯，不似寻常动别愁。"]},{"t":"送人还闽","f":"七言律诗","c":["杨柳经霜叶乱飞，双旌迢递出关西。","紫萸黄菊牵归兴，绿酒红亭惜解携。","宦邸清风随驿马，客程残月促晨鸡。","故园到日应多暇，好把新诗取次题。"]},{"t":"送郑琴士南游","f":"七言律诗","c":["壮游知不惮驱驰，东望三衢信所之。","流水高山琴里趣，阳春白雪马前诗。","岂无远道莺花好，为有高堂鹤发垂。","慈竹满庭春酒熟，归期须及燕来时。"]},{"t":"冬日牡丹","f":"七言律诗","c":["爱日微暄破锦丛，永春园内小亭东。","虚疑玄帝为青帝，却讶寒风变煖风。","松竹有情同晚节，雪霜何处避春红。","眼前生意多如许，可是能回造化功。"]},{"t":"寄汤半村","f":"七言律诗","c":["长安相见即相知，千里那堪久别离。","夜雨寒灯劳远梦，暮云春树动长思。","花明杜曲莺啼早，天阔吴江雁度迟。","芳草一庭书馆静，煮茶何日细论诗。"]},{"t":"题印湛然鍊师画像","f":"七言律诗","c":["画史丹青妙入神，毫端应怪写来真。","松风萝月閒中趣，野鹤孤云物外身。","脉脉灵源清似水，溶溶生意蔼如春。","风雷叱咤寻常事，信是人间有道人。"]},{"t":"涵碧池","f":"七言律诗","c":["分得瑶池一镜开，翠光澄彻净无埃。","雕阑昼永眠春柳，文石秋深锈雨苔。","菡萏多情红间白，鸳鸯有意去还来。","无边风景供游乐，细数行吟日几回。"]},{"t":"涌金桥","f":"七言律诗","c":["长松修竹共阴森，下有方塘几许深。","玉井遥分泉脉脉，彩虹高卧夜沈沈。","升仙有志空题柱，过海无凭浪费心。","谁似主人襟抱阔，芳尊吟倚曲阑阴。"]},{"t":"春日雨中","f":"七言律诗","c":["冷风冷雨过残春，景物无多迹半陈。","色褪荼蘼红粉淡，愁低杨柳翠眉颦。","翰林赋罢江沈月，金谷楼高玉委尘。","自古兴亡皆有数，达人何用苦伤神。"]},{"t":"同阎文振方伯仰晋卿宪副池亭小酌","f":"七言律诗","c":["绿荷池上小亭台，红白莲花映日开。","喜共薇垣高士话，况逢冰署可人来。","谩将景物酬诗句，何用笙歌送酒杯。","坐久香风生白苧，不知身外有蓬莱。"]},{"t":"春暮书怀","f":"七言律诗","c":["鸟啼花落减韶光，节序相催有底忙。","堤柳絮多迷燕子，渚蒲芽短露鸳鸯。","匡时献策知无补，对酒吟诗喜欲狂。","况是眼前生意满，濡毫宁惮索枯肠。"]},{"t":"寄戴松崖都宪 其一","f":"七言律诗","c":["南北暌违思不穷，远将音问托鳞鸿。","百年天地能容我，此日经纶正倚公。","直遣穷阴回淑气，还闻浇俗变淳风。","西窗夜雨何时会，樽酒留连一笑同。"]},{"t":"寄戴松崖都宪 其二","f":"七言律诗","c":["契合金兰独见君，索居应叹久离群。","乘轺只在商山外，放棹难寻剡水濆。","霄汉功名推独步，江湖声迹喜相闻。","画楼几凭阑干立，目断天南日暮云。"]},{"t":"元夕分韵得红字二首 其一","f":"七言律诗","c":["华堂灯烛影摇红，此夕衣冠宴集同。","开口况逢时节好，赏心休放酒杯空。","千年奎壁星重聚，万里烟霄月正中。","情景可人须尽醉，咏归还向舞雩风。"]},{"t":"元夕分韵得红字二首 其二 送王尚文少参致政还金陵","f":"七言律诗","c":["霄汉功名志未伸，便从岩穴问通津。","江东国士无双士，林下閒人见一人。","门近清淮多白鸟，堂开绿野断红尘。","五千书卷床头在，旧业弓裘未是贫。"]},{"t":"送冯原孝郎中奉使还朝","f":"七言律诗","c":["建节宗藩册礼成，鸣驺千里上神京。","宾筵此日看仪度，虎榜当年识姓名。","五色长虹光不掩，千金良璧价非轻。","趋朝正是阳回日，上苑迁乔听早莺。"]},{"t":"灞桥别意送徐进士还京","f":"七言律诗","c":["驱驰王事独贤劳，使节煌煌又入朝。","红雨飞花长乐苑，绿波芳草灞陵桥。","秦关百二山河壮，京国三千道路遥。","宵旰只今图治切，早施经济答唐尧。"]},{"t":"送王述之升山西宪长","f":"七言律诗","c":["龙蟠金敕下长安，宪副承恩又转官。","鸷鸟乘秋霜翮健，法星垂彩夜光寒。","五陵父老遮骢马，三晋云山识豸冠。","料得轻车行熟路，片言折狱信非难。"]},{"t":"请人看梅","f":"七言律诗","c":["桃李争春不耐寒，老龙独向雪中蟠。","孤标只许青松侣，冷艳从教白眼看。","瀹茗赋诗聊酝藉，巡檐索笑足盘桓。","合欢不是无杯酒，似怪风情近牡丹。"]},{"t":"送耿好问亚卿癸西岳事毕还京","f":"七言律诗","c":["圣皇忧旱为斯民，谒告名山简近臣。","千里亢阳过十月，一时飞雪遍三秦。","大烹牲腯劳歆飨，少宰精诚动鬼神。","归去金銮烦奏对，于今民物已回春。"]},{"t":"贺新亝兄书屋落成","f":"七言律诗","c":["宗藩华搆俯层城，小结书斋又落成。","满架香芸青馥馥，一庭芳草翠盈盈。","可人兼喜留谈谑，熟客频来免送迎。","孔思周情千载趣，湛然方寸有馀清。"]},{"t":"送大参邓松坡致政还乡","f":"七言律诗","c":["两封情疏达金扉，乞得閒身故里归。","上国久依红日近，内江遥望白云飞。","鲈鱼鲙美充珍馔，孔雀袍新胜舞衣。","忠孝两全臣子分，傍人应羡早知几。"]},{"t":"次韵留郑子初长史怀归","f":"七言律诗","c":["閒情未许寄盟鸥，秦国衣冠第一流。","仙桂有香秋淡淡，贞松无恙晚悠悠。","封王顾我犹青岁，作相怜君未白头。","道谊始终期不负，絷驹非是为私留。"]},{"t":"挹秀为宗弟永寿王东轩赋","f":"七言律诗","c":["叠石为山列画屏，方塘如鉴对幽亭。","水涵云影连天碧，峰送岚光入座青。","爽气逼人诗屡就，清风扑面酒微醒。","等閒自有濂溪趣，芳草长留翠满庭。"]},{"t":"读宁河武顺王邓氏世家录 其一","f":"七言律诗","c":["手提一剑归真主，百二雄师势独尊。","彤管铭功辉简册，青门为庶泣儿孙。","东皇已去花无赖，华表重来鹤有言。","六尺孤坟钟阜外，谁将麦饭吊英魂。"]},{"t":"读宁河武顺王邓氏世家录 其二","f":"七言律诗","c":["气节棱棱压万夫，平生百战定寰区。","丹书铁劵当朝宠，武略文韬百世模。","淮泗腴田惟旧业，麒麟高阁有新图。","天家雨露东溟阔，况是河山旧剖符。"]},{"t":"九日与戴松崖汤俟庵赏菊","f":"七言律诗","c":["门外衣冠次第来，斯文良会喜相陪。","天垂晴碧雨初过，菊带寒香花正开。","人世不须伤往事，篱根聊共醉深杯。","东风指日回春意，还约书窗看早梅。"]},{"t":"送郑子初长史致政归南闽","f":"七言律诗","c":["作相亲藩擅德音，莼鲈忽动故乡心。","匡衡去国多遗草，疏广还家有赐金。","绿野雨晴花雾煖，沧江月白水云深。","悬知报主心犹在，清梦还应绕禁林。"]},{"t":"送左廷珍宪使升都宪辽东巡抚","f":"七言律诗","c":["十载西台著豸冠，又迁都宪上朝端。","九重图治求贤急，三辅怀恩拜别难。","宝鉴光摇关月冷，高牙风动海云寒。","封侯自古多文士，斗印期登大将坛。"]},{"t":"宴保安府池亭席上偶成","f":"七言律诗","c":["路入名园景最幽，小亭如画枕寒流。","风生朱箔花香细，日转雕栏树影浮。","篆袅香烟霏宝鼎，酒倾玄露泻金瓯。","眼前便是仙家境，跨鹤宁须阆苑游。"]},{"t":"惜红梅","f":"七言律诗","c":["暂离紫府入秦城，水路迢迢数月程。","北客共知元有种，东君谁料太无情。","群芳各藉阳和力，一树何孤雨泽荣。","醉里师雄呼不醒，翠禽空绕月三更。"]},{"t":"次戴松崖韵以寓有怀","f":"七言律诗","c":["会合寻常叹不齐，可堪南北复东西。","门墙化雨归桃李，霄汉文星聚壁奎。","思逐杨花同滚滚，望迷芳草更萋萋。","不知骢马今何处，伐木空山鸟自啼。"]},{"t":"无题 其一","f":"七言律诗","c":["阑干曲曲思依依，风露凉生白苧衣。","瑶瑟调残金雁冷，玉箫声断綵鸾飞。","梦中说梦犹难信，山上安山更不归。","回首蓬莱三万里，煖云明灭望中微。"]},{"t":"无题 其二","f":"七言律诗","c":["聚散无凭若梦中，落花飞絮任西东。","金笼鹦鹉■松语，绿水芙蓉黯淡红。","晓镜芳华空自惜，夜灯谈笑与谁同。","十年零落同心结，不是侬家手未工。"]},{"t":"无题 其三","f":"七言律诗","c":["兔走乌飞有底忙，相思应断九回肠。","新声谩说朱弦好，旧恨谁怜白画长。","玉虎水寒犹汲井，金猊火冷尚添香。","星桥影淡秋无迹，碧海青天路渺茫。"]},{"t":"无题 其四","f":"七言律诗","c":["楚雨巫云恰好时，角声又起画楼西。","金屏绣褥空凝望，锦字鱼笺亦懒题。","藕断尚怜丝袅娜，花深偏怪雾凄迷。","宵征莫道无眠处，赋命从来自不齐。"]},{"t":"闺情 其一","f":"七言律诗","c":["倚遍阑干白昼长，更无情绪理新妆。","柳眉翠压春愁重，桃脸红添粉泪香。","潮信有期通瀚海，音书无路到辽阳。","自怜不及堂前燕，双去双来绕画梁。"]},{"t":"闺情 其二","f":"七言律诗","c":["午梦初回玉漏长，粉容香汗湿残妆。","箧中羞对班姬扇，帘底空闻贾媛香。","暮雨几时归楚岫，春心何处问巫阳。","閒来写就相思调，一段新声自绕梁。"]},{"t":"闺情 其三","f":"七言律诗","c":["愁中一刻似年长，无复浓妆与淡妆。","玉颊瘦来惭对镜，罗衣閒却罢熏香。","丹枫有恨随流水，白日无情易夕阳。","屈指光阴近重九，懒将黄菊傍钗梁。"]},{"t":"闺情 其四","f":"七言律诗","c":["锦被难温觉夜长，晓来无复学梅妆。","亸肩云鬓千丝乱，记臂丹砂一点香。","问约有情缄豆蔻，引年无意藉昌阳。","角声催起东楼月，颜色犹疑在屋梁。"]},{"t":"送春","f":"七言律诗","c":["榆荚杨花乱舞风，东皇何事去匆匆。","一庭芳草添浓绿，满耳啼莺怨落红。","眼底韶华浑似梦，人间乐事又成空。","临岐对酒情无赖，殢雨尤云怅望中。"]},{"t":"心迹双清为汧阳王作","f":"七言律诗","c":["一片灵台湛碧虚，此身真在水云居。","壶中秋月冰相映，帘外春风草不除。","老鹤枯琴君子操，牙签玉轴圣贤书。","东平未必清如许，俯仰无惭乐有馀。"]},{"t":"送娄廉使克让朝京","f":"七言律诗","c":["玉骢腾踏使车轻，宪节趋朝出雍城。","旌旆影摇晴雪冷，佩环声振晓风清。","云中双阙星辰近，天上重瞳日月明。","关辅年来尚彫敝，好因前席论苍生。"]},{"t":"东轩为永寿王作","f":"七言律诗","c":["搆得华轩府第东，搏桑朝影上梧桐。","雨香砌草先交翠，气淑林花早放红。","照眼帘栊迎旭日，满堂宾客坐春风。","主人吟罢连枝句，流水心期万折同。"]},{"t":"白云窝","f":"七言律诗","c":["为霖有待济恒旸，暂托幽栖覆苑墙。","缥缈远连天漠漠，氤氲微露月茫茫。","晴窗影堕琴书润，午榻阴生枕簟凉。","苍狗白衣随变幻，肯教飞梦落高唐。"]},{"t":"送吴元素长史致仕","f":"七言律诗","c":["缄情才上九重天，乞得閒身宠渥偏。","四品进阶金带重，五花裁锦茜袍鲜。","秦城况有连云第，杜曲仍多负郭田。","我喜相违复相近，沃心还望仲舒贤。"]},{"t":"元日遇雪","f":"七言律诗","c":["青帝今朝换物华，故将飞雪逞豪奢。","嘉祥偏应三阳候，枯树争开六出花。","耳底丰年先有咏，眼前生意浩无涯。","妆成富贵应难并，玉宇琼楼几万家。"]},{"t":"贺戴松崖升都宪","f":"七言律诗","c":["薇垣迁秩贰都台，荆楚风烟到处开。","恩命一函从北下，福星千里又南来。","凤麟自古生明世，廊庙于今用大材。","昨夜仰瞻霄汉上，文光垂彩耀三台。"]},{"t":"送韩贯道都宪巡抚西夏","f":"七言律诗","c":["盛世筹边用老成，魏公孙子复才名。","紫泥金敕来关辅，大纛高牙建夏城。","杀气凛如秋气肃，法星光并将星明。","塞垣自此烽烟净，廊庙行看佐太平。"]},{"t":"送周国瑞总戎守镇西夏","f":"七言律诗","c":["金敕初颁五凤楼，便催铁钺镇边州。","北来已破羌人胆，西顾宁烦圣主忧。","千里旌旗山月晓，一声鼓角塞云秋。","酬功他日铭彝鼎，定列麒麟阁上头。"]},{"t":"柬暹上人","f":"七言律诗","c":["千里劳师远入秦，久闻医术妙通神。","坐中不问三生话，指下求痊一病身。","早使惠风苏草木，要令幽谷变阳春。","慈悲最是僧家事，况是僧家最上人。"]},{"t":"中秋喜晴","f":"七言律诗","c":["三年好景忧中度，今岁中秋大放晴。","万里碧空星彩烂，满天凉露月华明。","桂香尊俎喷龙脑，花拥笙歌咽凤声。","清赏不知更漏永，只疑身世在蓬瀛。"]},{"t":"秋夜雨晴","f":"七言律诗","c":["雨馀林暑尽消残，凉气侵肤却素纨。","万里碧空秋淡淡，一天清露夜漫漫。","桂香暗结黄金粟，桥影斜涵白玉盘。","清思满襟浑不寐，诗成还倚曲阑干。"]},{"t":"雨晴即事","f":"七言律诗","c":["好山排闼送新晴，石径苔乾步屧轻。","华屋日高飞乳燕，绿杨风软听流莺。","也知守拙真成拙，须信浮名未是名。","一笑未堪尘鞅累，陶然醉咏乐升平。"]},{"t":"白兔","f":"七言律诗","c":["金精孕秀产明时，三窟祥生玉雪姿。","异种料应尘世少，仙胎元是月宫遗。","冰崖卧处人难见，草径行来犬易知。","好共蓬山雪毛鹿，去随阿母宴瑶池。"]},{"t":"映水芙蓉","f":"七言律诗","c":["花满平堤水满池，水光花影净相宜。","蜀江霞衬千机锦，海国蚕成五色丝。","镜里崔徽施巧手，溪边西子露香肌。","本来色相皆虚幻，恼乱鱼龙恐浪疑。"]},{"t":"舞风杨柳","f":"七言律诗","c":["灞陵桥畔晚依依，摇荡春光力尚微。","汉燕身轻斜亸袖，白蛮腰瘦不胜衣。","长条偏藉吹嘘力，弱质难禁剪拂威。","寄语章台休摆乱，风流态度有时归。"]},{"t":"春日写景","f":"七言律诗","c":["楼阁深沈画景长，淡云轻霭散晴光。","柳堤风煖莺莺巧，花径泥融燕燕忙。","歌管传声来别院，鞦韆送影过邻墙。","青春莫负韶华好，秉烛还须照海棠。"]},{"t":"访城南孝子庐墓","f":"七言律诗","c":["命驾来寻孝子居，落花天气日长初。","乔松几个一双鹤，老屋数间千卷书。","高冢己沾新雨露，故家还守旧田庐。","纷纷肉食知多少，侧耳高风愧不如。"]},{"t":"送脩武伯还朝","f":"七言律诗","c":["亲藩封拜礼初成，鸣佩依然上玉京。","千里河山旋使节，一方茅土受宗盟。","春回灞岸莺声早，雪霁函关马足轻。","青岁功名须努力，等閒莫负旧家声。"]},{"t":"送秋官车郎中还京","f":"七言律诗","c":["九重恩礼厚同宗，天上仙郎远锡封。","袖带玉炉香馥郁，口传金殿语从容。","秦关自昔山河壮，汉省于今雨露浓。","看取归朝还使节，定知飞步接夔龙。"]},{"t":"登城","f":"七言律诗","c":["层城百尺势凌虚，四面青山列画图。","北极九重红日近，南山双垄白云孤。","天连迥野迷高下，烟抹平林淡有无。","长啸一声回首处，夕阳归雁落汀芦。"]},{"t":"画眉次韵","f":"七言律诗","c":["宫样妆成忽自惊，剩添螺绿转分明。","平铺秋水双蛾秀，淡抹春山八字横。","颦学西施偏有态，妩怜京兆最多情。","等閒莫对弯弯月，只恐嫦娥也妒争。"]},{"t":"夜坐不寐听雨","f":"七言律诗","c":["积雨兼旬未放晴，瓦沟银竹势如倾。","楼头画鼓三更尽，窗下残灯一点明。","诗客此时偏得句，旅人今夕不胜情。","悬知足慰三农望，稼穑今秋定有成。"]},{"t":"过宫人墓","f":"七言律诗","c":["綵鸾飞去几回秋，枳棘丛深见墓丘。","艳骨香魂千古恨，断云残雨一天愁。","故宫寂寂春何在，落日涓涓水自流。","啼鸟声中增感慨，肩舆经过更迟留。"]},{"t":"四友轩","f":"七言律诗","c":["松竹梅花旧有名，幽人又结岁寒盟。","翻云覆雨嫌时态，傲雪凌霜有故情。","人物每同三益好，丰标况是一般清。","相看冷淡空山里，尔汝忘形度此生。"]},{"t":"春园行乐","f":"七言律诗","c":["漠漠轻烟淡淡风，曲阑干外小池东。","莺穿高柳分晴翠，燕掠飞花落软红。","好景只疑图画里，新诗都付笑谈中。","及时游衍心偏乐，鹦鹉深杯莫放空。"]},{"t":"与弟东轩","f":"七言律诗","c":["一遍赓诗百遍吟，吟成犹未惬人心。","韵逢险峻尤难押，句到新奇不易寻。","银烛烧残思处苦，长髭撚断坐来深。","阳春白雪真稀少，金石难同瓦缶音。"]},{"t":"望云思亲为陈公辅伴读赋","f":"七言律诗","c":["甘旨无由奉母慈，晨昏常起狄公思。","孤云目断三千里，寸草心悬十二时。","飞去不能身有翼，愁来空自泪交颐。","谁知我亦伤情切，忍诵当年陟屺诗。"]},{"t":"题陈叔振宪使雁山永慕卷","f":"七言律诗","c":["家山埋玉几星霜，游子天涯倍感伤。","宰木有乌风淅淅，泉台无路夜茫茫。","当年独立心常在，此日三迁教未忘。","貌得佳城随宦辙，公馀展拜泪淋浪。"]},{"t":"丘仲玉少参晚香亭","f":"七言律诗","c":["小结幽亭用意深，西风开遍满篱金。","餐英自得灵均味，把酒谁探靖节心。","冷艳不嫌秋色淡，残枝偏耐晓霜侵。","主人剩有新裁句，日对南山取次吟。"]},{"t":"借山楼为汤俟庵作","f":"七言律诗","c":["十二阑干百尺楼，千年风景一时收。","不妨老子常开眼，曾辱高峰为点头。","爽气隔帘时冉冉，岚光浮座晚悠悠。","姑苏景物分明是，底用思乡感旧游。"]},{"t":"净香亭","f":"七言律诗","c":["小结幽亭傍此君，百年风雨任朝昏。","湿云侵晚笼茶灶，高节凌寒落酒樽。","窗外有时摇翡翠，风前终日散兰荪。","主人对此歌淇澳，剩有清声远近闻。"]},{"t":"道中遇雪","f":"七言律诗","c":["前驱堕指折弓弦，四顾茫茫失渭川。","初讶飞花连碧落，还疑美玉出蓝田。","随车缟带真无异，捲幔冰崖绝可怜。","谁道眼前非上瑞，等閒三白是丰年。"]},{"t":"咏雪和苏长公韵 其一","f":"七言律诗","c":["已密还疏乱更纤，袭人寒气十分严。","可能端木皆成粟，未必杨花却似盐。","冷咽铜龙沈晓漏，声酣铁马战风檐。","晓来忽报红轮上，仙掌依稀露指尖。"]},{"t":"咏雪和苏长公韵 其二","f":"七言律诗","c":["长乐钟声散曙鸦，九衢风力疾于车。","折残渭水竿竿竹，拟遍梁园树树花。","沃野春回千陇麦，层檐冰缀万人家。","句清无奈茶烟湿，撚断吟髭手谩叉。"]},{"t":"雪晴 其一","f":"七言律诗","c":["阴沴初消瑞日升，田夫于耜拟东兴。","山头破煖青犹在，柳眼窥春绿未曾。","双艇远依收钓火，一帘深映读书灯。","人间妙手嗟谁及，调燮终归宰辅能。"]},{"t":"雪晴 其二","f":"七言律诗","c":["楼雪初融岁欲更，喜闻乾鹊报天晴。","炊烟早逐朝阳起，春意潜随野水生。","云散佛头来岳色，风回仙掌落钟声。","不知骢马经行处，赋得梅花几首成。"]},{"t":"雪晴 其三","f":"七言律诗","c":["玄冥司令势何严，一雪能教数日淹。","风敛冻云归远岫，天开晴日上虚檐。","梅腮破腊争匀粉，笋指缘寒未露尖。","好在田家应拍手，瓦盆盛酒正厌厌。"]},{"t":"雪晴复作 其一","f":"七言律诗","c":["谁剪琼花促未停，海云笼日上苍冥。","地宜麰麦三回白，山露芙蓉几仞青。","寒溜不妨和漏滴，春蚕犹爱隔窗听。","江湖此夜看牢落，应有高人睡未醒。"]},{"t":"雪晴复作 其二","f":"七言律诗","c":["四匝阴云动浃旬，河山积玉几番新。","吟馀瘦骨应怜我，寒到贫家亦恼人。","浮世悟来皆泡幻，化机流后即阳春。","座中鹤氅清如许，缓步能消物外尘。"]},{"t":"雪晴复作 其三","f":"七言律诗","c":["片片随风欲作围，晓来帘外正霏霏。","鸦巢深树饥争噪，鹊聚空梁冻不飞。","双棹山阴狂客返，一蓑江上钓翁归。","玉楼银海真仙咏，已觉当年属和稀。"]},{"t":"雪晴复作 其四","f":"七言律诗","c":["长空雪意未蹉跎，舞屑回风一瞬过。","药玉杯船迎腊早，水晶帘幕受寒多。","清浮石鼎应谁得，白战星堂奈若何。","回首江天云雾里，短罾疏网伴渔蓑。"]},{"t":"雪晴复作 其五","f":"七言律诗","c":["酸风吹雨结阴云，村舍人家半掩门。","剪水作花看有象，堆盐肖虎刻无痕。","彩毫冻合诗仍健，绿酒春回脸易温。","清兴满怀浑不俗，山阴灞水总休论。"]},{"t":"看雪","f":"七言律诗","c":["雨花云叶逞新奇，剪水何人夺化机。","掌上芙蓉旋玉女，空中缟素簇琼妃。","郊原瘦蹇冲寒去，野渡轻蓑薄暮归。","最是柱头惊旧鹤，烂银城郭此时非。"]},{"t":"听雪","f":"七言律诗","c":["玉屑兼风捲地惊，坐疑天籁不胜清。","吴蚕食叶渐无迹，江蟹行沙碎有声。","诗梦又从深夜转，春愁还向隔年生。","閒门要路无遗处，谁谓滕神亦世情。"]},{"t":"和杨宪副应宁过蓝桥","f":"七言律诗","c":["摇摇小队出蓝关，一路凌兢马足悭。","万里同云迷玉宇，满天霏雪幻银山。","枝翻宿鸟惊难定，苔长新痕湿未斑。","却忆昌黎经此日，凭谁沽酒慰愁颜。"]},{"t":"又和蓝田道中","f":"七言律诗","c":["风雪交加岁晚时，一年节候又将移。","官庖有廪堪沽酒，野店无梅欲废诗。","白凤随车归院疾，银杯逐马度桥迟。","关西重见杨夫子，犹恐前身是伯夷。"]},{"t":"送焦知县升彰德知府","f":"七言律诗","c":["曾于乌府播芳声，又向花封报政成。","皂盖朱轓今日宠，玉壶秋月旧时清。","爱民须体朝廷意，卧辙偏伤父老情。","见说调羹还有待，一麾宁许久专城。"]},{"t":"挽余士英司马父母","f":"七言律诗","c":["紫箫声彻凤鸾飞，雏凤呈祥世所稀。","二品褒封蒙异数，百年伉俪竟同归。","理财久擅韦公誉，断织犹存孟母机。","七尺穹碑昭不泯，西川山水亦增辉。"]},{"t":"夜坐闻笛","f":"七言律诗","c":["谁人吹笛倚楼东，静夜闻来迥不同。","嘹喨数声云散后，凄清三弄月明中。","梅花落尽江城雪，杨柳凋残野渡风。","坐久不知黄鹤隔，参差树影上帘栊。"]},{"t":"别意送凌卧岩还乡次韵 其一","f":"七言律诗","c":["术传卢扁字钟王，两浙高名海内香。","去路也知车载稳，济时何用剑生芒。","鸡鸣函谷三更月，枫落吴江两岸霜。","归到苕溪寻旧侣，画船诗酒水云乡。"]},{"t":"别意送凌卧岩还乡次韵 其二","f":"七言律诗","c":["束书孤剑别西秦，红树青山泼眼新。","千里风霜欺老鬓，五湖风月寄閒身。","灞桥驴背惊残梦，函谷鸡声促去轮。","料得纪行多赋咏，邮筒毋惜寄阳春。"]},{"t":"别意送凌卧岩还乡次韵 其三","f":"七言律诗","c":["先生为客感秋声，岂惮还乡两月程。","囊里有丹皆玉液，釜中无饭不青精。","月残茅店鸡三唱，霜冷河桥马独行。","去去天空风正急，渡江须待暮潮平。"]},{"t":"寄日华上人","f":"七言律诗","c":["秦城分手一年过，眼底流光逐逝波。","冷澹情怀交去久，平安消息寄来多。","宝炉香烬同谁话，白雪诗成想自哦。","遍倚阑干思无限，西风又老半塘荷。"]},{"t":"天开图画楼为唐府三城王作","f":"七言律诗","c":["十二丹梯百尺楼，无边佳致满中州。","山光凝黛当窗见，水色拖蓝绕楹流。","不用丹青誇独步，真成造物与同游。","高吟定有诗千首，安得登临一唱酬。"]},{"t":"御书阁为唐府三城王作","f":"七言律诗","c":["天上颁书宠数优，凌空杰阁冠中州。","六经垂世崇宣父，万轴传家羡邺侯。","粉蠹避芸香馥馥，晴虹贯日影悠悠。","贻孙燕子留芳远，瓜瓞绵绵与国休。"]},{"t":"送胡廷伦纪善致仕还乡","f":"七言律诗","c":["廿载秦藩共我游，萧萧华发已盈头。","季鹰去国莼初美，靖节还家菊正秋。","万里云霄双捲翼，五湖烟水一归舟。","会稽剩有佳山水，吟得新诗肯寄不。"]},{"t":"自题小像","f":"七言律诗","c":["石田挥笔写吾真，身外谁知更有身。","报国寸心元自赤，流年双鬓欲成银。","爱山常与山为主，种竹谁知竹是宾。","茶灶笔床随处有，优游天地一閒人。"]},{"t":"再游天池普光寺忆僧性空","f":"七言律诗","c":["不到禅关二十年，无边风景尚依然。","青苍远接千章树，红白新开万朵莲。","习隐不为招隐赋，爱山宁惜买山钱。","独怜惠远今何在，孤冢斜阳带晚烟。"]},{"t":"慰新斋兄","f":"七言律诗","c":["握手常嗟会面疏，年来尤觉甚于初。","身同野鹤清尤健，计比巢鸠拙不如。","莫为事烦妨食息，且教心静乐琴书。","谁言淡泊中无味，淡泊从来味有馀。"]},{"t":"次三镇国慎独斋竹轩之作 其一","f":"七言律诗","c":["筑得幽居类瀼西，苔痕蜗篆雨中迷。","出林老干芟犹密，解箨新梢长欲齐。","高咏不妨人径造，虚心似待我留题。","夜阑分付闲啼鸟，莫谩喧啾搅凤栖。"]},{"t":"次三镇国慎独斋竹轩之作 其二","f":"七言律诗","c":["隙地新开水竹居，游观终日从篮舆。","清阴满地和烟暝，凉影横窗过月虚。","一点红尘浑不到，万竿苍玉自森如。","等閒相对真成趣，不用笙歌乐有馀。"]},{"t":"次三镇国慎独斋陪游后园池亭之作 其一","f":"古风","c":["案牍无劳日日閒，每?临水更看山。","绿云冉冉侵帘细，红雨纷纷点砌斑。","三月韶光图画里，百年身世去来间。","东平自有天然乐，逸驾千年许共攀。"]},{"t":"次三镇国慎独斋陪游后园池亭之作 其二","f":"七言律诗","c":["年来年去几番新，万事回头扇底尘。","雪里老梅才破玉，雨中芳草又成茵。","满钩帘捲青山晓，半亩塘开绿水春。","美景故知常在眼，人间俗事浪频频。"]},{"t":"送任进之学正之绛州","f":"七言律诗","c":["匹马嘶风踏软尘，大河东去是通津。","金天后夜文星远，绛水开年化雨新。","芹泮绿回官舍晓，杏坛红送讲堂春。","人材瑞世从先达，皋席于今有凤麟。"]},{"t":"约戴松崖赏梅因出巡不果","f":"七言律诗","c":["宫庭万玉拥新梅，曾约逋仙共酒杯。","千里独怜青眼别，一襟谁为故人开。","漫劳疏影横窗入，徒有寒香扑面来。","欲折一枝烦远使，岂胜搔首望兰台。"]},{"t":"庄诵太祖皇帝御制文集","f":"七言律诗","c":["鼎湖龙去天应泣，弦管无声市肆空。","宸翰万年留圣制，人文千古缵神功。","尧民击壤风谣在，周胤分茅典则同。","秦陇诸孙瞻拜处，不禁血泪洒遗弓。"]},{"t":"览秀楼为宗兄临潼王养性斋题","f":"七言律诗","c":["杰构凭虚接上台，阑干曲曲障风埃。","窗涵渭水玻瓈滑，帘捲终南紫翠开。","歌舞不知谁共醉，登临应许我重来。","无边光景无穷趣，莫惜新诗为品裁。"]},{"t":"送鲁千之都宪之甘州巡抚","f":"七言律诗","c":["几年藩省著芳声，进秩都台荷宠荣。","霖雨又从今日作，泰阶应向此时平。","霜明番落旄头暗，春到阴山淑气生。","为语羌戎须远遁，于今万里有长城。"]},{"t":"次韵寄致政郁文溥少参","f":"七言律诗","c":["关陕相逢即故知，别来谁料会无期。","金兰漫忆同心话，白雪多惭下里诗。","夜雨一灯劳远梦，暮云千里动长思。","林泉闻说多萧散，两鬓年来尚未丝。"]},{"t":"牡丹亭侍亲夜宴","f":"七言律诗","c":["银烛辉煌照绮罗，绿云飞尽露银河。","天香国色春无际，玉漏铜龙夜几何。","翠袖舞风娇不起，凤笙吹月淡相和。","霞杯满进长生酒，春到庭闱喜气多。"]},{"t":"予祖康王尝游翠微山留题永庆寺璧迄今四十载寺僧录诗来谒求和予三复展诵感慕不觉泣下因再拜追和时成化庚子九月一日也","f":"七言律诗","c":["当年仙驾到禅宫，回首春花几度红。","剩有诗篇笼壁上，漫劳神物护山中。","腾蛟起凤奎光在，流水浮云世事空。","一捧骊珠双泪落，九原衰草正秋风。"]},{"t":"赠汤以脩纪善进阶致政","f":"七言律诗","c":["董贾才华擅俊良，曳裾元侍我先王。","笼鹅书妙黄金薤，倚马吟成白雪章。","松柏经霜知不改，筌蹄得意信难忘。","一封竟遂柴桑愿，又进官阶拜宠光。"]},{"t":"送余士英司马之京","f":"七言律诗","c":["天书飞下五云端，八座崇高礼数宽。","霖雨早收天下望，法星曾照塞门寒。","当年维岳生申甫，终古边城倚范韩。","将相勋名真不愧，折冲补衮信非难。"]},{"t":"咏雪次韵","f":"七言律诗","c":["纷纷瑞叶下遥天，宫阙高寒搅夜眠。","指露却愁东郭履，兴阑还笑剡溪船。","党姬风味羊羔酒，谢女才情柳絮联。","最喜太平先有兆，一冬三白遍秦川。"]},{"t":"送贾希召都宪致政还蜀","f":"七言律诗","c":["承流总宪两称宜，忧国忧民鬓已丝。","裴相抗章求退日，边人归化受降时。","巴江雪霁鸥波阔，蜀栈云连鸟道危。","可是还家便高卧，九重无乃动遐思。"]},{"t":"寿伯汧阳王","f":"七言律诗","c":["花甲将周鬓未丝，五朝身际太平时。","明珠白璧原无玷，后土皇天若有私。","云煖瑞芝森玉叶，雨香仙桂濯金枝。","年年此日春如海，笑对南山醉酒卮。"]},{"t":"闻余士英都宪凯旋喜而有作","f":"七言律诗","c":["貔貅十万度洮河，顷刻前徒自倒戈。","小丑命从今日尽，名臣功比昔人多。","一天膏雨消氛气，满路春风奏凯歌。","闻有巨崖堪勒颂，万人相向为君磨。"]},{"t":"夜坐纳凉","f":"七言律诗","c":["桃笙豹枕竹方床，爽气微添白苧裳。","宫漏穿花声断续，疏萤度水影煇煌。","玉绳低转繁星乱，银浦斜连淡月凉。","清兴满怀诗吻渴，笑拈斗柄挹天浆。"]},{"t":"拟送人赴举","f":"七言律诗","c":["十年经传费覃思，养就长材未是迟。","月殿秋高攀桂夕，禹门春暖化龙时。","士林声价千金璧，艺苑文章五色丝。","此去奏名真不忝，便应飞步接皋夔。"]},{"t":"送李经司升知陇州","f":"七言律诗","c":["赞政薇垣属老成，分符又喜领专城。","九衢父老壶浆饯，一路儿童竹马迎。","行李只随清献鹤，生涯谁卖陇山鹦。","东风三月长安道，侧耳行人沸颂声。"]},{"t":"拟圣寿节早朝","f":"七言律诗","c":["南极腾光烛紫霄，康衢又听颂唐尧。","九重宫阙开黄道，五色云霞拥赭袍。","霭霭御香浮黼扆，葱葱佳气拂旌旄。","万方感德多欢抃，共祝南山寿域高。"]},{"t":"春雪次韵","f":"七言律诗","c":["乱洒寒檐已足誇，飞来灯夕更光华。","天孙不记三阳候，青帝初裁五出花。","消剩江波浮钓艇，润馀田麦慰农家。","呼童莫待金乌上，扫向梅窗夜煮茶。"]},{"t":"对雪谩成","f":"七言律诗","c":["寒湛虚明耿夜光，朝来片片过宫墙。","轻如柳絮还应湿，白似梨花秪欠香。","风韵每怜飘处好，词情偏觉赋诗狂。","玉堂此际清如许，不数豪家乐醉乡。"]},{"t":"送娄克让之四川方伯","f":"七言律诗","c":["紫泥封敕下天阍，宪使迁官向蜀藩。","瑞世百年麟在囿，清风千里鹤随轩。","朝廷方岳西川重，霄汉星辰左辖尊。","从此雪山南下路，甘棠春煖绿阴繁。"]},{"t":"乙已仲春七日听颁宽恤诏","f":"七言律诗","c":["彩凤衔书出九重，圣恩如海遍寰中。","江山清昼风烟散，天地回春草木同。","二月迅雷惊蛰腐，一时膏雨起疲癊。","臣民欢忭将何补，万岁千秋祝华嵩。"]},{"t":"挽仪宾曹仲璜","f":"七言律诗","c":["宾馆相亲岁月多，年来霜鬓渐成皤。","千金伟器元无忝，半世荣名耿不磨。","北海樽空虚夜月，南柯梦断冷行窝。","石麟高冢青山下，肠断秋风叹逝波。"]},{"t":"周处三害图","f":"七言律诗","c":["膂力兼人胆气粗，势同蛟虎虐无辜。","若非父老一言悟，安得乡闾三害无。","死国能坚忠义节，读书还作圣贤徒。","男儿改过非难事，千古英风激懦夫。"]},{"t":"寿钱员外八十大参大用之父","f":"七言律诗","c":["八帙封君乐且康，酡颜偏称锦衣裳。","栖身有分终幽隐，裕后多书遂显扬。","越水吴山钟秀气，少微南极灿祥光。","世间甲子如流水，笑展方瞳看海桑。"]},{"t":"会乐图为宗弟永寿王题","f":"七言律诗","c":["四海承平庶事康，百年雅会重藩方。","琴樽适兴排鸳序，礼乐禔身肃雁行。","更喜阿咸从阮籍，且无成义狎宁王。","天伦至乐时时有，不似兰亭一咏觞。"]},{"t":"送暹上人还京","f":"七言律诗","c":["萍水相逢岁未周，又看飞锡上神州。","梁恢针验心多感，龙树机深计莫留。","雁度碧云函谷晓，蝉鸣红树曲江秋。","临岐且莫伤怀抱，更约春风此地游。"]},{"t":"和马天禄宪副陇州简阎光甫大参","f":"七言律诗","c":["悠悠汧水带云流，白草黄沙接远洲。","风断归鸿迷别渚，霜寒落木动高秋。","番营人散城边马，野渡僧归月下舟。","独有高閒当此际，每将心迹寄菟裘。"]},{"t":"和次阎大参韵","f":"七言律诗","c":["报国曾将素志酬，乞归还爱草堂幽。","夕阳帘捲吴山碧，野渡舟横陇水流。","诗酒放怀三径地，乡园飞梦五云楼。","身閒况是心无累，半百年来未白头。"]},{"t":"和华亭道中雨晴","f":"七言律诗","c":["五花骢马鞚青丝，宪使高秋按节时。","贪吏望风争解印，远人归化纳降旗。","草间泣露蛩声切，尘外摩空鸟力疲。","景物满前骚兴在，不妨头上雨催诗。"]},{"t":"和晚渡咸阳","f":"七言律诗","c":["长堤漠漠绕晴川，芳草离离接远天。","几处夕阳林外鸟，半篙秋水渡头船。","青山伯业成馀烬，紫蔓残碑纪昔年。","薄暮行人呼愈急，短衫黄帽立沙边。"]},{"t":"寿汧阳伯父","f":"七言律诗","c":["玳瑁筵开簇绮罗，碧桃花发去年柯。","东平乐善贤名著，南极呈祥瑞彩多。","翠袂舞风鸾影细，紫箫吹月凤声和。","霞杯满进长生酒，醉看桑田起白波。"]},{"t":"送陈公辅伴读省亲入蜀时其弟进士亦归省","f":"七言律诗","c":["一别慈闱几岁寒，宦游何处问平安。","太行睥睨云飞远，栈阁崔嵬马度难。","庭下称觞尧叟至，门前衣绣季方欢。","人间家庆如君少，堂北春深雨露宽。"]},{"t":"送童世奇黄门回京","f":"七言律诗","c":["近臣承诏下銮坡，跋涉其如远道何。","鱼目混珠须辩早，角弓入酒莫疑多。","人情翻覆真堪笑，水鉴妍媸定不讹。","行色一鞭催去马，华山回首郁嵯峨。"]},{"t":"送唐虞卿郎中回京","f":"七言律诗","c":["遥持玉节下秦中，万里流云素鉴空。","曲直肯挠三尺法，咨询都付一心公。","行旌渺渺瞻燕北，驿骑萧萧过陕东。","囊里封章多少事，更期民隐达宸衷。"]},{"t":"和咏雪","f":"七言律诗","c":["六花飞舞乱西东，一白茫茫路不通。","闭户高眠穷巷客，维舟独钓破蓑翁。","川原缭绕疑琼岛，草树高低见玉丛。","最喜丰年先有兆，来麰生意已无穷。"]},{"t":"送锦衣杨千兵回京","f":"七言律诗","c":["一片清冰置玉壶，家传韬略更兼儒。","鼠牙雀角原情伪，重裤疑金定有无。","堤柳煖风飞乳燕，河桥春水泛轻凫。","香尘十里长安道，笑拂吴钩上帝都。"]},{"t":"杨化州清节卷","f":"七言律诗","c":["佐政三州蔼颂声，茧丝保障极经营。","跳梁小丑空为乱，安堵居民总不惊。","囊里肯携包拯砚，胸中元有仲淹兵。","关西家世传来久，清白端能裕后生。"]},{"t":"次杨应宁佥宪留别京师词林诸友韵 其一","f":"七言律诗","c":["三年读礼辍慈闱，还逐鹓鸾旧伴飞。","双阙制颁纶綍命，五陵士望斗山归。","青云接武天应近，绛帐传经愿不违。","留取从行清献鹤，他年堪绣上罗衣。"]},{"t":"次杨应宁佥宪留别京师词林诸友韵 其二","f":"七言律诗","c":["玺书荣捧别词林，祖帐临岐思不任。","原委早承明道派，之无幼契乐天心。","官居执法飞霜远，人喜从游立雪深。","密勿庙廊应有待，壮年谁许脱朝簪。"]},{"t":"宣庙太乙真人莲叶舟画为永寿王题","f":"七言律诗","c":["水上飘飘一叶莲，真人宴坐稳于船。","撑归泰华峰头月，梦入西湖镜里天。","冲浪不惊红雨乱，忘机常对白鸥眠。","鼎湖龙去仙踪远，遗泽空存御笔鲜。"]},{"t":"送高文明绣衣事竣还朝","f":"七言律诗","c":["榷茶奉制抚边夷，一道澄清属有为。","豸角霜威秋肃肃，乌台月影夜离离。","及瓜有待催行色，折柳无端动别思。","关陇近来凋弊甚，封章好达圣明知。"]},{"t":"送匡敬敷绣衣事竣还朝","f":"七言律诗","c":["戎政贤劳岁屡更，又持绣斧上神京。","天开魏阙双龙近，云尽长空一鹗横。","官道飞埃过雨净，驿亭残暑逐风清。","九重若问三农事，麰麦微收谷未成。"]},{"t":"题忠孝节义传为都阃王徽作","f":"七言律诗","c":["节钺防边与弟俱，一门风化重舆图。","孤忠报主今应少，双节从夫古亦无。","事母孝思恩罔极，痛姑涕泪眼将枯。","芳名美誉垂青史，留与人间作范模。"]},{"t":"送都宪陈叔振作镇宣府","f":"七言律诗","c":["边疆作镇众称宜，攀卧争缘父老痴。","宪府恤刑崇德望，都台迁秩拜恩私。","燧烽烟杳防秋远，刁斗声沈警夜迟。","旧炼石皆成五色，珍藏还待补天维。"]},{"t":"与强景明伴读","f":"七言律诗","c":["清冰无滓玉无瑕，鱼水相看鬓未华。","诗拟陶韦窥雅调，文宗韩柳擅名家。","井天典教膺儒聘，藩邸能官更汝嘉。","惭愧楚筵初设醴，何如贾谊在长沙。"]},{"t":"竹窗写兴 其一","f":"七言律诗","c":["幽轩潇洒傍宫墙，种得新筠绕画廊。","寒色满林秋淅淅，绿阴匝地晓苍苍。","小窗不雨书常润，矮榻无风簟亦凉。","一点红尘无处著，分明身世在潇湘。"]},{"t":"竹窗写兴 其二","f":"七言律诗","c":["满院琅玕绿染成，苍茫秋色弄阴晴。","如云谩作纷纷态，带雨常为簌簌声。","陆地何时无翠滴，炎天终日有寒生。","我来不是閒乘兴，共结冰霜岁晚盟。"]},{"t":"竹窗写兴 其三","f":"七言律诗","c":["一片湘云压画栏，凤毛零乱绿成团。","香生箨粉晴犹堕，翠滴苔花湿未乾。","帘影低垂秋雾薄，玉声轻弄晚风寒。","傍人莫讶耽幽兴，尽日微吟独倚阑。"]},{"t":"竹窗写兴 其四","f":"七言律诗","c":["轩居幽僻断尘纷，不种秾华种此君。","晴翠拂檐秋瑟瑟，绿阴垂地画氲氲。","满庭碎玉人空扫，半亩清风鹤共分。","读罢武公淇澳句，不知帘外已斜曛。"]},{"t":"溪上晚景","f":"七言律诗","c":["隔岸山光翠欲流，暂停骢马一遨游。","断云阁雨天将暝，老叶惊风树已秋。","争果野猿时聚散，傍船水鸟自沈浮。","垂鞭缓策归来后，诗兴无边咏未休。"]},{"t":"和韵寄日华上人 其一","f":"七言律诗","c":["几年不见佛图澄，龙象天高未许登。","西土重来思有道，亲藩分守愧无能。","曾闻心印传诸祖，更喜诗坛续九僧。","料得山居无个事，蒲团终日课莲经。"]},{"t":"和韵寄日华上人 其二","f":"七言律诗","c":["当年曾会景隆池，千里难禁别后思。","古寺春深花落后，小轩人静月明时。","寒山笑谑都成偈，无本推敲酷爱诗。","何日重来寻旧约，相逢一笑话襟期。"]},{"t":"李公堤为岳州守李文明作","f":"七言律诗","c":["洞庭湖水古今同，岳牧全收捍禦功。","耕艺有田成岁稔，往来无客叹途穷。","沿堤新柳摇金缕，傍岸长桥卧彩虹。","昭代拟脩循吏传，声华先已属观风。"]},{"t":"送李文明宪使之任河南","f":"七言律诗","c":["东陵作镇先诸郡，西岳旬宣重一方。","到处苍生沾雨露，平生清节凛冰霜。","宪台赫赫官阶峻，使节摇摇驿路长。","不道梁园还久住，居然听履上岩廊。"]},{"t":"送少司马王表伦赴京 其一","f":"七言律诗","c":["简书分陕羡贤劳，几见巡边树节旄。","战马不嘶饶苜蓿，耕农无事醉蒲萄。","三春雨露滋三辅，六籍经纶济六韬。","八座登庸还有待，好将忠赤荅恩褒。"]},{"t":"送少司马王表伦赴京 其二","f":"七言律诗","c":["遥持玉节镇长安，百辟严趋仰豸冠。","私谒不通霜满面，秋毫无犯铁为肝。","一封丹诏来春殿，三品清衔贰夏官。","幸际升平戎事少，委蛇日日侍金銮。"]},{"t":"送张应祥绣衣按治四川还朝","f":"七言律诗","c":["绣衣骢马上金台，好是西川按辔回。","甘雨一天随使节，清风千里断氛埃。","故园情思迷松菊，先陇恩光贲草莱。","五色云开双阙近，朝阳争看凤飞来。"]}]};